            </div>

            <div className="flex items-end gap-4">
              <div className="flex-1">
                <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
                  迭代次数
                </label>
                <input
                  id="iterations"
                  type="number"
