                type="text"
                value={generatedLink}
                readOnly
                className="flex-1 px-3 py-2 text-xs border border-neutral-200 dark:border-neutral-700 rounded-lg bg-neutral-50 dark:bg-neutral-800"
        aria-label="分享链接"
      />
              <button
