export function ImportShareDialog({
  open,
  onClose,
  onImport,
}: {
  open: boolean;
  onClose: () => void;
  onImport: (shareData: SharedFormula) => void;
}) {
  const [link, setLink] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const handleImport = async () => {
    if (!link) return;

    setLoading(true);
    setError(null);

    try {
      const url = new URL(link);
      const params = url.searchParams;

      const shareData: SharedFormula = {
        shareId: typeof url.pathname.split('/').pop() === 'string' ? url.pathname.split('/').pop() || '' : '',
        formulaName: typeof params.get('f') === 'string' ? params.get('f') || '未知配方' : '未知配方',
        effects:
          params
            .get('e')
            ?.split(',')
            .filter((e) => typeof e === 'string' && e)
            .map((e) => (typeof e === 'string' ? e : '未知功效')) || [],
        ingredients:
          params
            .get('i')
            ?.split(',')
            .filter((name) => typeof name === 'string' && name)
            .map((name) => ({
              name: typeof name === 'string' ? name : '未知药材',
              dosage: '-',
              role: '-',
            })) || [],
        scores: {
          synergy: parseFloat(params.get('s') || '0') || 0,
          taste: 0,
          stability: 0,
          overall: parseFloat(params.get('s') || '0') || 0,
        },
        createdAt: Date.now(),
        expiresAt: params.get('exp') ? parseInt(params.get('exp')!) : undefined,
        viewCount: 0,
      };

      onImport(shareData);
      onClose();
    } catch (err) {
      setError('无效的分享链接');
    } finally {
      setLoading(false);
    }
  };

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4">
      <Card className="w-full max-w-md p-6">
        <h3 className="text-lg font-semibold text-neutral-900 dark:text-neutral-100 mb-4">导入配方</h3>

        <div className="space-y-4">
          <input
            type="text"
            value={link}
            onChange={(e) => setLink(e.target.value)}
            placeholder="粘贴分享链接"
            className="w-full px-3 py-2 border border-neutral-200 dark:border-neutral-700 rounded-lg bg-white dark:bg-neutral-800 focus:ring-2 focus:ring-info-500 focus:border-transparent"
          />

          {link.includes('pwd=') && (
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="输入访问密码"
              className="w-full px-3 py-2 border border-neutral-200 dark:border-neutral-700 rounded-lg bg-white dark:bg-neutral-800"
            />
          )}

          {error && <p className="text-sm text-error-500">{error}</p>}

          <div className="flex justify-end gap-2">
            <button onClick={onClose} className="px-4 py-2 text-sm text-neutral-600 hover:bg-neutral-100 dark:bg-neutral-800 rounded-lg">
              取消
            </button>
            <button
              onClick={handleImport}
              disabled={!link || loading}
              className="px-4 py-2 text-sm bg-info-500 text-white rounded-lg hover:bg-info-600 disabled:opacity-50"
            >
              {loading ? '导入中...' : '导入'}
            </button>
          </div>
        </div>
      </Card>
    </div>
  );
}

