                        {log.details && Object.keys(log.details).length > 0 && (
                          <div className="mt-1 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] font-mono break-all">
                            {JSON.stringify(log.details)}
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </>
            )}
          </div>
        )}
      </div>
    </Card>
