import { Select, Slider } from '@/components/ui'
import { Brain, ChevronDown, ChevronUp } from 'lucide-react'
import type { ModelType } from '@/api/modelClient'

interface ModelSelectorProps {
  modelType: ModelType
  onModelChange: (modelType: ModelType) => void
  onParamsChange: (params: Record<string, any>) => void
  className?: string
}

interface ModelOption {
  value: ModelType
  label: string
  description: string
  icon: React.ReactNode
}

export function ModelSelector({ modelType, onModelChange, onParamsChange, className }: ModelSelectorProps) {
  const [showParams, setShowParams] = useState(false)
  const [params, setParams] = useState({
    temperature: 0.7,
    maxTokens: 1000,
    topP: 0.9,
    frequencyPenalty: 0,
    presencePenalty: 0,
  })

  const modelOptions: ModelOption[] = [
    { value: 'formula_gpt',   label: 'FormulaGPT',  description: '配方生成模型', icon: <Brain className="w-4 h-4" /> },
    { value: 'synergy_net',   label: 'SynergyNet',  description: '协同分析模型', icon: <Brain className="w-4 h-4" /> },
    { value: 'safety_checker',label: 'SafetyChecker',description: '安全检查模型', icon: <Brain className="w-4 h-4" /> },
    { value: 'taste_predictor',label: 'TastePredictor',description: '口感预测模型', icon: <Brain className="w-4 h-4" /> },
    { value: 'stability_model',label: 'StabilityModel',description: '稳定性预测模型', icon: <Brain className="w-4 h-4" /> },
  ]

  const handleParamChange = (key: string, value: any) => {
    const newParams = { ...params, [key]: value }
    setParams(newParams)
    onParamsChange(newParams)
  }

  return (
    // Card default: p-5 (20px), rounded-xl, shadow-sm — matches parent page
    <Card className={`shadow-sm border border-[var(--border-color)] bg-white dark:bg-neutral-900 ${className}`}>
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          {/* icon: rounded-xl w-10 h-10 — matches SectionHeader icon pattern */}
          <div className="w-10 h-10 rounded-xl bg-primary-100 dark:bg-primary-300/25 flex items-center justify-center flex-shrink-0">
            <Brain className="w-5 h-5 text-primary-700 dark:text-primary-700" />
          </div>
          <div>
            {/* text-sm font-semibold — matches StatCard label pattern (was font-semibold=500) */}
            <h3 className="text-sm font-semibold text-[var(--text-primary)] dark:text-white leading-tight">模型选择</h3>
            <p className="text-xs text-[var(--text-muted)] leading-tight mt-0.5">选择和配置 AI 模型</p>
          </div>
        </div>
        <button
          onClick={() => setShowParams(!showParams)}
          className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-normal text-[var(--text-secondary)] border border-[var(--border-color)] bg-white dark:bg-neutral-900 hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors duration-150"
        >
          {showParams ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
          {showParams ? '收起参数' : '调节参数'}
        </button>
      </div>

      <div className="mt-4 space-y-4">
        <div className="space-y-1.5">
          <label className="text-sm font-semibold text-[var(--text-secondary)] block">模型类型</label>
          <Select value={modelType} onChange={(v) => onModelChange(v as ModelType)}>
            {modelOptions.map((option) => (
              <option key={option.value} value={option.value}>
                {option.label} - {option.description}
              </option>
            ))}
          </Select>
        </div>

        {showParams && (
          <div className="space-y-4 pt-4 border-t border-[var(--border-color)]">
            {[
              { key: 'temperature', label: '温度 (Temperature)', min: 0, max: 1, step: 0.01, display: 'toFixed(2)', low: '0.0 (确定)', high: '1.0 (随机)' },
              { key: 'maxTokens',   label: '最大 Tokens',       min: 100, max: 4000, step: 100, display: '', low: '100', high: '4000' },
              { key: 'topP',        label: 'Top P',              min: 0.1, max: 1, step: 0.01, display: 'toFixed(2)', low: '0.1', high: '1.0' },
            ].map(({ key, label, min, max, step, display, low, high }) => (
              <div key={key} className="space-y-1.5">
                <div className="flex items-center justify-between">
                  <label className="text-sm font-semibold text-[var(--text-secondary)]">{label}</label>
                  <span className="text-xs text-[var(--text-muted)]">
                    {display === 'toFixed(2)' ? params[key as keyof typeof params]?.toFixed?.(2) : params[key as keyof typeof params]}
                  </span>
                </div>
                <Slider
                  value={params[key as keyof typeof params] as number}
                  min={min} max={max} step={step}
                  onChange={(value) => handleParamChange(key, value)}
                  className="w-full"
                />
                <div className="flex justify-between text-xs text-[var(--text-muted)]">
                  <span>{low}</span><span>{high}</span>
                </div>
              </div>
            ))}

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              {[
                { key: 'frequencyPenalty', label: '频率惩罚', min: -2, max: 2, step: 0.1 },
                { key: 'presencePenalty', label: '存在惩罚', min: -2, max: 2, step: 0.1 },
              ].map(({ key, label, min, max, step }) => (
                <div key={key} className="space-y-1.5">
                  <div className="flex items-center justify-between">
                    <label className="text-sm font-semibold text-[var(--text-secondary)]">{label}</label>
                    <span className="text-xs text-[var(--text-muted)]">
                      {params[key as keyof typeof params]?.toFixed?.(2)}
                    </span>
                  </div>
                  <Slider
                    value={params[key as keyof typeof params] as number}
                    min={min} max={max} step={step}
                    onChange={(value) => handleParamChange(key, value)}
                    className="w-full"
                  />
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </Card>
  )
}

export default ModelSelector

import { useState } from 'react';
import { Card, Badge, Button } from '@/components/ui';
import { Brain, TrendingUp, TrendingDown, Minus, AlertTriangle, CheckCircle, ArrowUpDown } from 'lucide-react';
import type { AICandidate } from '@/api/ai';

interface MultiCandidateCompareProps {
  candidates: AICandidate[];
  onSelectCandidate?: (candidate: AICandidate) => void;
  selectedIndex?: number;
}

interface CompareResult {
  dimension: string;
  values: number[];
  bestIndex: number;
  differences: ('up' | 'down' | 'same')[];
}

export function MultiCandidateCompare({ candidates, onSelectCandidate, selectedIndex }: MultiCandidateCompareProps) {
  const [hoveredRow, setHoveredRow] = useState<string | null>(null);

  if (!candidates || candidates.length < 2) {
    return (
      <Card className="p-6 text-center text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
        <p className="text-sm">需要至少2个候选方案才能进行对比分析</p>
      </Card>
    );
  }

  const scoreDimensions: { key: keyof AICandidate; label: string; format?: (v: any) => string }[] = [
    { key: 'overall_score', label: '综合评分', format: (v) => (v != null ? (v as number).toFixed(3) : '-') },
    { key: 'synergy_score', label: '协同评分', format: (v) => (v != null ? (v as number).toFixed(3) : '-') },
    { key: 'taste_score', label: '口感评分', format: (v) => (v != null ? (v as number).toFixed(3) : '-') },
    { key: 'stability_score', label: '稳定性', format: (v) => (v != null ? (v as number).toFixed(3) : '-') },
  ];

  const safetyOk = candidates.map((c) => c.safety_passed);
  const herbCounts = candidates.map((c) => c.herb_combination?.length ?? 0);
  const peptideCounts = candidates.map((c) => c.peptide_candidates?.length || 0);

  const compareValues = (values: number[]): CompareResult => {
    const bestIndex = values.reduce((bestIdx, val, idx, arr) => (val > arr[bestIdx] ? idx : bestIdx), 0);
    const differences = values.map((v) => (v > values[bestIndex] ? 'down' : v < values[bestIndex] ? 'up' : 'same'));
    return {
      dimension: '',
      values,
      bestIndex,
      differences,
    };
  };

  const overallScores = candidates.map((c) => c.overall_score ?? 0);
  const synergyScores = candidates.map((c) => c.synergy_score ?? 0);
  const tasteScores = candidates.map((c) => c.taste_score ?? 0);
  const stabilityScores = candidates.map((c) => c.stability_score ?? 0);

  const overallCompare = compareValues(overallScores);
  const synergyCompare = compareValues(synergyScores);
  const tasteCompare = compareValues(tasteScores);
  const stabilityCompare = compareValues(stabilityScores);

  const getDifferenceIcon = (diff: 'up' | 'down' | 'same') => {
    switch (diff) {
      case 'up':
        return <TrendingUp className="w-3 h-3 text-danger-500" />;
      case 'down':
        return <TrendingDown className="w-3 h-3 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />;
      default:
        return <Minus className="w-3 h-3 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />;
    }
  };

  const getCellClass = (diff: 'up' | 'down' | 'same', isBest: boolean) => {
    const baseClass = 'text-center px-3 py-2 text-sm';
    if (isBest && diff === 'same') {
      return `${baseClass} bg-success-50/50 dark:bg-success-300/20 font-semibold text-success-600`;
    }
    if (diff === 'up') {
      return `${baseClass} bg-danger-50/30 dark:bg-danger-300/15 text-danger-600 dark:text-danger-600`;
    }
    if (diff === 'down') {
      return `${baseClass} text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]`;
    }
    return `${baseClass} text-neutral-600 dark:text-neutral-400`;
  };

  const getHerbRoleSet = (candidate: AICandidate) => {
    const roles: Record<string, Set<string>> = { 君: new Set(), 臣: new Set(), 佐: new Set(), 使: new Set() };
    candidate.herb_combination?.forEach((h) => {
      const role = typeof h.role === 'string' ? h.role : '';
      const name = typeof h.name === 'string' ? h.name : '未知药材';
      if (/君/i.test(role)) roles['君'].add(name);
      else if (/臣/i.test(role)) roles['臣'].add(name);
      else if (/佐/i.test(role)) roles['佐'].add(name);
      else if (/使/i.test(role)) roles['使'].add(name);
    });
    return roles;
  };

  const candidate1Roles = getHerbRoleSet(candidates[0]);
  const candidate2Roles = getHerbRoleSet(candidates[1]);

  const getRoleDifferences = () => {
    const diffs: { type: 'added' | 'removed' | 'changed'; herb?: string; role?: string; text: string }[] = [];
    ['君', '臣', '佐', '使'].forEach((role) => {
      const set1 =
        role === '君'
          ? candidate1Roles['君']
          : role === '臣'
            ? candidate1Roles['臣']
            : role === '佐'
              ? candidate1Roles['佐']
              : candidate1Roles['使'];
      const set2 =
        role === '君'
          ? candidate2Roles['君']
          : role === '臣'
            ? candidate2Roles['臣']
            : role === '佐'
              ? candidate2Roles['佐']
              : candidate2Roles['使'];

      const added = [...set2].filter((x) => !set1.has(x));
      const removed = [...set1].filter((x) => !set2.has(x));

      added.forEach((h) => diffs.push({ type: 'added', herb: h, role, text: `方案二增加${role}药 ${h}` }));
      removed.forEach((h) => diffs.push({ type: 'removed', herb: h, role, text: `方案一独有${role}药 ${h}` }));
    });
    return diffs;
  };

  const roleDiffs = candidates.length === 2 ? getRoleDifferences() : [];

  return (
    <Card className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Brain className="w-5 h-5 text-primary-500" />
          <h3 className="font-semibold">候选方案对比</h3>
        </div>
        <Badge variant="neutral" size="sm">
          {candidates.length} 套方案
        </Badge>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full border-collapse">
          <thead>
            <tr className="bg-gradient-to-r from-primary-50 to-primary-100/50 dark:from-primary-900/20 dark:to-primary-800/10">
              <th className="px-4 py-3 text-left text-xs font-bold text-primary-800 dark:text-primary-200 border-b-2 border-primary-300 dark:border-primary-600">
                指标
              </th>
              {candidates.map((c, i) => (
                <th
                  key={i}
                  className={`px-4 py-3 text-center text-xs font-bold border-b-2 border-primary-300 dark:border-primary-600 ${
                    selectedIndex === i
                      ? 'bg-primary-100/50 dark:bg-primary-300/25 text-primary-700 dark:text-primary-700'
                      : 'text-primary-800 dark:text-primary-200'
                  }`}
                >
                  <div className="space-y-1">
                    <div className="flex items-center justify-center gap-1">
                      <Brain className="w-3 h-3" />
                      <span>方案 {i + 1}</span>
                    </div>
                    <div className="text-sm font-semibold">
                      {typeof c.formula_name === 'string' ? c.formula_name : '未知配方'}
                    </div>
                  </div>
                </th>
              ))}
              <th className="px-4 py-3 text-center text-xs font-bold text-primary-800 dark:text-primary-200 border-b-2 border-primary-300 dark:border-primary-600">
                <div className="flex items-center justify-center gap-1">
                  <ArrowUpDown className="w-3 h-3" />
                  差异分析
                </div>
              </th>
            </tr>
          </thead>
          <tbody>
            {scoreDimensions.map((dim, dimIdx) => {
              const compare =
                dimIdx === 0
                  ? overallCompare
                  : dimIdx === 1
                    ? synergyCompare
                    : dimIdx === 2
                      ? tasteCompare
                      : stabilityCompare;
              const values =
                dimIdx === 0
                  ? overallScores
                  : dimIdx === 1
                    ? synergyScores
                    : dimIdx === 2
                      ? tasteScores
                      : stabilityScores;

              return (
                <tr
                  key={dim.key}
                  className={`${dimIdx % 2 === 0 ? 'bg-white dark:bg-neutral-800' : 'bg-neutral-50/50 dark:bg-neutral-900/30'} hover:bg-primary-50/20 transition-colors`}
                >
                  <td className="px-4 py-3 text-sm font-medium text-neutral-700 dark:text-neutral-300 border-r border-neutral-100 dark:border-neutral-700">
                    {dim.label}
                  </td>
                  {values.map((val, i) => (
                    <td
                      key={i}
                      className={`${getCellClass(compare.differences[i], i === compare.bestIndex)} border-r border-neutral-100 dark:border-neutral-700`}
                    >
                      <div className="flex items-center justify-center gap-1">
                        {getDifferenceIcon(compare.differences[i])}
                        <span>{dim.format ? dim.format(val) : val}</span>
                      </div>
                    </td>
                  ))}
                  <td className="px-4 py-3 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] text-center">
                    {compare.differences.filter((d) => d === 'up').length > 0 && (
                      <span className="text-danger-500">
                        方案 {compare.differences.findIndex((d) => d === 'up') + 1} 更优
                      </span>
                    )}
                    {compare.differences.every((d) => d === 'same') && <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">持平</span>}
                  </td>
                </tr>
              );
            })}

            <tr className={`bg-white dark:bg-neutral-800 hover:bg-primary-50/20 transition-colors`}>
              <td className="px-4 py-3 text-sm font-medium text-neutral-700 dark:text-neutral-300 border-r border-neutral-100 dark:border-neutral-700">
                安全状态
              </td>
              {safetyOk.map((ok, i) => (
                <td key={i} className="px-4 py-3 text-center border-r border-neutral-100 dark:border-neutral-700">
                  {ok ? (
                    <span className="inline-flex items-center gap-1 text-success-600 text-sm">
                      <CheckCircle className="w-4 h-4" /> 安全
                    </span>
                  ) : (
                    <span className="inline-flex items-center gap-1 text-warning-600 text-sm">
                      <AlertTriangle className="w-4 h-4" /> 预警
                    </span>
                  )}
                </td>
              ))}
              <td className="px-4 py-3 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] text-center">
                {safetyOk[0] !== safetyOk[1] && (
                  <Badge variant="warning" size="sm">
                    安全状态不同
                  </Badge>
                )}
                {safetyOk[0] === safetyOk[1] && <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">状态一致</span>}
              </td>
            </tr>

            <tr className={`bg-neutral-50/50 dark:bg-neutral-900/30 hover:bg-primary-50/20 transition-colors`}>
              <td className="px-4 py-3 text-sm font-medium text-neutral-700 dark:text-neutral-300 border-r border-neutral-100 dark:border-neutral-700">
                药材数量
              </td>
              {herbCounts.map((count, i) => (
                <td
                  key={i}
                  className="px-4 py-3 text-center text-sm text-neutral-600 dark:text-neutral-400 border-r border-neutral-100 dark:border-neutral-700"
                >
                  {count} 味
                </td>
              ))}
              <td className="px-4 py-3 text-xs text-center">
                {herbCounts[0] !== herbCounts[1] && (
                  <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">相差 {Math.abs(herbCounts[0] - herbCounts[1])} 味</span>
                )}
                {herbCounts[0] === herbCounts[1] && <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">数量相同</span>}
              </td>
            </tr>

            <tr className={`bg-white dark:bg-neutral-800 hover:bg-primary-50/20 transition-colors`}>
              <td className="px-4 py-3 text-sm font-medium text-neutral-700 dark:text-neutral-300 border-r border-neutral-100 dark:border-neutral-700">
                活性肽
              </td>
              {peptideCounts.map((count, i) => (
                <td
                  key={i}
                  className="px-4 py-3 text-center text-sm text-neutral-600 dark:text-neutral-400 border-r border-neutral-100 dark:border-neutral-700"
                >
                  {count} 个
                </td>
              ))}
              <td className="px-4 py-3 text-xs text-center">
                {peptideCounts[0] !== peptideCounts[1] && (
                  <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">相差 {Math.abs(peptideCounts[0] - peptideCounts[1])} 个</span>
                )}
                {peptideCounts[0] === peptideCounts[1] && <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">数量相同</span>}
              </td>
            </tr>
          </tbody>
        </table>
      </div>

      {roleDiffs.length > 0 && (
        <div className="border-t border-neutral-200 dark:border-neutral-700 pt-4">
          <h4 className="text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-3 flex items-center gap-2">
            <AlertTriangle className="w-4 h-4 text-warning-500" />
            配方组成差异分析
          </h4>
          <div className="space-y-2">
            {roleDiffs.map((diff, i) => (
              <div
                key={i}
                className={`flex items-center gap-2 text-xs px-3 py-2 rounded-lg ${
                  diff.type === 'added'
                    ? 'bg-success-50/50 dark:bg-success-300/20 text-success-600 dark:text-success-600'
                    : 'bg-danger-50/50 dark:bg-danger-300/20 text-danger-600 dark:text-danger-600'
                }`}
              >
                {diff.type === 'added' ? <TrendingUp className="w-3 h-3" /> : <TrendingDown className="w-3 h-3" />}
                <span>{diff.text}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {candidates.length > 2 && (
        <div className="border-t border-neutral-200 dark:border-neutral-700 pt-4">
          <h4 className="text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-3">药材组成</h4>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {candidates.map((c, i) => (
              <div key={i} className="bg-neutral-50/50 dark:bg-neutral-800/50 rounded-lg p-3">
                <div className="text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-2">
                  方案 {i + 1}: {typeof c.formula_name === 'string' ? c.formula_name : '未知配方'}
                </div>
                <div className="space-y-1">
                  {(c.herb_combination ?? []).map((h, j) => (
                    <div key={j} className="flex items-center justify-between text-xs">
                      <span className="text-neutral-600 dark:text-neutral-400">
                        {typeof h.name === 'string' ? h.name : '未知药材'}
                      </span>
                      <Badge variant="neutral" size="sm">
                        {typeof h.role === 'string' ? h.role : '其他'}
                      </Badge>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="flex justify-center gap-3 pt-2">
        {candidates.map((c, i) => (
          <Button
            key={i}
            variant={selectedIndex === i ? 'primary' : 'secondary'}
            size="sm"
            onClick={() => onSelectCandidate?.(c)}
          >
            选择方案 {i + 1}
          </Button>
        ))}
      </div>
    </Card>
  );
}

export default MultiCandidateCompare;

/**
 * 多维度参数调整组件
 * 支持精细化的剂量、口感、安全性等参数配置
 */
import { useState, useCallback, useMemo } from 'react'
import { Card } from '@/components/ui'
import { Sliders, Save, RotateCcw, ChevronDown, ChevronUp } from 'lucide-react'
import { useUserPreferenceStore } from '@/stores/userPreferenceStore'

interface ParameterConfig {
  id: string
  name: string
  value: number
  min: number
  max: number
  step: number
  unit: string
  description: string
}

interface TasteProfile {
  sweetness: number
  bitterness: number
  astringency: number
  umami: number
}

interface SafetyConfig {
  level: number
  excludeRestricted: boolean
  minSafetyScore: number
}

interface CostConfig {
  minCost: number
  maxCost: number
  optimizeCost: boolean
}

interface ParameterAdjustPanelProps {
  onParameterChange?: (params: {
    tasteProfile: TasteProfile
    safety: SafetyConfig
    cost: CostConfig
  }) => void
  expanded?: boolean
  onToggle?: () => void
}

const DEFAULT_TASTE: TasteProfile = {
  sweetness: 0.5,
  bitterness: 0.3,
  astringency: 0.2,
  umami: 0.4,
}

const DEFAULT_SAFETY: SafetyConfig = {
  level: 0.8,
  excludeRestricted: true,
  minSafetyScore: 0.7,
}

const DEFAULT_COST: CostConfig = {
  minCost: 0,
  maxCost: 1000,
  optimizeCost: false,
}

export function ParameterAdjustPanel({
  onParameterChange,
  expanded = false,
  onToggle,
}: ParameterAdjustPanelProps) {
  const { preferences, updatePreferences } = useUserPreferenceStore()

  const [tasteProfile, setTasteProfile] = useState<TasteProfile>({
    sweetness: preferences.tasteProfile?.sweetness ?? DEFAULT_TASTE.sweetness,
    bitterness: preferences.tasteProfile?.bitterness ?? DEFAULT_TASTE.bitterness,
    astringency: preferences.tasteProfile?.astringency ?? DEFAULT_TASTE.astringency,
    umami: preferences.tasteProfile?.umami ?? DEFAULT_TASTE.umami,
  })

  const [safety, setSafety] = useState<SafetyConfig>({
    level: preferences.safetyLevel ?? DEFAULT_SAFETY.level,
    excludeRestricted: true,
    minSafetyScore: 0.7,
  })

  const [cost, setCost] = useState<CostConfig>(DEFAULT_COST)

  const [savedTemplates, setSavedTemplates] = useState<{ name: string; taste: TasteProfile; safety: SafetyConfig }[]>([])

  const handleTasteChange = useCallback((key: keyof TasteProfile, value: number) => {
    const updated = { ...tasteProfile, [key]: value }
    setTasteProfile(updated)
    updatePreferences({ tasteProfile: updated })
    onParameterChange?.({ tasteProfile: updated, safety, cost })
  }, [tasteProfile, safety, cost, onParameterChange, updatePreferences])

  const handleSafetyChange = useCallback((updates: Partial<SafetyConfig>) => {
    const updated = { ...safety, ...updates }
    setSafety(updated)
    updatePreferences({ safetyLevel: updated.level })
    onParameterChange?.({ tasteProfile, safety: updated, cost })
  }, [tasteProfile, safety, cost, onParameterChange, updatePreferences])

  const handleCostChange = useCallback((updates: Partial<CostConfig>) => {
    const updated = { ...cost, ...updates }
    setCost(updated)
    onParameterChange?.({ tasteProfile, safety, cost: updated })
  }, [tasteProfile, safety, cost, onParameterChange])

  const handleReset = useCallback(() => {
    setTasteProfile(DEFAULT_TASTE)
    setSafety(DEFAULT_SAFETY)
    setCost(DEFAULT_COST)
    updatePreferences({
      tasteProfile: DEFAULT_TASTE,
      safetyLevel: DEFAULT_SAFETY.level,
    })
    onParameterChange?.({ tasteProfile: DEFAULT_TASTE, safety: DEFAULT_SAFETY, cost: DEFAULT_COST })
  }, [onParameterChange, updatePreferences])

  const handleSaveTemplate = useCallback(() => {
    const name = `模板 ${savedTemplates.length + 1}`
    setSavedTemplates((prev) => [...prev, { name, taste: tasteProfile, safety }])
  }, [tasteProfile, safety, savedTemplates.length])

  const handleLoadTemplate = useCallback((template: { name: string; taste: TasteProfile; safety: SafetyConfig }) => {
    setTasteProfile(template.taste)
    setSafety(template.safety)
    updatePreferences({ tasteProfile: template.taste, safetyLevel: template.safety.level })
    onParameterChange?.({ tasteProfile: template.taste, safety: template.safety, cost })
  }, [cost, onParameterChange, updatePreferences])

  const tasteScore = useMemo(() => {
    const total = tasteProfile.sweetness + tasteProfile.bitterness + tasteProfile.astringency + tasteProfile.umami
    return total > 0 ? (tasteProfile.sweetness - tasteProfile.bitterness + 0.5) / 1.5 : 0.5
  }, [tasteProfile])

  return (
    <Card className="overflow-hidden">
