  '延缓衰老': 7,
  '促进消化': 7,
  '安神': 7.5,
}

const SYNERGY_PAIRS: Record<string, { score: number; mechanism: string }> = {
  '人参-黄芪': { score: 9.2, mechanism: '补气相须为用，增强免疫功能' },
  '黄芪-当归': { score: 9.0, mechanism: '气血双补，协同增效' },
