          </div>
        </div>
      )}

      {section.content?.dataSource && (
        <div className="text-sm text-neutral-500 dark:text-neutral-400 pt-4 border-t border-neutral-200 dark:border-neutral-700">
          <strong>数据来源：</strong>{section.content.dataSource}
