      description: '激活免疫细胞活性',
      evidenceLevel: 'predicted',
      confidence: 78,
    })
    mediumTermEffects.push({
      category: '免疫系统',
      description: '建立免疫记忆，增强防御能力',
      evidenceLevel: 'predicted',
      confidence: 72,
    })
