export default FormulaExplanationModal

/**
 * FormulaExplanationPanel - 配方智能方解面板
 *
 * @description 调用后端 /ai/interpret 端点，基于网络药理学与中医理论生成方解
 * @version 1.0.0
 */
import { useState, useEffect } from 'react'
import { Loader2, FlaskConical, Shield, Lightbulb, Clock } from 'lucide-react'
import { aiApi } from '@/api/ai'
import type { AICandidate } from '@/api/ai'
import { Card } from '@/components/ui'

interface FormulaExplanationPanelProps {
  candidate: AICandidate
  targetEffects: string[]
  onClose: () => void
}

type Interpretation = {
  constitution?: string
  mechanism?: Array<{ herb: string; effects: string[]; compounds: Array<{ name: string; mol_weight?: string | number }>; targets: string[]; diseases: string[]; note: string }>
  synergy?: string
  safety?: { food_homology_ratio: string; risk_level: string; notes: string[] }
  usage?: { form: string; dosage_summary: string; frequency: string; course: string; adjustment_hint: string }
  monitoring?: Array<{ effect: string; metric: string; frequency: string }>
  disclaimer?: string
}

export function FormulaExplanationPanel({ candidate, targetEffects, onClose }: FormulaExplanationPanelProps) {
  const [interp, setInterp] = useState<Interpretation | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    let cancelled = false
    const load = async () => {
      setLoading(true)
      setError(null)
      try {
        const herbs = (candidate.herb_combination || []).map((h: any) => ({
          name: h.name || '',
          dosage_g: Number(h.dosage_g ?? h.dosage ?? h.dose_g ?? 0),
          role: h.role || '',
        }))
        const res = await aiApi.interpretFormula({
          formula_name: candidate.formula_name || candidate.name || '',
          herbs,
          target_effects: targetEffects,
        })
        if (!cancelled) setInterp((res.interpretation || {}) as Interpretation)
      } catch (e) {
        if (!cancelled) setError(e instanceof Error ? e.message : '解释服务暂不可用')
      } finally {
        if (!cancelled) setLoading(false)
      }
    }
    load()
    return () => { cancelled = true }
  }, [candidate, targetEffects])

  return (
    <Card className="p-4 space-y-3">
      <div className="flex items-center justify-between">
        <h3 className="text-title-sm font-semibold flex items-center gap-1.5">
          <FlaskConical className="w-4 h-4 text-primary" />
          配方方解与机理
        </h3>
        <button onClick={onClose} className="text-caption text-muted-foreground hover:text-foreground">关闭</button>
      </div>

      {loading && (
        <div className="flex items-center gap-2 text-caption text-muted-foreground py-4">
          <Loader2 className="w-4 h-4 animate-spin" /> 正在生成方解…
        </div>
      )}

      {error && (
        <div className="rounded-lg bg-danger/10 border border-danger/20 p-3 text-caption text-danger">{error}</div>
      )}

      {!loading && !error && interp && (
        <div className="space-y-3 text-body-sm">
          {interp.constitution && (
            <div>
              <h4 className="text-caption font-semibold text-primary mb-1 flex items-center gap-1"><Lightbulb className="w-3 h-3" />君臣佐使结构</h4>
              <p className="text-muted-foreground">{interp.constitution}</p>
            </div>
          )}

          {interp.mechanism && interp.mechanism.length > 0 && (
            <div>
              <h4 className="text-caption font-semibold text-primary mb-1">现代药理机制</h4>
              <ul className="space-y-1.5">
                {interp.mechanism.map((m, i) => (
                  <li key={i} className="rounded-lg bg-muted/50 p-2.5">
                    <span className="font-semibold">{m.herb}</span>
                    {m.compounds?.length > 0 && (
                      <p className="text-caption text-muted-foreground">活性成分：{m.compounds.map(c => c.name).filter(Boolean).join('、')}</p>
                    )}
                    {m.targets?.length > 0 && (
                      <p className="text-caption text-muted-foreground">作用靶点：{m.targets.join('、')}</p>
                    )}
                    <p className="text-caption text-muted-foreground mt-1">{m.note}</p>
                  </li>
                ))}
              </ul>
            </div>
          )}

          {interp.synergy && (
            <div>
              <h4 className="text-caption font-semibold text-primary mb-1">配伍协同效应</h4>
              <p className="text-muted-foreground">{interp.synergy}</p>
            </div>
          )}

          {interp.safety && (
            <div>
              <h4 className="text-caption font-semibold text-primary mb-1 flex items-center gap-1"><Shield className="w-3 h-3" />安全性评估</h4>
              <p className="text-caption text-muted-foreground">药食同源占比 {interp.safety.food_homology_ratio} · 风险等级 {interp.safety.risk_level}</p>
              <ul className="text-caption text-muted-foreground mt-1 list-disc pl-4">
                {(interp.safety.notes || []).map((n, i) => <li key={i}>{n}</li>)}
              </ul>
            </div>
          )}

          {interp.usage && (
            <div>
              <h4 className="text-caption font-semibold text-primary mb-1 flex items-center gap-1"><Clock className="w-3 h-3" />用法用量</h4>
              <p className="text-muted-foreground">{interp.usage.form} · {interp.usage.dosage_summary} · {interp.usage.frequency}</p>
              <p className="text-caption text-muted-foreground">{interp.usage.course}。{interp.usage.adjustment_hint}</p>
            </div>
          )}

          {interp.monitoring && interp.monitoring.length > 0 && (
            <div>
              <h4 className="text-caption font-semibold text-primary mb-1">效果监测指标</h4>
              <ul className="text-caption text-muted-foreground space-y-1">
                {interp.monitoring.map((m, i) => (
                  <li key={i}>「{m.effect}」：{m.metric}（{m.frequency}）</li>
                ))}
              </ul>
            </div>
          )}

          {interp.disclaimer && (
            <p className="text-caption text-muted-foreground/70 border-t border-border pt-2">{interp.disclaimer}</p>
          )}
        </div>
      )}
    </Card>
  )
}

export default FormulaExplanationPanel

import React, { useCallback, useMemo, Suspense, lazy } from 'react';
import { useTranslation } from 'react-i18next';
import { Filter, Lightbulb, Share2, FileText, GitBranch } from 'lucide-react';
import { Badge } from '@/components/ui';
import { NeuralResultCard } from '@/components/ai/NeuralResultCard';
import { MultiCandidateCompare } from '@/components/ai/MultiCandidateCompare';
import { ResultsViewSwitcher } from './ResultsViewSwitcher';
import { DEFAULTS, FORMULA_CATEGORIES } from '@/config';
import { type FormulaCategory } from '../config/generateTabConfig';
import { logger } from '@/utils/safeLogger';
import type { AICandidate } from '@/api/ai';
import type { GeneratorType, ViewMode } from '../config/generateTabConfig';

const OptimizationAdvisor = lazy(() =>
  import('@/components/ai/OptimizationAdvisor').then((module) => ({
    default: module.OptimizationAdvisor,
  })),
);
const FormulaSharePanel = lazy(() =>
  import('@/components/ai/FormulaSharePanel').then((module) => ({
    default: module.FormulaSharePanel,
  })),
);

interface FormulaResultsProps {
  generateResult: AICandidate[] | null;
  generator: GeneratorType;
  viewMode: ViewMode;
  onViewModeChange: (mode: ViewMode) => void;
  selectedCategory: FormulaCategory | 'all';
  onCategoryChange: (cat: FormulaCategory | 'all') => void;
  sortBy: 'score' | 'name' | 'synergy';
  sortOrder: 'asc' | 'desc';
  onToggleSort: (sort: 'score' | 'name' | 'synergy') => void;
  filteredResults: AICandidate[];
  formulaCategories: { id: FormulaCategory; label: string; color: string }[];
  onViewReport: (candidate: AICandidate) => void;
  onSelectCandidate: (candidate: AICandidate) => void;
  selectedCompareIndex: number | undefined;
  onExportFormula: (format: 'json' | 'csv' | 'pdf') => void;
  effectLabels: string[];
  onCompareVersions?: (v1: number, v2: number) => void;
}

export const FormulaResults: React.FC<FormulaResultsProps> = ({
  generateResult,
  generator,
  viewMode,
  onViewModeChange,
  selectedCategory,
  onCategoryChange,
  sortBy,
  sortOrder,
  onToggleSort,
  filteredResults,
  formulaCategories,
  onViewReport,
  onSelectCandidate,
  selectedCompareIndex,
  onExportFormula,
  effectLabels,
  onCompareVersions,
}) => {
  // ===== i18n =====
  const { t } = useTranslation();

  const [showOptimizationAdvisor, setShowOptimizationAdvisor] = React.useState(false);
  const [showSharePanel, setShowSharePanel] = React.useState(false);

  const safeExtractFormulaData = useCallback((candidate: AICandidate | null | undefined) => {
    if (!candidate) {
      return {
        formulaName: DEFAULTS.PLACEHOLDER_TEXTS.UNKNOWN_FORMULA,
        effects: [] as string[],
        ingredients: [] as { name: string; dosage: string; role: string }[],
        scores: {
          synergy: 0,
          taste: DEFAULTS.DEFAULT_TASTE_SCORE,
          stability: DEFAULTS.DEFAULT_STABILITY_SCORE,
          safety: DEFAULTS.DEFAULT_SAFETY_SCORE,
          cost: DEFAULTS.DEFAULT_COST_SCORE,
          overall: 0,
        },
      };
    }

    const herbCombination = candidate.herb_combination || [];
    const HERB_ROLES = ['君药', '臣药', '佐药', '使药'] as const;

    return {
      formulaName:
        typeof candidate.formula_name === 'string'
          ? candidate.formula_name
          : DEFAULTS.PLACEHOLDER_TEXTS.UNKNOWN_FORMULA,
      ingredients: herbCombination.map((h: any, i: number) => ({
        name: typeof h.name === 'string' ? h.name : DEFAULTS.PLACEHOLDER_TEXTS.UNKNOWN_INGREDIENT,
        dosage: h.dosage || DEFAULTS.DEFAULT_DOSAGE_RANGE,
        role: HERB_ROLES[i % HERB_ROLES.length],
      })),
      scores: {
        synergy: candidate.synergy_score || 0,
        taste: ((candidate as unknown) as Record<string, unknown>).taste_score as number || DEFAULTS.DEFAULT_TASTE_SCORE,
        stability: ((candidate as unknown) as Record<string, unknown>).stability_score as number || DEFAULTS.DEFAULT_STABILITY_SCORE,
        safety: ((candidate as unknown) as Record<string, unknown>).safety_score as number || DEFAULTS.DEFAULT_SAFETY_SCORE,
        cost: ((candidate as unknown) as Record<string, unknown>).cost_score as number || DEFAULTS.DEFAULT_COST_SCORE,
        overall: ((candidate as unknown) as Record<string, unknown>).overall_score as number || candidate.synergy_score || 0,
      },
    };
  }, []);

  const getGeneratorBadgeVariant = useMemo(() => {
    switch (generator) {
      case 'llm':
        return 'primary';
      case 'neural_network':
        return 'danger';
      case 'ga':
        return 'primary';
      default:
        return 'neutral';
    }
  }, [generator]);

  const getGeneratorBadgeLabel = useMemo(() => {
    switch (generator) {
      case 'llm':
        return DEFAULTS.PLACEHOLDER_TEXTS.BADGE_AI_MODEL;
      case 'neural_network':
        return DEFAULTS.PLACEHOLDER_TEXTS.BADGE_NEURAL_NETWORK;
      case 'ga':
        return '遗传算法优化';
      default:
        return DEFAULTS.PLACEHOLDER_TEXTS.BADGE_RULE_ENGINE;
    }
  }, [generator]);

  return (
    <div className="space-y-6 animate-slide-up">
      <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4">
        <div>
          <div className="flex items-center gap-2">
            <h3 className="text-lg font-semibold" style={{ color: 'var(--color-primary-600)' }}>
              {`${DEFAULTS.PLACEHOLDER_TEXTS.RESULT_COUNT_PREFIX} ${generateResult?.length || 0} ${DEFAULTS.PLACEHOLDER_TEXTS.RESULT_COUNT_SUFFIX}`}
            </h3>
            <Badge variant={getGeneratorBadgeVariant} className="text-xs">
              {getGeneratorBadgeLabel}
            </Badge>
          </div>
          <p className="text-sm mt-1" style={{ color: 'var(--text-muted)' }}>
            {DEFAULTS.PLACEHOLDER_TEXTS.RESULT_SUBTITLE}
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-2.5">
          <div className="flex items-center gap-2 px-3 py-1.5 bg-neutral-50 dark:bg-neutral-800 rounded-xl">
            <Filter className="w-3.5 h-3.5" style={{ color: 'var(--text-muted)' }} />
            <select
              value={selectedCategory}
              onChange={(e) => onCategoryChange(e.target.value as FormulaCategory | 'all')}
              className="bg-transparent text-xs font-medium border-none outline-none cursor-pointer"
              style={{ color: 'var(--text-primary)' }}
            >
              <option value="all">{t('ai.formula.generateTab.allCategories')}</option>
              {formulaCategories.map((cat) => (
                <option key={cat.id} value={cat.id}>
                  {cat.label}
                </option>
              ))}
            </select>
            {selectedCategory !== 'all' && (
              <span
                className="text-xs px-1.5 py-0.5 rounded-full"
                style={{
                  backgroundColor: FORMULA_CATEGORIES[selectedCategory]?.color + '20',
                  color: FORMULA_CATEGORIES[selectedCategory]?.color,
                }}
              >
                {filteredResults.length}
              </span>
            )}
          </div>

          <div className="flex items-center gap-1.5 bg-neutral-50 dark:bg-neutral-800 rounded-xl p-1">
            <button
              onClick={() => onToggleSort('score')}
              className={`px-2.5 py-1 rounded-lg text-xs font-medium transition-all ${
                sortBy === 'score' ? 'bg-white dark:bg-neutral-700 shadow-sm' : ''
              }`}
              style={{ color: sortBy === 'score' ? 'var(--color-primary-600)' : 'var(--text-muted)' }}
            >
              {t('ai.formula.generateTab.score')} {sortBy === 'score' && (sortOrder === 'desc' ? '↓' : '↑')}
            </button>
            <button
              onClick={() => onToggleSort('synergy')}
              className={`px-2.5 py-1 rounded-lg text-xs font-medium transition-all ${
                sortBy === 'synergy' ? 'bg-white dark:bg-neutral-700 shadow-sm' : ''
              }`}
              style={{ color: sortBy === 'synergy' ? 'var(--color-primary-600)' : 'var(--text-muted)' }}
            >
              {t('ai.formula.generateTab.synergy')} {sortBy === 'synergy' && (sortOrder === 'desc' ? '↓' : '↑')}
            </button>
          </div>

          {(generateResult?.length || 0) >= 2 && (
            <ResultsViewSwitcher viewMode={viewMode} onViewModeChange={onViewModeChange} />
          )}

          <button
            onClick={() => setShowOptimizationAdvisor(!showOptimizationAdvisor)}
            className={`px-3.5 py-2 rounded-xl text-xs font-medium transition-all duration-200 flex items-center gap-1.5 border ${
              showOptimizationAdvisor
                ? 'shadow-md bg-warning-500/10 dark:bg-warning-500/16 text-warning-600 dark:text-warning-700'
                : 'bg-neutral-50 dark:bg-neutral-800 text-neutral-600 dark:text-neutral-400'
            }`}
          >
            <Lightbulb className="w-3.5 h-3.5" />
            {DEFAULTS.PLACEHOLDER_TEXTS.BUTTON_OPTIMIZATION_ADVICE}
          </button>

          <button
            onClick={() => setShowSharePanel(!showSharePanel)}
            className={`px-3.5 py-2 rounded-xl text-xs font-medium transition-all duration-200 flex items-center gap-1.5 border ${
              showSharePanel
                ? 'shadow-md bg-info-500/10 dark:bg-info-500/16 text-info-600 dark:text-info-700'
                : 'bg-neutral-50 dark:bg-neutral-800 text-neutral-600 dark:text-neutral-400'
            }`}
          >
            <Share2 className="w-3.5 h-3.5" />
            {DEFAULTS.PLACEHOLDER_TEXTS.BUTTON_SHARE_FORMULA}
          </button>

          {onCompareVersions && (
            <button
              onClick={() => onCompareVersions(1, 2)}
              className="px-3.5 py-2 rounded-xl text-xs font-medium transition-all duration-200 flex items-center gap-1.5 border bg-neutral-50 dark:bg-neutral-800 text-neutral-600 dark:text-neutral-400 hover:shadow-md"
              title="对比最近两个版本"
            >
              <GitBranch className="w-3.5 h-3.5" />
              版本对比
