                {DEFAULTS.PLACEHOLDER_TEXTS.LOADING_TEXT}
              </div>
            }
          >
            {(() => {
              const formulaData = safeExtractFormulaData(generateResult[0]);
              return (
                <OptimizationAdvisor
                  formula={{
                    ...formulaData,
                    effects: effectLabels,
                  }}
                  onApplySuggestion={(suggestion: any) => {
                    logger.info('应用建议', suggestion);
                  }}
                />
              );
            })()}
          </Suspense>
