      )}

      {inputMode === 'effects' && (
        <>
          <Suspense fallback={
            <div className="animate-pulse p-6 bg-neutral-100 dark:bg-neutral-800 rounded-xl">
              {DEFAULTS.PLACEHOLDER_TEXTS.LOADING_TEXT}
            </div>
          }>
            <PersonalizedRecommendations
              onSelectRecommendation={(history: { effects: string[] }) => {
                const effectObjects = history.effects.map((effectName: string) => {
                  const effect = EFFECT_OPTIONS.find(e => e.label === effectName)
                  return effect || {
                    id: `custom_${effectName}`,
                    label: effectName,
                    category: DEFAULTS.PLACEHOLDER_TEXTS.CATEGORY_CUSTOM,
                    popular: false,
                  }
                })
                onSetSelectedEffects(effectObjects)
              }}
              maxDisplay={3}
            />
          </Suspense>

          <Suspense fallback={
            <div className="animate-pulse p-6 bg-neutral-100 dark:bg-neutral-800 rounded-xl">
              {DEFAULTS.PLACEHOLDER_TEXTS.LOADING_TEXT}
            </div>
          }>
            <ParameterAdjustPanel
              expanded={paramPanelExpanded}
              onToggle={onToggleParamPanel}
              onParameterChange={(params: Record<string, unknown>) => {
                logger.info('参数更新', params)
              }}
            />
          </Suspense>

          <div>
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-sm font-bold flex items-center gap-2" style={{ color: 'var(--text-primary)' }}>
                <div className="w-6 h-6 rounded-lg bg-primary-100 dark:bg-primary-300/25 flex items-center justify-center">
                  <RefreshCw className="w-3.5 h-3.5 text-primary-700 dark:text-primary-700" />
                </div>
                {DEFAULTS.PLACEHOLDER_TEXTS.TITLE_SELECT_EFFECTS}
                <span className="text-xs font-bold px-2.5 py-0.5 rounded-full bg-gradient-to-r from-[var(--color-primary-surface)] to-[var(--color-accent-surface-deep)] text-white shadow-sm">
                  {selectionCount}/{VALIDATION.maxEffectSelection}
                </span>
              </h3>
            </div>

            <div className="flex flex-wrap gap-2">
              {EFFECT_OPTIONS.map((effect) => {
                const isSelected = isEffectSelected(effect.id)

                return (
                  <button
                    key={effect.id}
                    onClick={() => onToggleEffect(effect)}
                    disabled={!isSelected && !canSelectMore}
                    className={`group/effect relative px-4 py-2.5 rounded-xl text-sm font-medium transition-all duration-200 overflow-hidden ${
                      isSelected
                        ? 'shadow-lg scale-105'
                        : !isSelected && !canSelectMore
                          ? 'opacity-30 cursor-not-allowed'
                          : 'hover:shadow-md hover:scale-102 active:scale-98'
                    }`}
                    style={{
                      backgroundColor: isSelected
                        ? 'var(--color-primary-500)'
                        : 'var(--bg-secondary)',
                      border: isSelected
                        ? 'none'
                        : '1px solid var(--border-color)',
                      color: isSelected
                        ? 'white'
                        : 'var(--text-secondary)',
                      boxShadow: isSelected
                        ? '0 8px 24px rgba(99, 102, 241, 0.3)'
                        : 'none',
                    }}
                  >
                    {/* 选中状态光晕 */}
                    {isSelected && (
                      <div className="absolute inset-0 bg-gradient-to-r from-white/20 to-transparent opacity-50" />
                    )}

                    <span className="relative flex items-center gap-2">
                      {effect.label}

                      {effect.popular && !isSelected && (
                        <span className="text-xs px-1.5 py-0.5 rounded-full bg-warning-500/15 dark:bg-warning-500/25 text-warning-600 dark:text-warning-700 font-semibold border border-warning-200 dark:border-warning-700">
                          {DEFAULTS.PLACEHOLDER_TEXTS.BADGE_POPULAR}
                        </span>
                      )}

                      {isSelected && (
                        <CheckCircle className="w-3.5 h-3.5 ml-1" />
                      )}
                    </span>
                  </button>
                )
              })}
            </div>
          </div>

          <div className="flex flex-col sm:flex-row items-center gap-4 pt-3 border-t border-neutral-100 dark:border-neutral-800">
            {progress.stage !== 'idle' && (
              <div className="flex-1 w-full">
                <GenerationProgressPanel
                  progress={progress}
                  onCancel={onCancelGeneration}
                  showCancelButton={progress.canCancel}
                />
              </div>
            )}

            <div className="flex items-center gap-3 w-full sm:w-auto">
              {/* 生成按钮 — 渐变增强 */}
              <Button
                disabled={selectedEffects.length === 0 || isGenerating}
                onClick={() => onGenerate(effectLabels)}
                loading={isGenerating}
                icon={
                  useLlm
                    ? <Wand2 className="w-4 h-4" />
                    : <Sparkles className="w-4 h-4" />
                }
                size="lg"
                className="min-w-[180px] rounded-xl font-bold shadow-lg hover:shadow-xl transition-all duration-200 bg-gradient-to-r from-primary-500 via-accent-500 to-accent-500 hover:from-primary-600 hover:via-accent-600 hover:to-accent-600"
              >
                {useLlm
                  ? DEFAULTS.PLACEHOLDER_TEXTS.BUTTON_AI_GENERATE
                  : DEFAULTS.PLACEHOLDER_TEXTS.BUTTON_START_GENERATE
                }
              </Button>

              {/* 快捷提示 */}
              {selectedEffects.length > 0 && (
                <span className="text-xs text-neutral-400 dark:text-neutral-400 hidden sm:inline">
                  ✓ {selectedEffects.length} 个功效已选择
                </span>
              )}
            </div>
          </div>
        </>
      )}
    </div>
  )
}

/**
 * GenerationInputEnhanced - 增强版配方生成输入组件
 * 
 * @description 解决子模块重叠问题，添加对话式输入，优化布局层次
 * @version 2.0.0
 */
import React, { useState, useCallback, useRef, useEffect } from 'react'
import {
  Target, FileText, MessageSquare, Sparkles, Send,
  X, ChevronDown, ChevronUp, Zap, Loader2,
  Lightbulb, Settings,
} from 'lucide-react'
import { Button } from '@/components/ui'
import { GenerationProgressPanel } from '@/components/ai/GenerationProgressPanel'
import { FormulaInputWindow } from '@/components/ai/FormulaInputWindow'
import { EFFECT_OPTIONS, EFFECT_CATEGORIES, getEffectsByCategory } from '@/config/ai/effects'
import { DEFAULTS, VALIDATION } from '@/config'
import { CheckCircle } from 'lucide-react'
import { logger } from '@/utils/safeLogger'

const QUICK_TEMPLATES = [
  { id: 'immune', name: '增强免疫', effects: ['增强免疫', '提高抵抗力'], icon: '🛡️' },
  { id: 'fatigue', name: '抗疲劳', effects: ['抗疲劳', '提升精力'], icon: '⚡' },
  { id: 'sleep', name: '改善睡眠', effects: ['改善睡眠', '安神定志'], icon: '😴' },
  { id: 'digestion', name: '健脾养胃', effects: ['健脾养胃', '促进消化'], icon: '🍵' },
  { id: 'beauty', name: '美容养颜', effects: ['美容养颜', '延缓衰老'], icon: '✨' },
  { id: 'cardio', name: '心血管健康', effects: ['降血脂', '保护血管'], icon: '❤️' },
]

interface EffectOption {
  id: string
  label: string
  category: string
  popular: boolean
}

interface GenerationInputEnhancedProps {
  inputMode: 'effects' | 'manual' | 'chat'
  onInputModeChange: (mode: 'effects' | 'manual' | 'chat') => void
  selectedEffects: EffectOption[]
  onToggleEffect: (effect: EffectOption) => void
  onClearEffects: () => void
  effectLabels: string[]
  canSelectMore: boolean
  selectionCount: number
  onGenerate: (effects: string[]) => void
  isGenerating: boolean
  progress: any
  onCancelGeneration: () => void
  onManualFormulaInput: (candidate: any) => void
  onSetSelectedEffects: (effects: EffectOption[]) => void
  paramPanelExpanded: boolean
  onToggleParamPanel: () => void
  onFullReset: () => void
  useLlm: boolean
  llmAvailable: boolean
}

export const GenerationInputEnhanced: React.FC<GenerationInputEnhancedProps> = ({
  inputMode,
  onInputModeChange,
  selectedEffects,
  onToggleEffect,
  onClearEffects,
  effectLabels,
  canSelectMore,
  selectionCount,
  onGenerate,
  isGenerating,
  progress,
  onCancelGeneration,
  onManualFormulaInput,
  onSetSelectedEffects,
  paramPanelExpanded,
  onToggleParamPanel,
  onFullReset,
  useLlm,
  llmAvailable,
}) => {
  const [chatInput, setChatInput] = useState('')
  const [chatHistory, setChatHistory] = useState<{role: 'user' | 'assistant'; content: string}[]>([])
  const [isChatProcessing, setIsChatProcessing] = useState(false)
  const [showQuickTemplates, setShowQuickTemplates] = useState(true)
  const chatEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLTextAreaElement>(null)

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [chatHistory])

  const handleQuickTemplateClick = useCallback((template: typeof QUICK_TEMPLATES[0]) => {
    const existingIds = selectedEffects.map(e => e.id)
    const newEffects = template.effects
      .map(label => EFFECT_OPTIONS.find(e => e.label === label))
      .filter((e): e is EffectOption => e !== undefined && !existingIds.includes(e.id))

    if (newEffects.length > 0) {
      onSetSelectedEffects([...selectedEffects, ...newEffects])
    }
    setShowQuickTemplates(false)
  }, [selectedEffects, onSetSelectedEffects])

  const handleChatSend = useCallback(async () => {
    if (!chatInput.trim() || isChatProcessing) return

    const userMessage = chatInput.trim()
    setChatHistory(prev => [...prev, { role: 'user', content: userMessage }])
    setChatInput('')
    setIsChatProcessing(true)

    try {
      // 模拟AI处理（实际应调用API）
      await new Promise(resolve => setTimeout(resolve, 1500))

      const assistantMessage = `已理解您的需求："${userMessage}"。基于此，我为您推荐以下功效组合：

• 增强免疫
• 改善睡眠  
• 健脾养胃

这些功效组合有助于整体调理。是否要应用这些选择？`

      setChatHistory(prev => [...prev, { role: 'assistant', content: assistantMessage }])

      // 自动选择推荐的效应
      const recommendedEffects = ['增强免疫', '改善睡眠', '健脾养胃']
        .map(label => EFFECT_OPTIONS.find(e => e.label === label))
        .filter((e): e is EffectOption => e !== undefined)

      if (recommendedEffects.length > 0) {
        onSetSelectedEffects(recommendedEffects)
      }
    } catch (error) {
      logger.error('Chat processing failed:', error)
      setChatHistory(prev => [...prev, { 
        role: 'assistant', 
        content: '处理请求时出现问题，请重试。' 
      }])
    } finally {
      setIsChatProcessing(false)
    }
  }, [chatInput, isChatProcessing, onSetSelectedEffects])

  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleChatSend()
    }
  }, [handleChatSend])

  return (
    <div className="space-y-6 animate-[fadeInUp_0.4s_cubic-bezier(0.16,1,0.3,1)_both]">
      {/* 输入模式切换 - 三栏设计 */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          <span className="text-xs font-semibold text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] uppercase tracking-wider">
            {DEFAULTS.PLACEHOLDER_TEXTS.LABEL_INPUT_MODE}
          </span>
          <div className="flex bg-neutral-100 dark:bg-neutral-800/80 rounded-xl p-1 shadow-inner">
            <button
              onClick={() => onInputModeChange('chat')}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-all duration-200 ${
                inputMode === 'chat'
                  ? 'bg-white dark:bg-neutral-700 shadow-md text-neutral-900 dark:text-neutral-100 scale-105'
                  : 'text-neutral-500 dark:text-neutral-400 hover:text-neutral-700 dark:hover:text-neutral-300'
              }`}
            >
              <MessageSquare className="w-4 h-4" />
              对话模式
            </button>
            <button
              onClick={() => onInputModeChange('effects')}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-all duration-200 ${
                inputMode === 'effects'
                  ? 'bg-white dark:bg-neutral-700 shadow-md text-neutral-900 dark:text-neutral-100 scale-105'
                  : 'text-neutral-500 dark:text-neutral-400 hover:text-neutral-700 dark:hover:text-neutral-300'
              }`}
            >
              <Target className="w-4 h-4" />
              功效选择
            </button>
            <button
              onClick={() => onInputModeChange('manual')}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-all duration-200 ${
                inputMode === 'manual'
                  ? 'bg-white dark:bg-neutral-700 shadow-md text-neutral-900 dark:text-neutral-100 scale-105'
                  : 'text-neutral-500 dark:text-neutral-400 hover:text-neutral-700 dark:hover:text-neutral-300'
              }`}
            >
              <FileText className="w-4 h-4" />
              手动输入
            </button>
          </div>
        </div>

        {/* 当前状态指示器 */}
        {selectedEffects.length > 0 && (
          <div className="flex items-center gap-2 px-3 py-1.5 bg-primary-50 dark:bg-primary-300/20 rounded-full border border-primary-200 dark:border-primary-800">
            <CheckCircle className="w-3.5 h-3.5 text-primary-700 dark:text-primary-700" />
            <span className="text-xs font-medium text-primary-700 dark:text-primary-700">
              已选 {selectionCount}/{VALIDATION.maxEffectSelection} 个功效
            </span>
          </div>
        )}
      </div>

      {/* 对话模式 */}
      {inputMode === 'chat' && (
        <div className="space-y-4 animate-fade-in">
          {/* 快捷模板 */}
          {showQuickTemplates && (
            <div className="p-4 bg-gradient-to-r from-warning-50 to-warning-50 dark:from-warning-900/10 dark:to-warning-900/10 rounded-xl border border-warning-200 dark:border-warning-800/30">
              <div className="flex items-center gap-2 mb-3">
                <Lightbulb className="w-4 h-4 text-warning-600 dark:text-warning-700" />
                <span className="text-sm font-medium text-warning-800 dark:text-warning-700">快捷模板</span>
                <button 
                  onClick={() => setShowQuickTemplates(false)}
                  className="ml-auto text-warning-500 hover:text-warning-700"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 sm:grid-cols-3 md:grid-cols-6 gap-2">
                {QUICK_TEMPLATES.map((template) => (
                  <button
                    key={template.id}
                    onClick={() => handleQuickTemplateClick(template)}
                    className="flex flex-col items-center gap-1 p-3 bg-white dark:bg-neutral-800 rounded-lg border border-neutral-200 dark:border-neutral-700 hover:border-warning-400 dark:hover:border-warning-600 hover:shadow-md transition-all duration-200"
                  >
                    <span className="text-xl">{template.icon}</span>
                    <span className="text-xs font-medium text-neutral-700 dark:text-neutral-300">{template.name}</span>
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* 聊天输入区域 */}
          <div className="relative bg-white dark:bg-neutral-900 rounded-2xl shadow-lg border border-neutral-200 dark:border-neutral-700 overflow-hidden">
            {/* 聊天记录区 */}
            <div className="max-h-64 overflow-y-auto p-4 space-y-3">
              {chatHistory.length === 0 ? (
                <div className="text-center py-8 text-neutral-400 dark:text-neutral-400">
                  <MessageSquare className="w-12 h-12 mx-auto mb-3 opacity-50" />
                  <p className="text-sm">描述您的健康需求，AI将为您生成个性化配方</p>
                  <p className="text-xs mt-1">例如："我最近经常熬夜，容易疲劳，想调理身体"</p>
                </div>
              ) : (
                chatHistory.map((msg, idx) => (
                  <div
                    key={idx}
                    className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
                  >
                    <div
                      className={`max-w-[80%] px-4 py-3 rounded-2xl text-sm ${
                        msg.role === 'user'
                          ? 'bg-primary-container text-primary-main rounded-br-sm'
                          : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded-bl-sm'
                      }`}
                    >
                      {msg.content.split('\n').map((line, i) => (
                        <p key={i} className={i > 0 ? 'mt-1' : ''}>{line}</p>
                      ))}
                    </div>
                  </div>
                ))
              )}
              {isChatProcessing && (
                <div className="flex justify-start">
                  <div className="bg-neutral-100 dark:bg-neutral-800 px-4 py-3 rounded-2xl rounded-bl-sm">
                    <Loader2 className="w-4 h-4 animate-spin text-primary-500" />
                  </div>
                </div>
              )}
              <div ref={chatEndRef} />
            </div>

            {/* 输入区域 */}
            <div className="border-t border-neutral-200 dark:border-neutral-700 p-3 flex gap-2">
              <textarea
                ref={inputRef}
                value={chatInput}
                onChange={(e) => setChatInput(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder="描述您的健康需求，如：改善睡眠、增强免疫..."
                rows={2}
                className="flex-1 resize-none bg-transparent text-sm text-neutral-900 dark:text-neutral-100 placeholder-neutral-400 focus:outline-none"
                disabled={isChatProcessing}
              />
              <button
                onClick={handleChatSend}
                disabled={!chatInput.trim() || isChatProcessing}
                className="px-3 py-2 bg-primary-container hover:bg-primary-container disabled:bg-neutral-300 dark:disabled:bg-neutral-700 text-primary-main rounded-xl transition-colors duration-200"
              >
                <Send className="w-4 h-4" />
              </button>
            </div>
          </div>

          {/* 选择结果展示 */}
          {selectedEffects.length > 0 && (
            <div className="flex flex-wrap gap-2 p-3 bg-success-50 dark:bg-success-300/15 rounded-xl border border-success-200 dark:border-success-800/30">
              <span className="text-xs font-medium text-success-700 dark:text-success-600 flex items-center gap-1">
                <CheckCircle className="w-3.5 h-3.5" />
                AI已为您选择：
              </span>
              {selectedEffects.map((effect) => (
                <span
                  key={effect.id}
                  className="text-xs px-2 py-1 bg-success-100 dark:bg-success-300/25 text-success-700 dark:text-success-600 rounded-full"
                >
                  {effect.label}
                </span>
              ))}
            </div>
          )}
        </div>
      )}

      {/* 功效选择模式 */}
      {inputMode === 'effects' && (
        <div className="space-y-6 animate-fade-in">
          {/* 分类筛选 */}
          <div className="flex flex-wrap gap-2">
            {EFFECT_CATEGORIES.map((category) => {
              const effects = getEffectsByCategory(category)
              const hasSelected = effects.some(e => selectedEffects.some(s => s.id === e.id))
              return (
                <button
                  key={category}
                  className={`px-3 py-1.5 rounded-full text-xs font-medium transition-all duration-200 ${
                    hasSelected
                      ? 'bg-primary-container text-primary-main shadow-sm'
                      : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-600 dark:text-neutral-400 hover:bg-neutral-200 dark:hover:bg-neutral-700'
                  }`}
                >
                  {category}
                  {hasSelected && <span className="ml-1 text-xs">✓</span>}
                </button>
              )
            })}
          </div>

          {/* 功效选择网格 */}
          <div>
            <div className="flex items-center justify-between mb-3">
              <h3 className="text-sm font-bold flex items-center gap-2" style={{ color: 'var(--text-primary)' }}>
                <div className="w-6 h-6 rounded-lg bg-primary-100 dark:bg-primary-300/25 flex items-center justify-center">
                  <Target className="w-3.5 h-3.5 text-primary-700 dark:text-primary-700" />
                </div>
                {DEFAULTS.PLACEHOLDER_TEXTS.TITLE_SELECT_EFFECTS}
                <span className="text-xs font-bold px-2.5 py-0.5 rounded-full bg-gradient-to-r from-[var(--color-primary-surface)] to-[var(--color-accent-surface-deep)] text-white shadow-sm">
                  {selectionCount}/{VALIDATION.maxEffectSelection}
                </span>
              </h3>
              {selectedEffects.length > 0 && (
                <button
                  onClick={onClearEffects}
                  className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-error-500 transition-colors"
                >
                  清空选择
                </button>
              )}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-2">
              {EFFECT_OPTIONS.map((effect) => {
                const isSelected = selectedEffects.some(e => e.id === effect.id)
                return (
                  <button
                    key={effect.id}
                    onClick={() => onToggleEffect(effect)}
                    disabled={!isSelected && !canSelectMore}
                    className={`group relative px-3 py-2.5 rounded-xl text-sm font-medium transition-all duration-200 overflow-hidden ${
                      isSelected
                        ? 'shadow-lg scale-105'
                        : !isSelected && !canSelectMore
                          ? 'opacity-30 cursor-not-allowed'
                          : 'hover:shadow-md hover:scale-102 active:scale-98'
                    }`}
                    style={{
                      backgroundColor: isSelected
                        ? 'var(--color-primary-500)'
                        : 'var(--bg-secondary)',
                      border: isSelected
                        ? 'none'
                        : '1px solid var(--border-color)',
                      color: isSelected
                        ? 'white'
                        : 'var(--text-secondary)',
                      boxShadow: isSelected
                        ? '0 8px 24px rgba(99, 102, 241, 0.3)'
                        : 'none',
                    }}
                  >
                    {isSelected && (
                      <div className="absolute inset-0 bg-gradient-to-r from-white/20 to-transparent opacity-50" />
                    )}
                    <span className="relative flex items-center gap-1.5">
                      {effect.label}
                      {effect.popular && !isSelected && (
                        <span className="text-xs px-1 py-0.5 rounded-full bg-warning-500/15 dark:bg-warning-500/25 text-warning-600 dark:text-warning-700 font-semibold">
                          热
                        </span>
                      )}
                      {isSelected && (
                        <CheckCircle className="w-3.5 h-3.5 ml-1" />
                      )}
                    </span>
                  </button>
                )
              })}
            </div>
          </div>

          {/* 参数调整面板 */}
          <div className="border-t border-neutral-200 dark:border-neutral-700 pt-4">
            <button
              onClick={onToggleParamPanel}
              className="flex items-center gap-2 text-sm font-medium text-neutral-600 dark:text-neutral-400 hover:text-neutral-900 dark:hover:text-neutral-100 transition-colors"
            >
              <Settings className="w-4 h-4" />
              高级参数配置
              {paramPanelExpanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
            </button>

            {paramPanelExpanded && (
              <div className="mt-3 p-4 bg-neutral-50 dark:bg-neutral-800/50 rounded-xl animate-fade-in">
                <p className="text-sm text-neutral-500 dark:text-neutral-400 text-center py-4">
                  参数配置功能开发中...
                </p>
              </div>
            )}
          </div>
        </div>
      )}

      {/* 手动输入模式 */}
      {inputMode === 'manual' && (
        <div className="animate-fade-in">
          <FormulaInputWindow
            onClose={() => onInputModeChange('effects')}
            onSubmit={onManualFormulaInput}
          />
        </div>
      )}

      {/* 进度显示 */}
      {progress.stage !== 'idle' && (
        <GenerationProgressPanel
          progress={progress}
          onCancel={onCancelGeneration}
          showCancelButton={progress.canCancel}
        />
      )}

      {/* 操作按钮 */}
      <div className="flex flex-col sm:flex-row items-center gap-4 pt-4 border-t border-neutral-100 dark:border-neutral-800">
        <div className="flex items-center gap-3 w-full sm:w-auto">
          <Button
            disabled={selectedEffects.length === 0 || isGenerating}
            onClick={() => onGenerate(effectLabels)}
            loading={isGenerating}
            icon={useLlm && llmAvailable ? <Zap className="w-4 h-4" /> : <Sparkles className="w-4 h-4" />}
            size="lg"
            className="min-w-[180px] rounded-xl font-bold shadow-lg hover:shadow-xl transition-all duration-200 bg-gradient-to-r from-primary-500 via-accent-500 to-accent-500 hover:from-primary-600 hover:via-accent-600 hover:to-accent-600"
          >
            {useLlm && llmAvailable
              ? DEFAULTS.PLACEHOLDER_TEXTS.BUTTON_AI_GENERATE
              : DEFAULTS.PLACEHOLDER_TEXTS.BUTTON_START_GENERATE
            }
          </Button>

          {selectedEffects.length > 0 && (
            <span className="text-xs text-neutral-400 dark:text-neutral-400 hidden sm:inline">
              ✓ {selectedEffects.length} 个功效已选择
            </span>
          )}
        </div>

        <div className="flex items-center gap-2 w-full sm:w-auto justify-end">
          <button
            onClick={onFullReset}
            className="px-4 py-2 text-sm text-neutral-500 hover:text-neutral-700 dark:text-neutral-400 dark:hover:text-neutral-200 transition-colors"
          >
            重置
          </button>
        </div>
      </div>
    </div>
  )
}

export default GenerationInputEnhanced

/**
 * GenerationInputPro - Professional Formula Generation Input Component
 * 
 * @description Clean layout following RMFOOD design system
 * @version 5.0.0 - Unified Layout
 */
import React, { useState, useCallback, useRef, useEffect } from 'react'
import {
  Target, FileText, MessageSquare, Sparkles, Send,
  X, ChevronDown, ChevronUp, Zap, Loader2,
  Lightbulb, Settings, CheckCircle,
  Shield,
} from 'lucide-react'
import { Button } from '@/components/ui'
import { GenerationProgressPanel } from '@/components/ai/GenerationProgressPanel'
import { FormulaInputWindow } from '@/components/ai/FormulaInputWindow'
import { EFFECT_OPTIONS, EFFECT_CATEGORIES } from '@/config/ai/effects'
import { DEFAULTS, VALIDATION } from '@/config'
import { useGenerationShortcuts } from '../hooks/useGenerationShortcuts'
import type { InputMode } from '../config/generateTabConfig'
import { AlgorithmConfigPanel } from './AlgorithmConfigPanel'
import { ConstraintPanel } from './ConstraintPanel'
import type { AlgorithmConfig } from './AlgorithmConfigPanel'
import type { PersonalConstraints } from './ConstraintPanel'

// Quick templates
const QUICK_TEMPLATES = [
  { id: 'immune', name: '增强免疫', icon: '🛡️', effects: ['immune_enhancement', 'resistance_boost'] },
  { id: 'fatigue', name: '抗疲劳', icon: '⚡', effects: ['anti_fatigue', 'energy_boost'] },
  { id: 'sleep', name: '改善睡眠', icon: '😴', effects: ['sleep_improvement', 'calm_mind'] },
  { id: 'digestion', name: '健脾养胃', icon: '🍵', effects: ['spleen_stomach', 'digestion_promotion'] },
  { id: 'beauty', name: '美容养颜', icon: '✨', effects: ['beauty_skin', 'antioxidant'] },
  { id: 'cardio', name: '心血管健康', icon: '❤️', effects: ['blood_lipid', 'vascular_protection'] },
]

interface EffectOption {
  id: string
  label: string
  category: string
  popular: boolean
}

interface GenerationInputProProps {
  inputMode: InputMode | 'chat'
  onInputModeChange: (mode: InputMode | 'chat') => void
  selectedEffects: EffectOption[]
  onToggleEffect: (effect: EffectOption) => void
  onClearEffects: () => void
  effectLabels: string[]
  canSelectMore: boolean
  selectionCount: number
  onGenerate: (effects: string[]) => void
  isGenerating: boolean
  progress: any
  onCancelGeneration: () => void
  onManualFormulaInput: (candidate: any) => void
  onSetSelectedEffects: (effects: EffectOption[]) => void
  paramPanelExpanded: boolean
  onToggleParamPanel: () => void
  onFullReset: () => void
  useLlm: boolean
  llmAvailable: boolean
  algorithmConfig?: AlgorithmConfig
  onAlgorithmConfigChange?: (config: AlgorithmConfig) => void
  constraints?: PersonalConstraints
  onConstraintsChange?: (constraints: PersonalConstraints) => void
  className?: string
}

export const GenerationInputPro: React.FC<GenerationInputProProps> = ({
  inputMode,
  onInputModeChange,
  selectedEffects,
  onToggleEffect,
  onClearEffects,
  effectLabels,
  canSelectMore,
  selectionCount,
  onGenerate,
  isGenerating,
  progress,
  onCancelGeneration,
  onManualFormulaInput,
  onSetSelectedEffects,
  paramPanelExpanded,
  onToggleParamPanel,
  onFullReset,
  useLlm,
  llmAvailable,
  algorithmConfig,
  onAlgorithmConfigChange,
  constraints,
  onConstraintsChange,
  className = '',
}) => {
  const [chatInput, setChatInput] = useState('')
  const [chatHistory, setChatHistory] = useState<{role: 'user' | 'assistant'; content: string; timestamp?: number}[]>([])
  const [isChatProcessing, setIsChatProcessing] = useState(false)
  const [showQuickTemplates, setShowQuickTemplates] = useState(true)
  const [activeCategory, setActiveCategory] = useState<string>('All')
  const chatEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLTextAreaElement>(null)

  const { shortcuts } = useGenerationShortcuts({
    onGenerate: () => onGenerate(effectLabels),
    onCancel: onCancelGeneration,
    onReset: onFullReset,
    onSwitchToChat: () => onInputModeChange('chat'),
  })

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [chatHistory])

  const categories = ['All', ...EFFECT_CATEGORIES]
  const filteredEffects = activeCategory === 'All' 
    ? EFFECT_OPTIONS 
    : EFFECT_OPTIONS.filter(e => e.category === activeCategory)

  const handleQuickTemplateClick = useCallback((template: typeof QUICK_TEMPLATES[0]) => {
    const existingIds = new Set(selectedEffects.map(e => e.id))
    const newEffects = template.effects
      .map(id => EFFECT_OPTIONS.find(e => e.id === id))
      .filter((e): e is EffectOption => e !== undefined && !existingIds.has(e.id))

    if (newEffects.length > 0) {
      onSetSelectedEffects([...selectedEffects, ...newEffects])
    }
    setShowQuickTemplates(false)
  }, [selectedEffects, onSetSelectedEffects])

  const handleChatSend = useCallback(async () => {
    if (!chatInput.trim() || isChatProcessing) return

    const userMessage = chatInput.trim()
    setChatHistory(prev => [...prev, { role: 'user', content: userMessage, timestamp: Date.now() }])
    setChatInput('')
    setIsChatProcessing(true)

    try {
      await new Promise(resolve => setTimeout(resolve, 1200))

      const assistantMessage = `已理解您的需求："${userMessage}"

根据您的描述，推荐以下功效组合：
- 增强免疫
- 改善睡眠
- 健脾养胃`

      setChatHistory(prev => [...prev, { role: 'assistant', content: assistantMessage, timestamp: Date.now() }])

      const recommendedEffects = ['immune_enhancement', 'sleep_improvement', 'spleen_stomach']
        .map(id => EFFECT_OPTIONS.find(e => e.id === id))
        .filter((e): e is EffectOption => e !== undefined)

      if (recommendedEffects.length > 0) {
        onSetSelectedEffects(recommendedEffects)
      }
    } catch (error) {
      console.error('Chat processing failed:', error)
      setChatHistory(prev => [...prev, { role: 'assistant', content: '出错了，请重试。', timestamp: Date.now() }])
    } finally {
      setIsChatProcessing(false)
    }
  }, [chatInput, isChatProcessing, onSetSelectedEffects])

  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleChatSend()
    }
  }, [handleChatSend])

  return (
    <div className={className}>
      {/* Mode switcher - compact */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-3">
          <span className="text-overline font-semibold text-muted-foreground uppercase tracking-wider">Mode</span>
          <div className="flex bg-muted rounded-lg p-0.5">
            {(['chat', 'effects', 'manual'] as const).map((mode) => {
              const labels = { chat: 'Chat', effects: 'Effects', manual: 'Manual' }
              const icons = { chat: MessageSquare, effects: Target, manual: FileText }
              const Icon = icons[mode]
              const isActive = inputMode === mode
              return (
                <button
                  key={mode}
                  onClick={() => onInputModeChange(mode)}
                  className={`flex items-center gap-1.5 px-3 py-1.5 rounded-md text-body-sm font-medium transition-all
                    ${isActive ? 'bg-primary text-primary-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'}`}
                >
                  <Icon className="w-3.5 h-3.5" />
                  {labels[mode]}
                </button>
              )
            })}
          </div>
        </div>
        {selectedEffects.length > 0 && (
          <div className="flex items-center gap-2 px-3 py-1.5 bg-primary/10 rounded-full border border-primary/20">
            <CheckCircle className="w-3.5 h-3.5 text-primary" />
            <span className="text-body-sm font-medium text-primary">{selectionCount}/{VALIDATION.maxEffectSelection}</span>
          </div>
        )}
      </div>

      {/* Chat mode */}
      {inputMode === 'chat' && (
        <div className="space-y-4">
          {showQuickTemplates && (
            <div className="p-4 bg-muted/30 rounded-xl border border-border">
              <div className="flex items-center justify-between mb-3">
                <div className="flex items-center gap-2">
                  <Lightbulb className="w-4 h-4 text-warning" />
                  <span className="text-body-sm font-semibold">快速开始</span>
                </div>
                <button onClick={() => setShowQuickTemplates(false)} className="p-1 text-muted-foreground hover:text-foreground">
                  <X className="w-4 h-4" />
                </button>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-3 sm:grid-cols-6 gap-2">
                {QUICK_TEMPLATES.map((template) => (
                  <button
                    key={template.id}
                    onClick={() => handleQuickTemplateClick(template)}
                    className="flex flex-col items-center gap-1.5 p-3 bg-background rounded-lg border border-border hover:border-primary/40 transition-all"
                  >
                    <span className="text-xl">{template.icon}</span>
                    <span className="text-caption font-medium text-center">{template.name}</span>
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Chat input */}
          <div className="bg-background rounded-xl border border-border overflow-hidden">
            <div className="max-h-64 overflow-y-auto p-4 space-y-3">
              {chatHistory.length === 0 ? (
                <div className="text-center py-8 text-muted-foreground">
                  <MessageSquare className="w-10 h-10 mx-auto mb-3 opacity-30" />
                  <p className="text-body-sm font-medium mb-1">描述您的健康需求</p>
                  <p className="text-caption text-muted-foreground">例如："长期熬夜、精神疲惫"</p>
                </div>
              ) : (
                chatHistory.map((msg, idx) => (
                  <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                    <div className={`max-w-[85%] px-3 py-2 rounded-xl text-body-sm ${
                      msg.role === 'user' 
                        ? 'bg-primary text-primary-foreground rounded-br-sm' 
                        : 'bg-muted text-foreground rounded-bl-sm'
                    }`}>
                      {msg.content.split('\n').map((line, i) => <p key={i} className={i > 0 ? 'mt-1.5' : ''}>{line}</p>)}
                    </div>
                  </div>
                ))
              )}
              {isChatProcessing && (
                <div className="flex justify-start">
                  <div className="bg-muted px-3 py-2 rounded-xl rounded-bl-sm">
                    <Loader2 className="w-4 h-4 animate-spin text-primary" />
                  </div>
                </div>
              )}
              <div ref={chatEndRef} />
            </div>
            <div className="border-t border-border p-3 flex gap-2">
              <textarea
                ref={inputRef}
                value={chatInput}
                onChange={(e) => setChatInput(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder="描述您的健康需求..."
                rows={2}
                className="flex-1 resize-none bg-transparent text-body placeholder:text-muted-foreground focus:outline-none"
                disabled={isChatProcessing}
              />
              <button
                onClick={handleChatSend}
                disabled={!chatInput.trim() || isChatProcessing}
                className="px-3 py-2 bg-primary hover:bg-primary-hover disabled:bg-muted text-primary-foreground rounded-lg transition-all"
              >
                <Send className="w-4 h-4" />
              </button>
            </div>
          </div>

          {selectedEffects.length > 0 && (
            <div className="flex flex-wrap gap-2 p-3 bg-success/5 rounded-lg border border-success/20">
              <span className="text-body-sm font-medium text-success flex items-center gap-1.5">
                <CheckCircle className="w-3.5 h-3.5" />AI已选择：
              </span>
              {selectedEffects.map((effect) => (
                <span key={effect.id} className="text-caption px-2 py-0.5 bg-success/10 text-success rounded-full font-medium">
                  {effect.label}
                </span>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Effects mode */}
      {inputMode === 'effects' && (
        <div className="space-y-4">
          {/* Categories */}
          <div className="flex flex-wrap gap-1.5">
            {categories.map((category) => {
              const count = category === 'All' ? EFFECT_OPTIONS.length : EFFECT_OPTIONS.filter(e => e.category === category).length
              const hasSelected = category === 'All' ? selectedEffects.length > 0 : EFFECT_OPTIONS.some(e => e.category === category && selectedEffects.some(s => s.id === e.id))
              return (
                <button
                  key={category}
                  onClick={() => setActiveCategory(category)}
                  className={`px-3 py-1.5 rounded-full text-caption font-medium transition-all
                    ${activeCategory === category ? 'bg-primary text-primary-foreground' : hasSelected ? 'bg-primary/10 text-primary border border-primary/20' : 'bg-muted text-muted-foreground hover:bg-background'}`}
                >
                  {category} <span className="opacity-70 ml-1">{count}</span>
                </button>
              )
            })}
          </div>

          {/* Effects grid */}
          <div>
            <div className="flex items-center justify-between mb-3">
              <h3 className="text-title-sm font-semibold flex items-center gap-2">
                <div className="w-5 h-5 rounded-md bg-primary/10 flex items-center justify-center">
                  <Target className="w-3 h-3 text-primary" />
                </div>
                选择功效
                <span className="text-caption font-medium px-2 py-0.5 rounded-full bg-primary text-primary-foreground text-xs">
                  {selectionCount}/{VALIDATION.maxEffectSelection}
                </span>
              </h3>
              {selectedEffects.length > 0 && (
                <button onClick={onClearEffects} className="text-caption text-muted-foreground hover:text-error">清空</button>
              )}
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-3 sm:grid-cols-4 md:grid-cols-5 gap-2">
              {filteredEffects.map((effect) => {
                const isSelected = selectedEffects.some(e => e.id === effect.id)
                return (
                  <button
                    key={effect.id}
                    onClick={() => onToggleEffect(effect)}
                    disabled={!isSelected && !canSelectMore}
                    className={`px-3 py-2 rounded-lg text-body-sm font-medium transition-all border
                      ${isSelected ? 'bg-primary text-primary-foreground border-primary' : !isSelected && !canSelectMore ? 'opacity-40 cursor-not-allowed bg-muted border-transparent' : 'bg-background border-border hover:border-primary/40'}`}
                  >
                    <span className="flex items-center gap-1.5">
                      {effect.label}
                      {effect.popular && !isSelected && <span className="text-[9px] px-1 py-0.5 rounded bg-warning/10 text-warning font-bold">热门</span>}
                      {isSelected && <CheckCircle className="w-3 h-3 ml-auto" />}
                    </span>
                  </button>
                )
              })}
            </div>
          </div>

          {/* Parameters */}
          <div className="border-t border-border pt-3">
            <button onClick={onToggleParamPanel} className="flex items-center gap-2 text-body-sm font-medium text-muted-foreground hover:text-foreground">
              <Settings className="w-4 h-4" />
              算法参数
              {paramPanelExpanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
            </button>
            {paramPanelExpanded && (
              <div className="mt-3 space-y-4 animate-fade-in">
                {/* Algorithm Config */}
                <div className="p-4 bg-muted/30 rounded-lg">
                  <div className="flex items-center gap-2 mb-3">
                    <Zap className="w-4 h-4 text-primary" />
                    <h4 className="text-sm font-semibold">遗传算法配置</h4>
                  </div>
                  <AlgorithmConfigPanel
                    config={algorithmConfig || {
                      strategy: 'auto',
                      preset: 'balanced',
                      populationSize: 50,
                      generations: 40,
                      mutationRate: 0.15,
                      crossoverRate: 0.85,
                      eliteRatio: 0.15,
                      tournamentSize: 5,
                      tastePreference: 'balanced',
                    }}
                    onChange={(config) => onAlgorithmConfigChange?.(config)}
                    onApplyPreset={(preset) => onAlgorithmConfigChange?.({
                      ...(algorithmConfig || {}),
                      preset,
                    } as AlgorithmConfig)}
                    isGenerating={isGenerating}
                  />
                </div>

                {/* Personal Constraints */}
                <div className="p-4 bg-muted/30 rounded-lg">
                  <div className="flex items-center gap-2 mb-3">
                    <Shield className="w-4 h-4 text-warning" />
                    <h4 className="text-sm font-semibold">个人约束条件</h4>
                  </div>
                  <ConstraintPanel
                    constraints={constraints}
                    onChange={(c) => onConstraintsChange?.(c)}
                  />
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Manual mode */}
      {inputMode === 'manual' && (
        <FormulaInputWindow onClose={() => onInputModeChange('effects')} onSubmit={onManualFormulaInput} />
      )}

      {/* Progress */}
      {progress.stage !== 'idle' && (
        <GenerationProgressPanel progress={progress} onCancel={onCancelGeneration} showCancelButton={progress.canCancel} />
      )}

      {/* Action bar */}
      <div className="flex items-center justify-between mt-4 pt-4 border-t border-border">
        <div className="flex items-center gap-3">
          <Button
            disabled={selectedEffects.length === 0 || isGenerating}
            onClick={() => onGenerate(effectLabels)}
            loading={isGenerating}
            icon={useLlm && llmAvailable ? <Zap className="w-4 h-4" /> : <Sparkles className="w-4 h-4" />}
            size="lg"
            className="rounded-lg font-semibold"
          >
            {useLlm && llmAvailable ? DEFAULTS.PLACEHOLDER_TEXTS.BUTTON_AI_GENERATE : DEFAULTS.PLACEHOLDER_TEXTS.BUTTON_START_GENERATE}
          </Button>
          {selectedEffects.length > 0 && (
            <span className="text-caption text-muted-foreground">
              ✓ {selectedEffects.length} 已选
            </span>
          )}
        </div>
        <div className="flex items-center gap-3">
          <div className="hidden md:flex items-center gap-2 text-caption text-muted-foreground">
            <kbd className="px-1.5 py-0.5 bg-muted rounded border border-border font-mono text-xs">{shortcuts.generate}</kbd>
            <span>生成配方</span>
          </div>
          <button onClick={onFullReset} className="px-3 py-1.5 text-body-sm text-muted-foreground hover:text-foreground">重置</button>
        </div>
      </div>
    </div>
  )
}

export default GenerationInputPro

import React from 'react'
import { Sparkles, Zap, Brain, RefreshCw, MessageSquare, Settings, History, Download } from 'lucide-react'
import { Button, Badge } from '@/components/ui'
