export const Header: React.FC<HeaderProps> = ({
  advancedMode,
  onToggleAdvancedMode,
  useLlm,
  onToggleUseLlm,
  llmAvailable,
  modelStatus,
  generateResult,
  onFullReset,
  onSwitchToChat,
  onExportHistory,
  historyCount = 0,
