            <Brain className="w-4 h-4" />
            {advancedMode
              ? DEFAULTS.PLACEHOLDER_TEXTS.BUTTON_SIMPLE_MODE
              : DEFAULTS.PLACEHOLDER_TEXTS.BUTTON_ADVANCED_MODE
