          {/* 重新生成 */}
          {generateResult && (
            <Button
              variant="secondary"
              size="sm"
              icon={<RefreshCw className="w-4 h-4" />}
              onClick={onFullReset}
            >
              {DEFAULTS.PLACEHOLDER_TEXTS.BUTTON_REGENERATE}
            </Button>
          )}

