            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3 flex-1">
              <StatCard
                icon={<Dna className="w-5 h-5" />}
                label="总代数"
                value={`${result?.total_generations ?? liveHistory.length}`}
                color="indigo"
              />
              <StatCard
                icon={<FlaskConical className="w-5 h-5" />}
                label="评估次数"
                value={`${result?.total_evaluations?.toLocaleString() ?? '--'}`}
                color="blue"
              />
              <StatCard
                icon={<TrendingUp className="w-5 h-5" />}
                label="耗时(ms)"
                value={`${result?.execution_time_ms ?? '--'}`}
                color="green"
              />
              <StatCard
                icon={<GitBranch className="w-5 h-5" />}
                label="Pareto 解数"
                value={`${result?.pareto_front?.length ?? '--'}`}
                color="purple"
              />
              <StatCard
                icon={<Zap className="w-5 h-5" />}
                label="收敛代"
                value={`${result?.convergence_generation ?? '--'}`}
                color="amber"
              />
              <StatCard
                icon={<BarChart3 className="w-5 h-5" />}
                label="最终多样性"
                value={
