                      stroke="var(--color-slate-400, #9CA3AF)"
                      domain={['dataMin - 0.02', 'dataMax + 0.02']}
                    />
                    <Tooltip
                      contentStyle={{
                        backgroundColor: 'var(--card-bg, #fff)',
                        border: '1px solid var(--border-color, #e5e7eb)',
