                    />
                    <Legend wrapperStyle={{ fontSize: '12px' }} />
                    <Line
                      type="monotone"
                      dataKey="best_fitness"
                      name="最佳适应度"
                      stroke="var(--color-green-500, var(--color-primary-400))"
