                      dot={false}
                      strokeDasharray="3 3"
                    />
                  </LineChart>
                </ResponsiveContainer>
              </div>
            ) : (
              <div className="flex items-center justify-center py-12 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" role="status">
