export interface SensitivityParameter {
  id: string
  name: string
  unit: string
  baseValue: number
  minValue: number
  maxValue: number
  step: number
  currentValue: number
}

export interface MetricResult {
  efficacy: number
  stability: number
  cost: number
  safety: number
  sensory: number
  overall: number
}

export interface ScenarioConfig {
  id: string
  name: string
  color: string
  parameters: Record<string, number>
  results: MetricResult | null
}

interface SensitivityAnalysisProps {
  baseParameters: SensitivityParameter[]
  onParameterChange?: (parameters: Record<string, number>) => void
  onScenarioApply?: (scenario: ScenarioConfig) => void
  className?: string
}

const DEFAULT_PARAMETERS: SensitivityParameter[] = [
  { id: 'ph', name: 'pH 值', unit: '', baseValue: 6.5, minValue: 3.5, maxValue: 9.0, step: 0.1, currentValue: 6.5 },
  { id: 'temperature', name: '温度', unit: '°C', baseValue: 25, minValue: 4, maxValue: 80, step: 1, currentValue: 25 },
  { id: 'concentration', name: '浓度', unit: '%', baseValue: 10, minValue: 1, maxValue: 50, step: 0.5, currentValue: 10 },
  { id: 'time', name: '时间', unit: 'min', baseValue: 30, minValue: 5, maxValue: 120, step: 5, currentValue: 30 },
]

const METRIC_LABELS: Record<keyof MetricResult, string> = {
  efficacy: '功效',
  stability: '稳定性',
  cost: '成本效益',
  safety: '安全性',
  sensory: '感官品质',
  overall: '综合评分',
}

const METRIC_COLORS: Record<keyof MetricResult, string> = {
  efficacy: 'var(--color-primary, var(--color-primary-400))',
  stability: 'var(--color-secondary, #0A84FF)',
  cost: 'var(--color-warning, #FF9F0A)',
  safety: 'var(--color-error, #FF3B30)',
  sensory: 'var(--color-primary-500, #10b981)',
  overall: 'var(--color-danger-500, #D946EF)',
}

const SCENARIO_COLORS = ['var(--color-primary, var(--color-primary-400))', 'var(--color-secondary, #0A84FF)', 'var(--color-warning, #FF9F0A)']

function calculateMockResults(parameters: Record<string, number>): MetricResult {
  const ph = parameters.ph || 6.5
  const temp = parameters.temperature || 25
  const conc = parameters.concentration || 10
  const time = parameters.time || 30

  const phEffect = Math.max(0, 100 - Math.abs(ph - 6.5) * 20)
  const tempEffect = temp <= 40 ? 90 - Math.abs(temp - 25) : Math.max(30, 70 - (temp - 40))
  const concEffect = Math.min(100, conc * 8)
  const timeEffect = Math.min(100, time * 2)

  return {
    efficacy: Math.round((phEffect * 0.3 + tempEffect * 0.25 + concEffect * 0.3 + timeEffect * 0.15) * 100) / 100,
    stability: Math.round((100 - Math.abs(ph - 7) * 15 - (temp > 50 ? (temp - 50) : 0)) * 100) / 100,
    cost: Math.round(Math.max(20, 100 - conc * 1.5) * 100) / 100,
    safety: Math.round((ph >= 4.5 && ph <= 8 ? 95 : 60) * 100) / 100,
    sensory: Math.round((80 + Math.sin(ph) * 10 + (temp < 35 ? 10 : -5)) * 100) / 100,
    overall: 0,
  }
}

calculateMockResults.overall = function(results: MetricResult): number {
  return Math.round(
    (results.efficacy * 0.3 +
      results.stability * 0.2 +
      results.cost * 0.15 +
      results.safety * 0.2 +
      results.sensory * 0.15) *
      100,
  ) / 100
}

export function SensitivityAnalysis({
  baseParameters = DEFAULT_PARAMETERS,
  onParameterChange,
  onScenarioApply,
  className = '',
}: SensitivityAnalysisProps) {
  const [parameters, setParameters] = useState<SensitivityParameter[]>(
    baseParameters.map(p => ({ ...p })),
  )
  const [activeParamId, setActiveParamId] = useState<string>(baseParameters[0]?.id || '')
  const [scenarios, setScenarios] = useState<ScenarioConfig[]>([
    { id: 'A', name: '基准场景', color: SCENARIO_COLORS[0], parameters: {}, results: null },
  ])
  const [activeScenarioIndex, setActiveScenarioIndex] = useState(0)
  const [showHeatmapDetail, setShowHeatmapDetail] = useState<{ param: string; metric: string } | null>(null)
  const [debounceTimer, setDebounceTimer] = useState<ReturnType<typeof setTimeout> | null>(null)

  const currentParams = useMemo(
    () => Object.fromEntries(parameters.map(p => [p.id, p.currentValue])),
    [parameters],
  )

  const currentResults = useMemo(() => {
    const results = calculateMockResults(currentParams)
    results.overall = calculateMockResults.overall(results);
    return results
  }, [currentParams])

  const baselineResults = useMemo(() => {
    const baseline = Object.fromEntries(baseParameters.map(p => [p.id, p.baseValue]))
    const results = calculateMockResults(baseline)
    results.overall = calculateMockResults.overall(results);
    return results
  }, [baseParameters])

  const sensitivityData = useMemo(() => {
    const activeParam = parameters.find(p => p.id === activeParamId)
    if (!activeParam) return []

    const range = activeParam.baseValue * 0.2
    const minVal = Math.max(activeParam.minValue, activeParam.baseValue - range)
    const maxVal = Math.min(activeParam.maxValue, activeParam.baseValue + range)
    const steps = 20
    const stepSize = (maxVal - minVal) / steps

    const data = []
    for (let i = 0; i <= steps; i++) {
      const value = minVal + i * stepSize
      const testParams = { ...currentParams, [activeParam.id]: value }
      const results = calculateMockResults(testParams)
      results.overall = calculateMockResults.overall(results);

      data.push({
        value: Number(value.toFixed(2)),
        ...results,
        isBaseline: Math.abs(value - activeParam.baseValue) < stepSize / 2,
      })
    }

    return data
  }, [parameters, activeParamId, currentParams])

  const heatmapData = useMemo(() => {
    return parameters.map(param => {
      const row: Record<string, any> = { parameter: param.name }

      ;(Object.keys(METRIC_LABELS) as (keyof MetricResult)[]).forEach(metric => {
        const highParams = { ...currentParams, [param.id]: param.baseValue * 1.2 }
        const lowParams = { ...currentParams, [param.id]: param.baseValue * 0.8 }

        const highResult = calculateMockResults(highParams)
        highResult.overall = calculateMockResults.overall(highResult);
        const lowResult = calculateMockResults(lowParams)
        lowResult.overall = calculateMockResults.overall(lowResult);

        const sensitivity = ((highResult[metric] - lowResult[metric]) / (param.baseValue * 0.4)) * 100
        row[metric] = Number(sensitivity.toFixed(2))
      })

      return row
    })
  }, [parameters, currentParams])

  const getHeatmapColor = useCallback((value: number): string => {
    if (Math.abs(value) < 0.5) return 'bg-neutral-200 dark:bg-neutral-700'
    if (value > 0) {
      const intensity = Math.min(1, value / 10)
      return `rgba(16, 185, 129, ${0.3 + intensity * 0.7})`
    }
    const intensity = Math.min(1, Math.abs(value) / 10)
    return `rgba(239, 68, 68, ${0.3 + intensity * 0.7})`
  }, [])

  const handleParamChange = useCallback(
    (paramId: string, value: number) => {
      setParameters(prev =>
        prev.map(p => (p.id === paramId ? { ...p, currentValue: value } : p)),
      )

      if (debounceTimer) clearTimeout(debounceTimer)
      setDebounceTimer(
        setTimeout(() => {
          const newParams = Object.fromEntries(
            parameters.map(p => [p.id, p.id === paramId ? value : p.currentValue]),
          )
          onParameterChange?.(newParams)
        }, 200),
      )
    },
    [onParameterChange, parameters, debounceTimer],
  )

  useEffect(() => {
    return () => {
      if (debounceTimer) clearTimeout(debounceTimer)
    }
  }, [debounceTimer])

  const saveAsScenario = useCallback(
    (name: string) => {
      if (scenarios.length >= 3) return

      const newScenario: ScenarioConfig = {
        id: String.fromCharCode(65 + scenarios.length),
        name: name || `场景 ${String.fromCharCode(65 + scenarios.length)}`,
        color: SCENARIO_COLORS[scenarios.length],
        parameters: { ...currentParams },
        results: { ...currentResults },
      }

      setScenarios(prev => [...prev, newScenario])
      setActiveScenarioIndex(scenarios.length)
    },
    [scenarios.length, currentParams, currentResults],
  )

  const applyScenario = useCallback(
    (scenario: ScenarioConfig) => {
      setParameters(prev =>
        prev.map(p => ({
          ...p,
          currentValue: scenario.parameters[p.id] ?? p.currentValue,
        })),
      )
      onScenarioApply?.(scenario)
    },
    [onScenarioApply],
  )

  const resetToBaseline = useCallback(() => {
    setParameters(prev => prev.map(p => ({ ...p, currentValue: p.baseValue })))
  }, [])

  const getBestScenario = useCallback((): number => {
    let bestIdx = 0
    let bestScore = -1

    scenarios.forEach((scenario, idx) => {
      if (scenario.results && scenario.results.overall > bestScore) {
        bestScore = scenario.results.overall
        bestIdx = idx
      }
    })

    return bestIdx
  }, [scenarios])

  return (
    <div className={`space-y-6 ${className}`}>
      {/* 标题 */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-semibold text-neutral-900 dark:text-white flex items-center gap-2">
            <Sliders className="w-5 h-5 text-accent-500" />
            What-if 敏感性分析
          </h3>
          <p className="text-sm text-neutral-500 dark:text-neutral-400 mt-1">
            调整参数观察对配方指标的影响（±20% 变化范围）
          </p>
        </div>
        <button onClick={resetToBaseline} className="flex items-center gap-1.5 px-3 py-1.5 text-sm text-neutral-600 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors">
          <RotateCcw className="w-4 h-4" />
          重置基准
        </button>
      </div>

      {/* 单因素分析区域 */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* 左侧：参数滑动条组 */}
        <motion.div
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          className="bg-white dark:bg-neutral-900 rounded-2xl border border-neutral-200 dark:border-neutral-800 p-5"
        >
          <h4 className="text-sm font-semibold text-neutral-700 dark:text-neutral-300 mb-4">参数调整</h4>

          <div className="space-y-5">
            {parameters.map(param => {
              const deviation = ((param.currentValue - param.baseValue) / param.baseValue) * 100
              const isActive = param.id === activeParamId

              return (
                <div key={param.id} className={`space-y-2 rounded-xl p-3 transition-colors cursor-pointer ${isActive ? 'bg-accent-50 dark:bg-accent-300/20' : 'hover:bg-neutral-50 dark:hover:bg-neutral-800/50'}`}  role="button" tabIndex={0} onClick={() => setActiveParamId(param.id)}>
                  <div className="flex items-center justify-between">
                    <label className="text-sm font-medium text-neutral-700 dark:text-neutral-300">{param.name}</label>
                    <span className={`text-xs font-mono px-2 py-0.5 rounded ${
                      Math.abs(deviation) < 1 ? 'bg-neutral-100 dark:bg-neutral-800 text-neutral-600' :
                      deviation > 0 ? 'bg-secondary-100 dark:bg-secondary-300/25 text-secondary-600' :
                      'bg-error-100 dark:bg-error-300/25 text-error-600'
                    }`}>
                      {param.currentValue}{param.unit}
                      {Math.abs(deviation) >= 1 && (
                        <span className="ml-1">
                          {deviation > 0 ? '+' : ''}{deviation.toFixed(1)}%
                        </span>
                      )}
                    </span>
                  </div>

                  <input
                    type="range"
                    min={param.minValue}
                    max={param.maxValue}
                    step={param.step}
                    value={param.currentValue}
                    onChange={(e) => handleParamChange(param.id, Number(e.target.value))}
                    className={`w-full h-2 rounded-full appearance-none cursor-pointer accent-accent-500`} aria-label="滑块" />

                  <div className="flex justify-between text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                    <span>{param.minValue}{param.unit}</span>
                    <span className="font-medium text-accent-600">基准: {param.baseValue}{param.unit}</span>
                    <span>{param.maxValue}{param.unit}</span>
                  </div>
                </div>
              )
            })}
          </div>

          {/* 当前结果摘要 */}
          <div className="mt-6 pt-4 border-t border-neutral-100 dark:border-neutral-800">
            <h5 className="text-xs font-semibold text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] uppercase tracking-wider mb-3">实时计算结果</h5>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              {(Object.keys(METRIC_LABELS) as (keyof MetricResult)[]).slice(0, 4).map(metric => {
                const diff = currentResults[metric] - baselineResults[metric]
                const Icon = diff > 0.5 ? TrendingUp : diff < -0.5 ? TrendingDown : Minus
                const color = diff > 0.5 ? 'text-success-600' : diff < -0.5 ? 'text-error-600' : 'text-neutral-600'

                return (
                  <div key={metric} className="flex items-center justify-between p-2 bg-neutral-50 dark:bg-neutral-800 rounded-lg">
                    <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{METRIC_LABELS[metric]}</span>
                    <div className="flex items-center gap-1">
                      <span className="text-sm font-semibold text-neutral-900 dark:text-white">
                        {currentResults[metric]}
                      </span>
                      <Icon className={`w-3 h-3 ${color}`} />
                    </div>
                  </div>
                )
              })}
            </div>
          </div>
        </motion.div>

        {/* 右侧：影响图表 */}
        <motion.div
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          className="bg-white dark:bg-neutral-900 rounded-2xl border border-neutral-200 dark:border-neutral-800 p-5"
        >
          <h4 className="text-sm font-semibold text-neutral-700 dark:text-neutral-300 mb-4">
            参数影响曲线 - {parameters.find(p => p.id === activeParamId)?.name || ''}
          </h4>

          <div className="h-72">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={sensitivityData}>
                <CartesianGrid strokeDasharray="3 3" stroke="var(--color-slate-100, #F0F0F0)" />
                <XAxis
                  dataKey="value"
                  tick={{ fontSize: 12 }}
                  label={{
                    value: `${parameters.find(p => p.id === activeParamId)?.name} (${parameters.find(p => p.id === activeParamId)?.unit})`,
                    position: 'insideBottomRight',
                    offset: -5,
                    fontSize: 12,
                  }}
                />
                <YAxis domain={[0, 100]} tick={{ fontSize: 12 }} />
                <Tooltip
                  contentStyle={{
                    backgroundColor: 'rgba(255,255,255,0.95)',
                    border: '1px solid var(--color-slate-200, #E5E7EB)',
                    borderRadius: '8px',
                    fontSize: '12px',
                  }}
                />

                {(Object.keys(METRIC_LABELS) as (keyof MetricResult)[]).slice(0, 5).map(metric => (
                  <Line
                    key={metric}
                    type="monotone"
                    dataKey={metric}
                    stroke={METRIC_COLORS[metric]}
                    strokeWidth={2}
                    dot={false}
                    activeDot={{ r: 4 }}
                  />
                ))}

                <ReferenceLine
                  x={parameters.find(p => p.id === activeParamId)?.baseValue}
                  stroke="var(--color-primary-500, #10b981)"
                  strokeWidth={2}
                  strokeDasharray="5 5"
                  label={{ value: '基准', position: 'top', fontSize: 12 }}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>

          {/* 图例 */}
          <div className="flex flex-wrap justify-center gap-4 mt-3">
            {(Object.keys(METRIC_LABELS) as (keyof MetricResult)[]).slice(0, 5).map(metric => (
              <div key={metric} className="flex items-center gap-1.5">
                <div className="w-3 h-0.5" style={{ backgroundColor: METRIC_COLORS[metric] }} />
                <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{METRIC_LABELS[metric]}</span>
              </div>
            ))}
          </div>
        </motion.div>
      </div>

      {/* 参数影响热力图 */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="bg-white dark:bg-neutral-900 rounded-2xl border border-neutral-200 dark:border-neutral-800 p-5"
      >
        <h4 className="text-sm font-semibold text-neutral-700 dark:text-neutral-300 mb-4">参数影响热力图</h4>

        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr>
                <th className="py-2 px-3 text-left font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">参数 \\ 指标</th>
                {(Object.keys(METRIC_LABELS) as (keyof MetricResult)[]).map(metric => (
                  <th key={metric} className="py-2 px-3 text-center font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                    {METRIC_LABELS[metric]}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {heatmapData.map((row, idx) => (
                <tr key={idx}>
                  <td className="py-2 px-3 font-medium text-neutral-700 dark:text-neutral-300 whitespace-nowrap">
                    {row.parameter}
                  </td>
                  {(Object.keys(METRIC_LABELS) as (keyof MetricResult)[]).map(metric => {
                    const value = row[metric] as number
                    return (
                      <td
                        key={metric}
                        className="py-2 px-3 text-center cursor-pointer hover:opacity-80 transition-opacity relative"
                        style={{ backgroundColor: getHeatmapColor(value) }}
                        onClick={() =>
                          setShowHeatmapDetail({ param: row.parameter, metric: METRIC_LABELS[metric] })
                        }
                      >
                        <span className={`font-mono text-xs ${Math.abs(value) >= 5 ? 'font-bold' : ''}`}>
                          {value > 0 ? '+' : ''}{value}
                        </span>
                      </td>
                    )
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* 热力图说明 */}
        <div className="mt-3 flex items-center justify-center gap-6 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
          <div className="flex items-center gap-1.5">
            <div className="w-4 h-4 bg-success-500/70 rounded" />
            <span>正向影响</span>
          </div>
          <div className="flex items-center gap-1.5">
            <div className="w-4 h-4 bg-neutral-300 dark:bg-neutral-600 rounded" />
            <span>无影响</span>
          </div>
          <div className="flex items-center gap-1.5">
            <div className="w-4 h-4 bg-error-500/70 rounded" />
            <span>负向影响</span>
          </div>
        </div>
      </motion.div>

      {/* 热力图详情弹窗 */}
      <AnimatePresence>
        {showHeatmapDetail && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/30 flex items-center justify-center z-50"
            onClick={() => setShowHeatmapDetail(null)}
          >
            <motion.div
              initial={{ scale: 0.9 }}
              animate={{ scale: 1 }}
              exit={{ scale: 0.9 }}
              onClick={(e) => e.stopPropagation()}
              className="bg-white dark:bg-neutral-900 rounded-2xl p-6 max-w-md shadow-2xl"
            >
              <div className="flex items-start gap-3 mb-4">
                <Info className="w-5 h-5 text-secondary-500 mt-0.5" />
                <div>
                  <h4 className="font-semibold text-neutral-900 dark:text-white">
                    {showHeatmapDetail.param} → {showHeatmapDetail.metric}
                  </h4>
                  <p className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">
                    该参数的变化对目标指标的影响程度和方向
                  </p>
                </div>
              </div>
              <div className="space-y-2 text-sm text-neutral-600 dark:text-neutral-400">
                <p>• 正值表示参数增加时，该指标上升</p>
                <p>• 负值表示参数增加时，该指标下降</p>
                <p>• 绝对值越大，敏感性越强</p>
                <p>• 建议关注绝对值 &gt; 5 的关键敏感点</p>
              </div>
              <button
                onClick={() => setShowHeatmapDetail(null)}
                className="mt-4 w-full py-2 bg-neutral-100 dark:bg-neutral-800 rounded-lg text-sm font-medium hover:bg-neutral-200 dark:hover:bg-neutral-700 transition-colors"
              >
                关闭
              </button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* 场景对比功能 */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="bg-white dark:bg-neutral-900 rounded-2xl border border-neutral-200 dark:border-neutral-800 p-5"
      >
        <div className="flex items-center justify-between mb-4">
          <h4 className="text-sm font-semibold text-neutral-700 dark:text-neutral-300 flex items-center gap-2">
            <Zap className="w-4 h-4 text-warning-500" />
            场景对比（最多 3 个）
          </h4>
          {scenarios.length < 3 && (
            <button
              onClick={() => {
                const name = prompt('输入场景名称：')
                if (name) saveAsScenario(name)
              }}
              className="px-3 py-1.5 text-xs font-medium text-accent-600 bg-accent-50 dark:bg-accent-300/20 hover:bg-accent-100 dark:hover:bg-accent-900/30 rounded-lg transition-colors"
            >
              + 新增场景
            </button>
          )}
        </div>

        {scenarios.length === 0 ? (
          <p className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] text-center py-4">暂无对比场景</p>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {scenarios.map((scenario, idx) => {
              const isBest = idx === getBestScenario()
              const isActive = idx === activeScenarioIndex

              return (
                <motion.div
                  key={scenario.id}
                  whileHover={{ scale: 1.02 }}
                  onClick={() => setActiveScenarioIndex(idx)}
                  className={`relative p-4 rounded-xl border-2 cursor-pointer transition-all ${
                    isActive
                      ? 'border-accent-500 shadow-lg'
                      : 'border-neutral-200 dark:border-neutral-700 hover:border-neutral-300'
                  } ${isBest ? 'ring-2 ring-warning-400 ring-offset-2' : ''}`}
                >
                  {isBest && (
                    <div className="absolute -top-2 -right-2 bg-warning-400 text-white text-xs px-2 py-0.5 rounded-full font-medium">
                      推荐
                    </div>
                  )}

                  <div className="flex items-center gap-2 mb-3">
                    <div
                      className="w-3 h-3 rounded-full"
                      style={{ backgroundColor: scenario.color }}
                    />
                    <h5 className="font-semibold text-neutral-900 dark:text-white">{scenario.name}</h5>
                  </div>

                  {scenario.results ? (
                    <div className="space-y-2">
                      <div className="text-center pb-2 border-b border-neutral-100 dark:border-neutral-800">
                        <span className="text-2xl font-bold text-neutral-900 dark:text-white">
                          {scenario.results.overall}
                        </span>
                        <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] ml-1">分</span>
                      </div>

                      {(Object.keys(METRIC_LABELS) as (keyof MetricResult)[])
                        .filter(m => m !== 'overall')
                        .map(metric => (
                          <div key={metric} className="flex items-center justify-between text-sm">
                            <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{METRIC_LABELS[metric]}</span>
                            <span className="font-medium text-neutral-900 dark:text-white">
                              {scenario.results?.[metric] || '-'}
                            </span>
                          </div>
                        ))}

                      <button
                        onClick={(e) => {
                          e.stopPropagation()
                          applyScenario(scenario)
                        }}
                        className="w-full mt-2 py-1.5 text-xs font-medium text-accent-600 bg-accent-50 dark:bg-accent-300/20 hover:bg-accent-100 rounded-lg transition-colors flex items-center justify-center gap-1"
                      >
                        <CheckCircle2 className="w-3 h-3" />
                        应用此场景
                      </button>
                    </div>
                  ) : (
                    <div className="text-center py-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] text-sm">
                      点击保存当前配置为场景
                    </div>
                  )}
                </motion.div>
              )
            })}
          </div>
        )}

        {/* 场景对比柱状图 */}
        {scenarios.some(s => s.results) && (
          <div className="mt-6 h-48">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={(Object.keys(METRIC_LABELS) as (keyof MetricResult)[])
                  .filter(m => m !== 'overall')
                  .map(metric => {
                    const bar: any = { name: METRIC_LABELS[metric] }
                    scenarios.forEach(s => {
                      bar[s.name] = s.results?.[metric] || 0
                    })
                    return bar
                  })}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="var(--color-slate-100, #F0F0F0)" />
                <XAxis dataKey="name" tick={{ fontSize: 12 }} />
                <YAxis domain={[0, 100]} tick={{ fontSize: 12 }} />
                <Tooltip />
                <Legend />
                {scenarios
                  .filter(s => s.results)
                  .map(scenario => (
                    <Bar
                      key={scenario.id}
                      dataKey={scenario.name}
                      fill={scenario.color}
                      radius={[4, 4, 0, 0]}
                    />
                  ))}
              </BarChart>
            </ResponsiveContainer>
          </div>
        )}
      </motion.div>
    </div>
  )
}

export default SensitivityAnalysis

/**
 * StabilityPredictTab - 稳定性评估模块 (增强版)
 *
 * 从 35% 提升至 70% 的深度开发版本
 * 集成时间序列图、保质期预测算法、因素分析等核心功能
 *
 * 架构设计：
 * - 左侧：输入与参数配置（40%）
 * - 右侧：可视化结果展示（60%）
 */

import { useState, useCallback, useMemo } from 'react';
import { useMutation } from '@tanstack/react-query';
import { aiApi } from '@/api/ai';
import { logger } from '@/utils/safeLogger';
import { Button, Card, Select, Badge, Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui';
import {
  BarChart3,
  Thermometer,
  Droplets,
  Sun,
  Package,
  Clock,
  AlertTriangle,
  CheckCircle2,
  RotateCcw,
  TrendingDown,
  Info,
} from 'lucide-react';

import { StabilityDegradationChart } from './components/StabilityDegradationChart';

import { stabilityPredictor } from '@/services/stabilityPredictor';
import type { StabilityAssessment, StorageCondition } from '@/types/stability.types';

export function StabilityPredictTab() {
  const [stabilityInput, setStabilityInput] = useState('');
  const [stabilityResult, setStabilityResult] = useState<StabilityAssessment | null>(null);
  const [stabilityError, setStabilityError] = useState<string | null>(null);

  const [temperature, setTemperature] = useState<number>(25);
  const [humidity, setHumidity] = useState<number>(60);
  const [lightExposure, setLightExposure] = useState<'dark' | 'ambient' | 'bright'>('ambient');
  const [packaging, setPackaging] = useState<'sealed' | 'semi-permeable' | 'open'>('sealed');

  /** 后端 risk_factors.type → 可读降解机理名 */
  const DEGRADATION_TYPE_LABELS: Record<string, string> = {
    oxidation: '氧化降解',
    hydrolysis: '水解',
    light_sensitivity: '光敏降解',
    ph_sensitivity: 'pH 敏感',
    high_humidity: '高湿水解',
    unknown_ingredient: '成分参数缺失',
    thermal: '热敏降解',
    microbial: '微生物风险',
  };

  const mutation = useMutation({
    mutationFn: async (names: string[]) => {
      return await aiApi.stabilityPredict(names.map((name) => ({ name })), temperature);
    },
    onSuccess: (data) => {
      const risks = data.risk_factors ?? [];

      // 降解途径：按机理去重（与"关键影响因素"刻意区分）
      const pathways = Array.from(new Set(risks.map((r) => DEGRADATION_TYPE_LABELS[r.type] ?? r.type)));

      // 关键影响因素：按严重度降序取前 5 条完整描述
      const critical = [...risks]
        .sort((a, b) => (b.severity ?? 0) - (a.severity ?? 0))
        .slice(0, 5)
        .map((r) => r.description ?? `${DEGRADATION_TYPE_LABELS[r.type] ?? r.type}（严重度 ${(r.severity ?? 0).toFixed(2)}）`);

      const mapped: StabilityAssessment = {
        score: data.stability_score,
        shelfLifeDays: data.estimated_shelf_life_months * 30,
        degradationPathway: pathways,
        criticalFactors: critical,
        storageRecommendations: data.storage_advice ?? [],
        timeSeriesData: (data.monthly_curve ?? []).map((c) => {
          // 后端 remaining_pct 是 0-1；图表期望 0-100 刻度
          const potency = Math.max(0, Math.min(100, (c.remaining_pct ?? 0) * 100));
          return {
            time: c.month,
            timeUnit: 'month' as const,
            potency,
            // 杂质含量与效力保留互补，不再乘无依据的 ×80 系数
            impurities: Math.max(0, 100 - potency),
          };
        }),
        // 用本地预测器补全 factorContributions
        ...(() => {
          const condition: StorageCondition = { temperature, humidity, lightExposure, packaging };
          const inputNames = stabilityInput.split(/[,，\n]/).map((s) => s.trim()).filter(Boolean);
          const localResult = stabilityPredictor.predict({
            initialPotency: 100,
            targetPotency: 90,
            storageCondition: condition,
            ingredients: inputNames,
          });
          return { factorContributions: localResult.factorContributions };
        })(),
      };
      setStabilityResult(mapped);
      setStabilityError(null);
    },
    onError: (err) => {
      // 原先无 onError 分支，后端 500/404 静默吞掉，用户只看到"没有反应"
      const msg = err instanceof Error ? err.message : '稳定性预测请求失败';
      setStabilityError(msg);
      logger.error('[StabilityPredictTab] predict failed:', err);
    },
  });

  const handlePredict = useCallback(() => {
    const names = stabilityInput
      .split(/[,，\n]/)
      .map((s) => s.trim())
      .filter(Boolean);

    if (names.length === 0) return;

    mutation.mutate(names);
  }, [stabilityInput, temperature, humidity, lightExposure, packaging, mutation]);

  const handleLocalPredict = useCallback(() => {
    const names = stabilityInput
      .split(/[,，\n]/)
      .map((s) => s.trim())
      .filter(Boolean);

    if (names.length === 0) return;

    const condition: StorageCondition = {
      temperature,
      humidity,
      lightExposure,
      packaging,
    };

    const result = stabilityPredictor.predict({
      initialPotency: 100,
      targetPotency: 90,
      storageCondition: condition,
      ingredients: names,
    });

    setStabilityResult(result);
  }, [stabilityInput, temperature, humidity, lightExposure, packaging]);

  const handleClear = useCallback(() => {
    setStabilityInput('');
    setStabilityResult(null);
  }, []);

  const parsedIngredients = useMemo(() => {
    return stabilityInput
      .split(/[,，\n]/)
      .map((s) => s.trim())
      .filter(Boolean);
  }, [stabilityInput]);

  const formatShelfLife = (days: number): string => {
    if (days >= 365) {
      return `${(days / 365).toFixed(1)} 年`;
    } else if (days >= 30) {
      return `${(days / 30).toFixed(1)} 个月`;
    } else {
      return `${Math.round(days)} 天`;
    }
  };

  return (
    <div className="grid grid-cols-12 gap-6 h-full">
      {/* 左侧：输入控制面板 — 玻璃态设计 */}
      <div className="col-span-12 lg:col-span-4 space-y-4">
        <div className="relative group">
          <div className="absolute -inset-0.5 bg-gradient-to-r from-secondary-500 to-info-500 rounded-2xl opacity-0 group-hover:opacity-10 transition-opacity duration-300 blur" />
          <Card className="relative p-6 space-y-5 bg-white/80 dark:bg-neutral-900/80 backdrop-blur-sm rounded-2xl">
            {/* 标题区 */}
            <div className="flex items-start gap-3">
              <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-secondary-500 to-info-600 flex items-center justify-center shadow-md flex-shrink-0">
                <BarChart3 className="w-5 h-5 text-white" />
              </div>
              <div className="flex-1">
                <h2 className="text-base font-bold tracking-tight" style={{ color: 'var(--text-primary)' }}>
                  稳定性评估
                </h2>
                <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-0.5 leading-relaxed">
                  预测配方的化学稳定性和保质期。基于 Arrhenius 方程和 Q10 法则。
                </p>
              </div>
            </div>

            {/* 输入框 */}
            <div>
              <label className="text-xs font-semibold text-neutral-500 dark:text-neutral-400 uppercase tracking-wider mb-2 block">
                配方成分
              </label>
              <textarea
                value={stabilityInput}
                onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setStabilityInput(e.target.value)}
                placeholder={`如：\n黄芪、党参、枸杞子、甘草`}
                rows={4}
                className="w-full px-4 py-3 border border-neutral-200 dark:border-neutral-700
                           rounded-xl text-sm bg-neutral-50 dark:bg-neutral-800/50
                           focus:ring-2 focus:ring-secondary-200 dark:focus:ring-secondary-800 focus:border-secondary-400
                           resize-none transition-all duration-200"
              />
            </div>

            {/* 储存条件配置 — 卡片式分组 */}
            <div className="rounded-xl bg-neutral-50 dark:bg-neutral-800/50 border border-neutral-100 dark:border-neutral-700/50 p-4 space-y-4">
              <div className="flex items-center gap-2">
                <div className="w-6 h-6 rounded-lg bg-secondary-100 dark:bg-secondary-300/25 flex items-center justify-center">
                  <Thermometer className="w-3.5 h-3.5 text-secondary-600 dark:text-secondary-700" />
                </div>
                <h3 className="text-xs font-bold text-neutral-700 dark:text-neutral-300 uppercase tracking-wider">
                  储存条件配置
                </h3>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="text-xs font-semibold text-neutral-500 dark:text-neutral-400 mb-1.5 block uppercase tracking-wider">
                    温度 (°C)
                  </label>
                  <Select value={String(temperature)} onChange={(v) => setTemperature(Number(v))} className="rounded-lg">
                    {[4, 15, 25, 30, 37].map((t) => (
                      <option key={t} value={String(t)}>{t}°C</option>
                    ))}
                  </Select>
                </div>
                <div>
                  <label className="text-xs font-semibold text-neutral-500 dark:text-neutral-400 mb-1.5 block uppercase tracking-wider">
                    湿度 (%)
                  </label>
                  <Select value={String(humidity)} onChange={(v) => setHumidity(Number(v))} className="rounded-lg">
                    {[30, 45, 60, 75, 90].map((h) => (
                      <option key={h} value={String(h)}>{h}%</option>
                    ))}
                  </Select>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="text-xs font-semibold text-neutral-500 dark:text-neutral-400 mb-1.5 block uppercase tracking-wider">
                    光照条件
                  </label>
                  <Select value={lightExposure} onChange={(v) => setLightExposure(v as 'dark' | 'ambient' | 'bright')} className="rounded-lg">
                    <option value="dark">☀️ 避光</option>
                    <option value="ambient">💡 正常</option>
                    <option value="bright">🔆 强光</option>
                  </Select>
                </div>
                <div>
                  <label className="text-xs font-semibold text-neutral-500 dark:text-neutral-400 mb-1.5 block uppercase tracking-wider">
                    包装类型
                  </label>
                  <Select value={packaging} onChange={(v) => setPackaging(v as 'sealed' | 'semi-permeable' | 'open')} className="rounded-lg">
                    <option value="sealed">📦 密封</option>
                    <option value="semi-permeable">🧪 半透膜</option>
                    <option value="open">🌬️ 开放</option>
                  </Select>
                </div>
              </div>
            </div>

            {/* 操作按钮 */}
            <div className="flex gap-2 pt-1">
              <Button
                onClick={handleLocalPredict}
                disabled={!stabilityInput.trim()}
                icon={<BarChart3 className="w-4 h-4" />}
                variant="outline"
                className="flex-1 rounded-xl font-medium border-neutral-200 dark:border-neutral-700"
              >
                本地计算
              </Button>
              <Button
                onClick={handlePredict}
                disabled={!stabilityInput.trim() || mutation.isPending}
                loading={mutation.isPending}
                icon={<TrendingDown className="w-4 h-4" />}
                className="flex-1 rounded-md font-medium transition-colors duration-150"
              >
                AI 分析
              </Button>
            </div>

            <Button
              onClick={handleClear}
              variant="ghost"
              size="sm"
              icon={<RotateCcw className="w-4 h-4" />}
              className="w-full text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-300"
            >
              清空重置
            </Button>
          </Card>
        </div>

        {/* 条件摘要卡片 */}
        {(parsedIngredients.length > 0 || stabilityResult) && (
          <Card className="p-4 rounded-lg">
            <h3 className="text-xs font-semibold uppercase tracking-wider text-neutral-500 dark:text-neutral-400 mb-3">当前评估条件</h3>
            <div className="space-y-2 text-sm">
              <div className="flex items-center justify-between">
                <span className="flex items-center gap-2 text-neutral-600">
                  <Thermometer className="w-4 h-4" /> 温度
                </span>
                <Badge variant={temperature > 30 ? 'danger' : temperature > 25 ? 'warning' : 'success'}>
                  {temperature}°C
                </Badge>
              </div>
              <div className="flex items-center justify-between">
                <span className="flex items-center gap-2 text-neutral-600">
                  <Droplets className="w-4 h-4" /> 湿度
                </span>
                <Badge variant={humidity > 70 ? 'danger' : humidity > 60 ? 'warning' : 'success'}>{humidity}%</Badge>
              </div>
              <div className="flex items-center justify-between">
                <span className="flex items-center gap-2 text-neutral-600">
                  <Sun className="w-4 h-4" /> 光照
                </span>
                <Badge variant={lightExposure === 'bright' ? 'warning' : 'success'}>
                  {lightExposure === 'dark' ? '避光' : lightExposure === 'ambient' ? '正常' : '强光'}
                </Badge>
              </div>
              <div className="flex items-center justify-between">
                <span className="flex items-center gap-2 text-neutral-600">
                  <Package className="w-4 h-4" /> 包装
                </span>
                <Badge
                  variant={packaging === 'open' ? 'danger' : packaging === 'semi-permeable' ? 'warning' : 'success'}
                >
                  {packaging === 'sealed' ? '密封' : packaging === 'semi-permeable' ? '半透膜' : '开放'}
                </Badge>
              </div>
            </div>
          </Card>
        )}
      </div>

      {/* 右侧：可视化结果展示 */}
      <div className="col-span-8">
        {stabilityError && (
          <Card className="mb-4 border-destructive/40 bg-destructive/5 dark:bg-destructive/10">
            <div className="flex items-start gap-3 p-4">
              <AlertTriangle className="w-5 h-5 text-destructive flex-shrink-0 mt-0.5" />
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-destructive">AI 稳定性预测不可用</p>
                <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1 break-all">
                  {stabilityError}
                </p>
                <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">
                  可先使用"本地计算"获得启发式结果，或检查后端稳定性服务是否正常运行。
                </p>
              </div>
            </div>
          </Card>
        )}
        {!stabilityResult ? (
          <Card
            className="h-full flex items-center justify-center bg-gradient-to-br
                           from-secondary-50 to-info-50 dark:from-neutral-800 dark:to-neutral-900"
          >
            <div className="text-center space-y-3 p-8">
              <BarChart3 className="w-16 h-16 mx-auto text-secondary-300 dark:text-secondary-700" />
              <h3 className="text-xl font-semibold text-neutral-700 dark:text-neutral-300">等待输入配方...</h3>
              <p className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] max-w-md">
                在左侧输入成分名称并配置储存条件后，点击"本地计算"或"AI 分析"按钮，
                此处将显示稳定性评分、保质期预测和时间序列分析。
              </p>
            </div>
          </Card>
        ) : (
          <Tabs defaultValue="overview" className="h-full">
            <TabsList className="mb-4">
              <TabsTrigger value="overview" icon={<Info className="w-4 h-4" />}>
                总览
              </TabsTrigger>
              <TabsTrigger value="timeseries" icon={<TrendingDown className="w-4 h-4" />}>
                时间序列
              </TabsTrigger>
              <TabsTrigger value="factors" icon={<AlertTriangle className="w-4 h-4" />}>
                因素分析
              </TabsTrigger>
              <TabsTrigger value="recommendations" icon={<CheckCircle2 className="w-4 h-4" />}>
                建议
              </TabsTrigger>
            </TabsList>

            {/* 总览视图 */}
            <TabsContent value="overview" className="mt-0">
              <Card className="p-6">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                  {/* 稳定性评分 */}
                  <div className="space-y-3">
                    <h3 className="font-semibold text-lg">稳定性评分</h3>
                    <div className="flex items-baseline gap-2">
                      <span className="text-5xl font-bold text-secondary-600">{stabilityResult.score.toFixed(0)}</span>
                      <span className="text-xl text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">/100</span>
                    </div>
                    <div className="w-full bg-neutral-200 rounded-full h-3 overflow-hidden">
                      <div
                        className={`h-full transition-all duration-500 ${
                          stabilityResult.score >= 80
                            ? 'bg-success-500'
                            : stabilityResult.score >= 60
                              ? 'bg-warning-500'
                              : 'bg-error-500'
                        }`}
                        style={{ width: `${stabilityResult.score}%` }}
                      />
                    </div>
                    <p className="text-sm text-neutral-600">
                      {stabilityResult.score >= 80
                        ? '✅ 稳定性良好，适合长期储存'
                        : stabilityResult.score >= 60
                          ? '⚠️ 稳定性一般，建议优化储存条件'
                          : '❌ 稳定性较差，需立即改善储存环境'}
                    </p>
                  </div>

                  {/* 保质期预测 */}
                  <div className="space-y-3">
                    <h3 className="font-semibold text-lg flex items-center gap-2">
                      <Clock className="w-5 h-5" />
                      预测保质期
                    </h3>
                    <div className="text-4xl font-bold text-accent-600">
                      {formatShelfLife(stabilityResult.shelfLifeDays)}
                    </div>
                    <p className="text-sm text-neutral-600">基于当前储存条件和 Arrhenius 动力学模型计算</p>
                  </div>
                </div>

                {/* 关键影响因素 */}
                <div className="mt-6 pt-6 border-t border-neutral-200 dark:border-neutral-700">
                  <h4 className="font-semibold mb-3">关键影响因素</h4>
                  <div className="flex flex-wrap gap-2">
                    {stabilityResult.criticalFactors.map((factor, idx) => (
                      <Badge
                        key={idx}
                        variant={factor.includes('加速') || factor.includes('促进') ? 'warning' : 'neutral'}
                        size="sm"
                      >
                        {factor}
                      </Badge>
                    ))}
                  </div>
                </div>
              </Card>
            </TabsContent>

            {/* 时间序列视图 */}
            <TabsContent value="timeseries" className="mt-0">
              <StabilityDegradationChart result={stabilityResult} />
            </TabsContent>

            {/* 因素分析视图 */}
            <TabsContent value="factors" className="mt-0">
              <Card className="p-6">
                <h3 className="font-semibold mb-4">各因素贡献度分析</h3>
                <div className="space-y-4">
                  {stabilityResult.factorContributions.map((contrib, idx) => (
                    <div key={idx} className="space-y-2">
                      <div className="flex items-center justify-between">
                        <span className="font-medium">{contrib.factor}</span>
                        <Badge variant={contrib.impact > 2 ? 'danger' : contrib.impact > 1.2 ? 'warning' : 'success'}>
                          影响系数: {contrib.impact.toFixed(2)}x
                        </Badge>
                      </div>
                      <div className="w-full bg-neutral-200 rounded-full h-2 overflow-hidden">
                        <div
                          className={`h-full transition-all duration-500 ${
                            contrib.impact > 2 ? 'bg-error-500' : contrib.impact > 1.2 ? 'bg-warning-500' : 'bg-success-500'
                          }`}
                          style={{
                            width: `${Math.min((contrib.impact / 4) * 100, 100)}%`,
                          }}
                        />
                      </div>
                      <p className="text-sm text-neutral-600">{contrib.description}</p>
                    </div>
                  ))}
                </div>
              </Card>
            </TabsContent>

            {/* 建议视图 */}
            <TabsContent value="recommendations" className="mt-0">
              <Card className="p-6 space-y-4">
                <h3 className="font-semibold flex items-center gap-2">
                  <CheckCircle2 className="w-5 h-5 text-success-500" />
                  储存优化建议
                </h3>

                <div className="space-y-3">
                  {stabilityResult.storageRecommendations.map((rec, index) => (
                    <div
                      key={index}
                      className="flex gap-3 p-3 rounded-lg bg-success-50 dark:bg-success-300/20
                                 border border-success-200 dark:border-success-800"
                    >
                      <span
                        className="flex-shrink-0 w-6 h-6 rounded-full bg-success-200
                                      dark:bg-success-800 text-success-800 dark:text-success-200
                                      flex items-center justify-center text-sm font-bold"
                      >
                        {index + 1}
                      </span>
                      <p className="text-sm text-neutral-700 dark:text-neutral-300">{rec}</p>
                    </div>
                  ))}
                </div>

                <div className="pt-4 border-t border-neutral-200 dark:border-neutral-700">
                  <h4 className="font-semibold text-sm mb-2">降解途径说明</h4>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                    {stabilityResult.degradationPathway.map((pathway, idx) => (
                      <div key={idx} className="text-xs px-2 py-1 bg-neutral-100 dark:bg-neutral-800 rounded">
                        • {pathway}
                      </div>
                    ))}
                  </div>
                </div>
              </Card>
            </TabsContent>
          </Tabs>
        )}
      </div>
    </div>
  );
}

export default StabilityPredictTab;

