/** 快速查询：给定药材名，返回所有禁忌配伍 */
export function getContraindications(herbName: string): ContraindicatedPair[] {
  return CONTRAINDICATED_PAIRS.filter(
    p => p.herbA === herbName || p.herbB === herbName,
  )
}

/** 检查两味药材是否存在禁忌关系 */
export function hasContraindication(herbA: string, herbB: string): ContraindicatedPair | null {
  return CONTRAINDICATED_PAIRS.find(
    p => (p.herbA === herbA && p.herbB === herbB) ||
         (p.herbA === herbB && p.herbB === herbA),
  ) ?? null
}

// ── localStorage 键 ───────────────────────────────────────────────────────────
const HISTORY_STORAGE_KEY = 'synergy_analysis_history';
const MAX_HISTORY_ITEMS = 10;

function loadHistory(): SynergyHistoryEntry[] {
  try {
    const raw = localStorage.getItem(HISTORY_STORAGE_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}

function saveHistory(history: SynergyHistoryEntry[]) {
  try {
    localStorage.setItem(HISTORY_STORAGE_KEY, JSON.stringify(history.slice(0, MAX_HISTORY_ITEMS)));
  } catch {
    // localStorage full — ignore
  }
}

function clearHistory() {
  localStorage.removeItem(HISTORY_STORAGE_KEY);
}

// ── 推荐药材（常见配伍场景）────────────────────────────────────────────────────
const SUGGESTED_HERBS = [
  ['黄芪', '当归'], ['枸杞子', '菊花'], ['人参', '五味子'],
  ['丹参', '川芎'], ['金银花', '连翘'], ['黄芩', '黄连'],
  ['白术', '茯苓'], ['陈皮', '半夏'], ['薄荷', '连翘'],
];

// ── 主组件 ─────────────────────────────────────────────────────────────────────

export function SynergyTab() {
  const { t } = useTranslation();
  const [synergyInput, setSynergyInput] = useState('');
  const [synergyResult, setSynergyResult] = useState<SynergyResult | null>(null);
  const [history, setHistory] = useState<SynergyHistoryEntry[]>(loadHistory);
  const [showHistory, setShowHistory] = useState(false);
  const [hoveredCell, setHoveredCell] = useState<string | null>(null);

  // 加载历史
  useEffect(() => {
    setHistory(loadHistory());
  }, []);

  const mutation = useMutation({
    mutationFn: (names: string[]) => aiApi.synergyAnalysis(names),
    onSuccess: (data) => {
      setSynergyResult(data);
      // 保存历史记录
      const entry: SynergyHistoryEntry = {
        id: Date.now().toString(),
        timestamp: Date.now(),
        herbs: data.synergy_pairs?.map((p) => p.a).filter(Boolean) || [],
        score: data.score ?? 0,
        synergyCount: data.synergy_pairs?.length ?? 0,
        antagonismCount: data.antagonism_warnings?.length ?? 0,
      };
      // 去重：相同药材组合不重复记录
      const key = [...entry.herbs].sort().join(',');
      setHistory((prev) => {
        const filtered = prev.filter((h) => [...h.herbs].sort().join(',') !== key);
        const next = [entry, ...filtered].slice(0, MAX_HISTORY_ITEMS);
        saveHistory(next);
        return next;
      });
    },
    onError: (error: unknown) => {
      logger.error('协同分析失败:', error);
    },
  });

  const handleAnalysis = useCallback(() => {
    const names = synergyInput
      .split(/[,，\n]/)
      .map((s) => s.trim())
      .filter(Boolean);
    if (names.length < 2) return;
    mutation.mutate(names);
  }, [synergyInput, mutation]);

  // ── 矩阵数据计算 ────────────────────────────────────────────────────────────
  const matrixData = useMemo(() => {
    if (!synergyResult) return null;
    const herbSet = new Set<string>();
    synergyResult.synergy_pairs?.forEach((p) => { herbSet.add(p.a); herbSet.add(p.b); });
    synergyResult.antagonism_warnings?.forEach((w) => { herbSet.add(w.a); herbSet.add(w.b); });
    const herbs = Array.from(herbSet);
    if (herbs.length === 0) return null;

    const matrix: Record<string, Record<string, { value: number; type: 'synergy' | 'antagonism' | 'none' }>> = {};
    herbs.forEach((h) => { matrix[h] = {}; });
    herbs.forEach((h1) => {
      herbs.forEach((h2) => {
        if (h1 === h2) { matrix[h1][h2] = { value: 0, type: 'none' }; return; }
        const synPair = synergyResult.synergy_pairs?.find(
          (p) => (p.a === h1 && p.b === h2) || (p.a === h2 && p.b === h1),
        );
        const antPair = synergyResult.antagonism_warnings?.find(
          (w) => (w.a === h1 && w.b === h2) || (w.a === h2 && w.b === h1),
        );
        if (synPair) matrix[h1][h2] = { value: synPair.score, type: 'synergy' };
        else if (antPair) matrix[h1][h2] = { value: -1, type: 'antagonism' };
        else matrix[h1][h2] = { value: 0, type: 'none' };
      });
    });
    return { herbs, matrix };
  }, [synergyResult]);

  // ── 禁忌高亮：检查输入药材是否在十八反十九畏中 ─────────────────────────────
  const contraindicationWarnings = useMemo(() => {
    if (!synergyInput.trim()) return [];
    const inputHerbs = synergyInput.split(/[,，\n]/).map((s) => s.trim()).filter(Boolean);
    const warnings: { a: string; b: string; type: string; severity: string }[] = [];
    inputHerbs.forEach((h1) => {
      CONTRAINDICATED_PAIRS.forEach(({ herbA, herbB, type, severity }) => {
        if (h1 === herbA && inputHerbs.includes(herbB)) {
          warnings.push({ a: herbA, b: herbB, type, severity });
        } else if (h1 === herbB && inputHerbs.includes(herbA)) {
          warnings.push({ a: herbB, b: herbA, type, severity });
        }
      });
    });
    // 去重
    const seen = new Set<string>();
    return warnings.filter(w => {
      const key = [w.a, w.b].sort().join('-');
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  }, [synergyInput]);

  // ── 推荐添加药材（点击添加到输入框）─────────────────────────────────────────
  const handleAddHerb = useCallback((herb: string) => {
    const current = synergyInput.trim();
    const herbs = current ? current.split(/[,，\n]/).map((s) => s.trim()).filter(Boolean) : [];
    if (!herbs.includes(herb)) {
      setSynergyInput(current ? `${current}, ${herb}` : herb);
    }
  }, [synergyInput]);

  // ── 加载历史记录 ────────────────────────────────────────────────────────────
  const handleLoadHistory = useCallback((entry: SynergyHistoryEntry) => {
    setSynergyInput(entry.herbs.join(', '));
    setShowHistory(false);
  }, []);

  const handleClearHistory = useCallback(() => {
    clearHistory();
    setHistory([]);
  }, []);

  return (
    <div className="space-y-5">
      {/* ── 输入区域 ── */}
      <Card className="p-6 space-y-4">
        <div>
          <h2 className="text-lg font-semibold flex items-center gap-2">
            <GitMerge className="w-5 h-5 text-primary-500" />
            {t('ai.synergy.synergyTab.title')}
          </h2>
          <p className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">{t('ai.synergy.synergyTab.inputDescription')}</p>
        </div>

        <div className="flex gap-3">
          <Input
            value={synergyInput}
            onChange={(e) => setSynergyInput(e.target.value)}
            placeholder={t('ai.synergy.synergyTab.inputPlaceholder')}
            onKeyDown={(e) => e.key === 'Enter' && handleAnalysis()}
            className="flex-1"
          />
          <Button
            disabled={!synergyInput.trim() || mutation.isPending}
            onClick={handleAnalysis}
            loading={mutation.isPending}
            icon={<GitMerge className="w-4 h-4" />}
          >
            {t('ai.synergy.synergyTab.analyze')}
          </Button>
        </div>

        {/* 推荐药材快捷添加 */}
        <div className="flex flex-wrap gap-2 items-center">
          <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] flex items-center gap-1">
            <Star className="w-3 h-3" /> 快速添加：
          </span>
          {SUGGESTED_HERBS.flat().slice(0, 8).map((herb) => (
            <button
              key={herb}
              onClick={() => handleAddHerb(herb)}
              className="px-2 py-1 text-xs rounded-full border border-neutral-200 dark:border-neutral-700 text-neutral-600 dark:text-neutral-400 hover:border-primary-400 hover:text-primary-700 transition-colors flex items-center gap-1"
            >
              <Plus className="w-3 h-3" /> {herb}
            </button>
          ))}
        </div>

        {/* 禁忌警告 */}
        {contraindicationWarnings.length > 0 && (
          <div className="bg-warning-50 dark:bg-warning-300/20 border border-warning-300 dark:border-warning-700/50 rounded-xl p-4 flex items-start gap-3">
            <AlertTriangle className="w-5 h-5 text-warning-500 flex-shrink-0 mt-0.5" />
            <div>
              <p className="font-medium text-warning-700 dark:text-warning-700 text-sm">
                发现十八反禁忌组合
              </p>
              <ul className="mt-2 space-y-1 text-sm text-warning-600 dark:text-warning-700">
                {contraindicationWarnings.map((w, i) => (
                  <li key={i}>⚠ {w.a} + {w.b}：{w.type}</li>
                ))}
              </ul>
            </div>
          </div>
        )}

        {mutation.isError && (
          <div className="bg-danger-50 dark:bg-danger-500/10 border border-danger-200 dark:border-danger-500/20 rounded-xl p-5 text-sm text-danger-600 dark:text-danger-600">
            {t('ai.synergy.synergyTab.analyzeFailed')}
          </div>
        )}
      </Card>

      {/* ── 结果区域 ── */}
      {synergyResult && matrixData && (
        <div className="space-y-5 animate-fade-in">
          {/* 摘要卡片 */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div className="border border-primary-200 dark:border-primary-800 rounded-xl p-4 bg-primary-50/50 dark:bg-primary-300/15">
              <div className="text-2xl font-bold text-primary-700">{synergyResult.score ?? 0}</div>
              <div className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">综合协同评分</div>
            </div>
            <div className="border border-success-200 dark:border-success-800 rounded-xl p-4 bg-success-50/50 dark:bg-success-300/15">
              <div className="text-2xl font-bold text-success-600">
                {synergyResult.synergy_pairs?.length ?? 0}
              </div>
              <div className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">协同配对</div>
            </div>
            <div className="border border-danger-200 dark:border-danger-800 rounded-xl p-4 bg-danger-50/50 dark:bg-danger-500/10">
              <div className="text-2xl font-bold text-danger-600">
                {synergyResult.antagonism_warnings?.length ?? 0}
              </div>
              <div className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">配伍禁忌</div>
            </div>
          </div>

          {/* 交互热力图 */}
          <div>
            <h4 className="font-semibold text-neutral-900 dark:text-white mb-4">
              配伍关系矩阵
            </h4>
            <div className="overflow-x-auto rounded-xl border border-neutral-200 dark:border-neutral-700">
              <table className="border-collapse text-sm w-full">
                <thead>
                  <tr>
                    <th className="p-3 text-neutral-400 font-normal bg-neutral-50 dark:bg-neutral-800/50" />
                    {matrixData.herbs.map((h) => (
                      <th key={h} className="p-3 text-neutral-600 dark:text-neutral-300 font-medium whitespace-nowrap bg-neutral-50 dark:bg-neutral-800/50">
                        {h}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {matrixData.herbs.map((h1) => (
                    <tr key={h1}>
                      <td className="p-3 text-neutral-600 dark:text-neutral-300 font-medium whitespace-nowrap bg-neutral-50 dark:bg-neutral-800/50 border-r border-neutral-200 dark:border-neutral-700">
                        {h1}
                      </td>
                      {matrixData.herbs.map((h2) => {
                        const cell = matrixData.matrix[h1][h2];
                        const isHovered = hoveredCell === `${h1}-${h2}`;
                        let bgClass = 'bg-neutral-50 dark:bg-neutral-800/30';
                        let textColor = 'text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]';
                        let content = '—';
                        if (h1 === h2) {
                          bgClass = 'bg-neutral-100 dark:bg-neutral-700/50';
                          content = '·';
                        } else if (cell.type === 'synergy') {
                          const intensity = Math.min(cell.value, 1);
                          // 修复 D-55 同源动态类 bug：原 `bg-primary-${Math.round(intensity*200)}00`
                          // 生成 000/010/020... 等不存在档位（Tailwind 色阶为 50-950），JIT 0 生成 →
                          // 热力图整行无背景。改为映射到真实色阶档位（100-500）+ 暗色不反转的 /alpha。
                          const step = Math.min(5, Math.max(1, Math.round(intensity * 5)));
                          const tier = [100, 200, 300, 400, 500][step - 1];
                          bgClass = `bg-primary-${tier}/15 dark:bg-primary-${tier}/30`;
                          textColor = 'text-primary-700 dark:text-primary-700';
                          content = cell.value.toFixed(2);
                        } else if (cell.type === 'antagonism') {
                          bgClass = 'bg-danger-100 dark:bg-danger-500/20';
                          textColor = 'text-danger-700 dark:text-danger-600';
                          content = '!';
                        }
                        return (
                          <td
                            key={h2}
                            className={`p-3 text-center rounded cursor-pointer transition-all duration-150 border border-transparent ${bgClass} ${textColor} ${isHovered ? 'ring-2 ring-primary-500 scale-105' : ''}`}
                            onMouseEnter={() => setHoveredCell(`${h1}-${h2}`)}
                            onMouseLeave={() => setHoveredCell(null)}
                          >
                            {content}
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            {/* 悬浮提示 */}
            {hoveredCell && matrixData && (() => {
              const [h1, h2] = hoveredCell.split('-');
              const cell = matrixData.matrix[h1]?.[h2];
              if (!cell || cell.type === 'none') return null;
              return (
                <div className="mt-2 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                  {cell.type === 'synergy'
                    ? `✓ ${h1} + ${h2}：协同评分 ${cell.value.toFixed(2)}`
                    : `⚠ ${h1} + ${h2}：存在配伍禁忌`
                  }
                </div>
              );
            })()}
            <div className="flex gap-4 mt-3 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
              <span className="flex items-center gap-1">
                <span className="inline-block w-3 h-3 rounded bg-primary-200 dark:bg-primary-800/40" /> 协同（颜色越深评分越高）
              </span>
              <span className="flex items-center gap-1">
                <span className="inline-block w-3 h-3 rounded bg-danger-200 dark:bg-danger-500/30" /> 配伍禁忌
              </span>
            </div>
          </div>

          {/* 协同配对详情 */}
          {synergyResult.synergy_pairs && synergyResult.synergy_pairs.length > 0 && (
            <div className="border border-primary-200 dark:border-primary-800 rounded-xl p-5 bg-primary-50/30 dark:bg-primary-300/15">
              <h4 className="font-semibold text-primary-700 dark:text-primary-700 mb-3">
                协同配对列表
              </h4>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                {synergyResult.synergy_pairs.map((p, i) => (
                  <div key={i} className="flex items-center gap-3 p-3 bg-white dark:bg-neutral-800 rounded-lg border border-primary-100 dark:border-primary-900/30">
                    <span className="text-primary-500 font-medium">+</span>
                    <span className="text-neutral-700 dark:text-neutral-300 text-sm flex-1">{p.a}</span>
                    <span className="text-primary-500 font-medium">+</span>
                    <span className="text-neutral-700 dark:text-neutral-300 text-sm flex-1">{p.b}</span>
                    <span className="text-xs font-mono text-primary-700 bg-primary-50 dark:bg-primary-300/25 px-2 py-1 rounded">
                      {p.score.toFixed(2)}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* 配伍禁忌详情 */}
          {synergyResult.antagonism_warnings && synergyResult.antagonism_warnings.length > 0 && (
            <div className="border border-danger-200 dark:border-danger-800 rounded-xl p-5 bg-danger-50/30 dark:bg-danger-300/15">
              <h4 className="font-semibold text-danger-700 dark:text-danger-600 mb-3 flex items-center gap-2">
                <AlertTriangle className="w-4 h-4" />
                配伍禁忌警告
              </h4>
              <div className="space-y-2">
                {synergyResult.antagonism_warnings.map((w, i) => (
                  <div key={i} className="flex items-center gap-3 p-3 bg-white dark:bg-neutral-800 rounded-lg border border-danger-100 dark:border-danger-900/30">
                    <span className="text-danger-500 font-medium">!</span>
                    <span className="text-neutral-700 dark:text-neutral-300 text-sm">{w.a}</span>
                    <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">+</span>
                    <span className="text-neutral-700 dark:text-neutral-300 text-sm">{w.b}</span>
                    {w.reason && (
                      <span className="text-xs text-danger-500 ml-auto">{w.reason}</span>
                    )}
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {/* ── 历史记录面板 ── */}
      <div className="relative">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => setShowHistory(!showHistory)}
          icon={<History className="w-4 h-4" />}
          className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]"
        >
          分析历史 ({history.length})
        </Button>
        {showHistory && history.length > 0 && (
          <div className="absolute z-10 top-full left-0 mt-2 w-80 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl shadow-lg p-4 space-y-3">
            <div className="flex items-center justify-between">
              <span className="text-sm font-medium text-neutral-600 dark:text-neutral-400">最近分析</span>
              <button
                onClick={handleClearHistory}
                className="text-xs text-danger-500 hover:text-danger-700 flex items-center gap-1"
              >
                <Trash2 className="w-3 h-3" /> 清空
              </button>
            </div>
            <div className="space-y-2 max-h-60 overflow-y-auto">
              {history.map((entry) => (
                <button
                  key={entry.id}
                  onClick={() => handleLoadHistory(entry)}
                  className="w-full text-left p-3 rounded-lg border border-neutral-100 dark:border-neutral-700 hover:border-primary-300 dark:hover:border-primary-700 transition-colors"
                >
                  <div className="flex items-center gap-2 text-sm text-neutral-700 dark:text-neutral-300 truncate">
                    {entry.herbs.slice(0, 3).join(' + ')}
                    {entry.herbs.length > 3 && <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">…(+{entry.herbs.length - 3})</span>}
                  </div>
                  <div className="flex items-center gap-3 mt-1 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                    <span>评分 {entry.score.toFixed(2)}</span>
                    <span className="text-success-500">{entry.synergyCount} 协同</span>
                    {entry.antagonismCount > 0 && (
                      <span className="text-danger-500">{entry.antagonismCount} 禁忌</span>
                    )}
                    <span className="ml-auto">
                      {new Date(entry.timestamp).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' })}
                    </span>
                  </div>
                </button>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * TastePredictTab - 口感预测模块 (增强版)
 *
 * 从 35% 提升至 75% 的深度开发版本
 * 集成风味轮、雷达图、本地算法、成分映射表等核心功能
 *
 * 架构设计：
 * - 左侧：输入控制面板（40%）
 * - 右侧：可视化结果展示（60%）
 */

import { useState, useCallback, useMemo } from 'react';
import { useMutation } from '@tanstack/react-query';
import { aiApi } from '@/api/ai';
import { Button, Card, Select, Badge, Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui';
import { Cherry, FlaskConical, BarChart3, Table2, Lightbulb, RotateCcw, History } from 'lucide-react';

import { FlavorWheel } from '@/components/ai/visualization/FlavorWheel';
import { TasteRadarChart } from '@/components/ai/visualization/TasteRadarChart';
import { localTastePredictor } from '@/services/tastePredictor';
import { TastePrediction, FiveTastes } from '@/types/taste.types';
import {
  FIVE_TASTES_LABELS,
  FIVE_TASTES_COLORS,
  INGREDIENT_TASTE_DATABASE,
  PROCESSING_METHODS,
} from '@/types/taste.types';

interface IngredientInput {
  name: string;
  amount?: number;
  unit?: string;
  processingMethod?: string;
}

function computeAvgSour(names: string[]): number {
  let total = 0, count = 0;
  for (const name of names) {
    const profile = INGREDIENT_TASTE_DATABASE[name];
    if (profile) { total += profile.sour; count++; }
  }
  return count > 0 ? Math.round(total / count) : 0;
}

export function TastePredictTab() {
  const [tasteInput, setTasteInput] = useState('');
  const [, setIngredients] = useState<IngredientInput[]>([]);
  const [processingMethod, setProcessingMethod] = useState<string>('');
  const [algorithmMode, setAlgorithmMode] = useState<'weighted' | 'synergy'>('weighted');
  const [tasteResult, setTasteResult] = useState<TastePrediction | null>(null);
  const [historyResults, setHistoryResults] = useState<TastePrediction[]>([]);

  const mutation = useMutation({
    mutationFn: async (names: string[]) => {
      return await aiApi.tastePredict(names.map((name) => ({ name })));
    },
    onSuccess: (data) => {
      const names = tasteInput.split(/[,，\n]/).map((s) => s.trim()).filter(Boolean);
      const mapped: TastePrediction = {
        score: data.overall_score,
        dominantTaste:
          data.sweetness >= data.bitterness && data.sweetness >= data.astringency
            ? FiveTastes.SWEET
            : data.bitterness >= data.astringency
              ? FiveTastes.BITTER
              : FiveTastes.SOUR,
        dominantIntensity: Math.max(data.sweetness, data.bitterness, data.astringency),
        profile: {
          sweet: data.sweetness,
          sour: computeAvgSour(names),
          bitter: data.bitterness,
          pungent: data.pungency ?? 0,
          salty: data.saltiness ?? 0,
          bland: 0,
        },
        features: data.flavor_notes,
        description: '',
        // 用本地预测器补全 suggestions 和 contributions
        ...(() => {
          const localInput = names.map((n) => ({ name: n, processingMethod }));
          const localResult = localTastePredictor.predict({ ingredients: localInput, algorithmMode });
          return { suggestions: localResult.suggestions, contributions: localResult.contributions };
        })(),
      };
      setTasteResult(mapped);
      if (!historyResults.find((r) => r.score === mapped.score)) {
        setHistoryResults((prev) => [mapped, ...prev].slice(0, 5));
      }
    },
  });

  const handlePredict = useCallback(() => {
    const names = tasteInput
      .split(/[,，\n]/)
      .map((s) => s.trim())
      .filter(Boolean);

    if (names.length === 0) return;

    setIngredients(names.map((n) => ({ name: n, processingMethod })));
    mutation.mutate(names);
  }, [tasteInput, processingMethod, algorithmMode, mutation]);

  const handleLocalPredict = useCallback(() => {
    const names = tasteInput
      .split(/[,，\n]/)
      .map((s) => s.trim())
      .filter(Boolean);

    if (names.length === 0) return;

    const inputIngredients = names.map((n) => ({
      name: n,
      processingMethod: processingMethod || undefined,
    }));

    setIngredients(inputIngredients);

    const result = localTastePredictor.predict({
      ingredients: inputIngredients,
      algorithmMode,
    });

    setTasteResult(result);
    if (!historyResults.find((r) => r.score === result.score)) {
      setHistoryResults((prev) => [result, ...prev].slice(0, 5));
    }
  }, [tasteInput, processingMethod, algorithmMode]);

  const handleClear = useCallback(() => {
    setTasteInput('');
    setIngredients([]);
    setTasteResult(null);
    setProcessingMethod('');
  }, []);

  const parsedIngredients = useMemo(() => {
    return tasteInput
      .split(/[,，\n]/)
      .map((s) => s.trim())
      .filter(Boolean);
  }, [tasteInput]);

  const ingredientProfiles = useMemo(() => {
    return parsedIngredients.map((name) => ({
      name,
      profile: INGREDIENT_TASTE_DATABASE[name] || null,
      hasData: !!INGREDIENT_TASTE_DATABASE[name],
    }));
  }, [parsedIngredients]);

  return (
    <div className="grid grid-cols-12 gap-6 h-full">
      {/* 左侧：输入控制面板 — 玻璃态设计 */}
      <div className="col-span-12 lg:col-span-4 space-y-4">
        <div className="relative group">
          <div className="absolute -inset-0.5 bg-gradient-to-r from-warning-500 to-danger-500 rounded-2xl opacity-0 group-hover:opacity-10 transition-opacity duration-300 blur" />
          <Card className="relative p-6 space-y-5 bg-white/80 dark:bg-neutral-900/80 backdrop-blur-sm rounded-2xl">
            {/* 标题区 */}
            <div className="flex items-start gap-3">
              <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-warning-500 to-danger-600 flex items-center justify-center shadow-md flex-shrink-0">
                <Cherry className="w-5 h-5 text-white" />
              </div>
              <div className="flex-1">
                <h2 className="text-base font-bold tracking-tight" style={{ color: 'var(--text-primary)' }}>
                  口感预测
                </h2>
                <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-0.5 leading-relaxed">
                  输入药材名称，支持本地快速预测和 AI 深度分析
                </p>
              </div>
            </div>

            {/* 输入框 */}
            <div>
              <label className="text-xs font-semibold text-neutral-500 dark:text-neutral-400 uppercase tracking-wider mb-2 block">
                药材配方
              </label>
              <textarea
                value={tasteInput}
                onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setTasteInput(e.target.value)}
                placeholder={`如：\n黄芪、党参、枸杞子、山药、甘草`}
                rows={4}
                className="w-full px-4 py-3 border border-neutral-200 dark:border-neutral-700
                           rounded-xl text-sm bg-neutral-50 dark:bg-neutral-800/50
                           focus:ring-2 focus:ring-warning-200 dark:focus:ring-warning-800 focus:border-warning-400
                           resize-none transition-all duration-200"
              />
            </div>

            {/* 参数配置 — 选择器样式 */}
            <div className="space-y-3">
              <div>
                <label className="text-xs font-semibold text-neutral-500 dark:text-neutral-400 uppercase tracking-wider mb-2 block">
                  炮制方法（可选）
                </label>
                <Select
                  value={processingMethod}
                  onChange={(v) => setProcessingMethod(v)}
                  placeholder="选择炮制方法..."
                  className="rounded-xl"
                >
                  <option value="">无</option>
                  {PROCESSING_METHODS.map((method) => (
                    <option key={method.name} value={method.name}>
                      {method.name} - {method.description}
                    </option>
                  ))}
                </Select>
              </div>

              <div>
                <label className="text-xs font-semibold text-neutral-500 dark:text-neutral-400 uppercase tracking-wider mb-2 block">
                  算法模式
                </label>
                <div className="flex gap-2">
                  <button
                    onClick={() => setAlgorithmMode('weighted')}
                    className={`flex-1 px-3 py-2 rounded-xl text-xs font-medium transition-all duration-200 border ${
                      algorithmMode === 'weighted'
                        ? 'bg-warning-50 dark:bg-warning-300/20 border-warning-300 dark:border-warning-700 text-warning-700 dark:text-warning-700 shadow-sm'
                        : 'bg-neutral-50 dark:bg-neutral-800/50 border-neutral-200 dark:border-neutral-700 text-neutral-600 dark:text-neutral-400 hover:border-warning-200'
                    }`}
                  >
                    <div className="font-semibold">加权平均</div>
                    <div className="text-xs opacity-70 mt-0.5">快速计算</div>
                  </button>
                  <button
                    onClick={() => setAlgorithmMode('synergy')}
                    className={`flex-1 px-3 py-2 rounded-xl text-xs font-medium transition-all duration-200 border ${
                      algorithmMode === 'synergy'
                        ? 'bg-warning-50 dark:bg-warning-300/20 border-warning-300 dark:border-warning-700 text-warning-700 dark:text-warning-700 shadow-sm'
                        : 'bg-neutral-50 dark:bg-neutral-800/50 border-neutral-200 dark:border-neutral-700 text-neutral-600 dark:text-neutral-400 hover:border-warning-200'
                    }`}
                  >
                    <div className="font-semibold">协同分析</div>
                    <div className="text-xs opacity-70 mt-0.5">精确预测</div>
                  </button>
                </div>
              </div>
            </div>

            {/* 操作按钮 — 渐变按钮 */}
            <div className="flex gap-2 pt-1">
              <Button
                onClick={handleLocalPredict}
                disabled={!tasteInput.trim()}
                icon={<FlaskConical className="w-4 h-4" />}
                variant="outline"
                className="flex-1 rounded-xl font-medium border-neutral-200 dark:border-neutral-700"
              >
                本地预测
              </Button>
              <Button
                onClick={handlePredict}
                disabled={!tasteInput.trim() || mutation.isPending}
                loading={mutation.isPending}
                icon={<Cherry className="w-4 h-4" />}
                className="flex-1 rounded-md font-medium transition-colors duration-150"
              >
                AI 分析
              </Button>
            </div>

            <Button
              onClick={handleClear}
              variant="ghost"
              size="sm"
              icon={<RotateCcw className="w-4 h-4" />}
              className="w-full text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-300"
            >
              清空重置
            </Button>
          </Card>
        </div>

        {/* 成分预览卡片 */}
        {ingredientProfiles.length > 0 && (
          <Card className="p-4 rounded-lg">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-sm font-bold flex items-center gap-2" style={{ color: 'var(--text-primary)' }}>
                <div className="w-6 h-6 rounded-lg bg-warning-100 dark:bg-warning-300/25 flex items-center justify-center">
                  <Table2 className="w-3.5 h-3.5 text-warning-600 dark:text-warning-700" />
                </div>
                成分列表
                <span className="text-xs font-medium px-2 py-0.5 rounded-full bg-warning-100 dark:bg-warning-300/25 text-warning-600 dark:text-warning-700">
                  {ingredientProfiles.length}
                </span>
              </h3>
            </div>
            <div className="space-y-2 max-h-56 overflow-y-auto pr-1">
              {ingredientProfiles.map((item, index) => (
                <div
                  key={index}
                  className="flex items-center justify-between p-2.5 rounded-md bg-neutral-50 dark:bg-neutral-800/50 text-sm hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors"
                >
                  <span className="font-medium text-neutral-700 dark:text-neutral-300">{item.name}</span>
                  <Badge variant={item.hasData ? 'success' : 'warning'} size="sm" className="rounded-full px-2.5 py-0.5">
                    {item.hasData ? '✓ 有数据' : '○ 待补充'}
                  </Badge>
                </div>
              ))}
            </div>
          </Card>
        )}
      </div>

      {/* 右侧：可视化结果展示 */}
      <div className="col-span-8">
        {!tasteResult ? (
          <Card
            className="h-full flex items-center justify-center bg-gradient-to-br
                           from-error-50 to-warning-50 dark:from-neutral-800 dark:to-neutral-900"
          >
            <div className="text-center space-y-3 p-8">
              <Cherry className="w-16 h-16 mx-auto text-error-300 dark:text-error-600" />
              <h3 className="text-xl font-semibold text-neutral-700 dark:text-neutral-300">等待输入配方...</h3>
              <p className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] max-w-md">
                在左侧输入药材名称后，点击"本地预测"或"AI 分析"按钮， 此处将显示五味分布、口感评分和优化建议。
              </p>
            </div>
          </Card>
        ) : (
          <Tabs defaultValue="wheel" className="h-full">
            <TabsList className="mb-4">
              <TabsTrigger value="wheel" icon={<BarChart3 className="w-4 h-4" />}>
                风味轮
              </TabsTrigger>
              <TabsTrigger value="radar" icon={<BarChart3 className="w-4 h-4" />}>
                雷达图
              </TabsTrigger>
              <TabsTrigger value="details" icon={<Table2 className="w-4 h-4" />}>
                详细数据
              </TabsTrigger>
              <TabsTrigger value="suggestions" icon={<Lightbulb className="w-4 h-4" />}>
                优化建议
              </TabsTrigger>
            </TabsList>

            {/* 风味轮视图 */}
            <TabsContent value="wheel" className="mt-0">
              <Card className="p-6">
                <div className="flex flex-col lg:flex-row items-center gap-8">
                  <FlavorWheel data={tasteResult.profile} size={320} />

                  <div className="flex-1 space-y-4">
                    <div>
                      <h3 className="text-lg font-semibold text-neutral-900 dark:text-neutral-100">综合评分</h3>
                      <div className="flex items-baseline gap-2 mt-1">
                        <span className="text-4xl font-bold text-secondary-600">{(tasteResult.score * 100).toFixed(0)}</span>
                        <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">/ 100</span>
                      </div>
                      <p className="text-sm text-neutral-600 mt-2">{tasteResult.description}</p>
                    </div>

                    <div>
                      <h4 className="font-semibold text-sm mb-2">主导口味</h4>
                      <div className="flex items-center gap-2">
                        <div
                          className="w-4 h-4 rounded-full"
                          style={{
                            backgroundColor: FIVE_TASTES_COLORS[tasteResult.dominantTaste],
                          }}
                        />
                        <span className="font-medium">{FIVE_TASTES_LABELS[tasteResult.dominantTaste]}</span>
                        <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">({tasteResult.dominantIntensity.toFixed(1)})</span>
                      </div>
                    </div>

                    <div>
                      <h4 className="font-semibold text-sm mb-2">口感特征</h4>
                      <div className="flex flex-wrap gap-2">
                        {tasteResult.features.map((feature, i) => (
                          <Badge key={i} variant="neutral" size="sm">
                            {feature}
                          </Badge>
                        ))}
                      </div>
                    </div>
                  </div>
                </div>
              </Card>
            </TabsContent>

            {/* 雷达图视图 */}
            <TabsContent value="radar" className="mt-0">
              <Card className="p-6">
                <TasteRadarChart
                  primaryData={tasteResult.profile}
                  comparisonData={
                    historyResults.length > 0
                      ? [
                          {
                            label: '历史记录 #1',
                            data: historyResults[0].profile,
                            color: 'var(--color-primary-400)',
                          },
                        ]
                      : undefined
                  }
                  height={420}
                />
              </Card>
            </TabsContent>

            {/* 详细数据视图 */}
            <TabsContent value="details" className="mt-0">
              <Card className="p-6">
                <h3 className="font-semibold mb-4">成分贡献分析</h3>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-neutral-200 dark:border-neutral-700">
                        <th className="text-left py-2 px-3">成分</th>
                        <th className="text-center py-2 px-2">甘</th>
                        <th className="text-center py-2 px-2">酸</th>
                        <th className="text-center py-2 px-2">苦</th>
                        <th className="text-center py-2 px-2">辛</th>
                        <th className="text-center py-2 px-2">咸</th>
                        <th className="text-center py-2 px-2">淡</th>
                        <th className="text-right py-2 px-3">权重</th>
                      </tr>
                    </thead>
                    <tbody>
                      {tasteResult.contributions.map((contrib, idx) => (
                        <tr key={idx} className="border-b border-neutral-100 dark:border-neutral-800">
                          <td className="py-2 px-3 font-medium">{contrib.name}</td>
                          {(Object.keys(contrib.profile) as (keyof typeof contrib.profile)[]).map((taste) => (
                            <td key={taste} className="text-center py-2 px-2">
                              {contrib.profile[taste].toFixed(0)}
                            </td>
                          ))}
                          <td className="text-right py-2 px-3 text-neutral-600">
                            {(contrib.percentage || 0).toFixed(1)}%
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </Card>
            </TabsContent>

            {/* 优化建议视图 */}
            <TabsContent value="suggestions" className="mt-0">
              <Card className="p-6 space-y-4">
                <h3 className="font-semibold flex items-center gap-2">
                  <Lightbulb className="w-5 h-5 text-warning-500" />
                  优化建议
                </h3>

                <div className="space-y-3">
                  {tasteResult.suggestions.map((suggestion, index) => (
                    <div
                      key={index}
                      className="flex gap-3 p-3 rounded-lg bg-warning-50 dark:bg-warning-300/20
                                 border border-warning-200 dark:border-warning-800"
                    >
                      <span
                        className="flex-shrink-0 w-6 h-6 rounded-full bg-warning-200
                                      dark:bg-warning-800 text-warning-800 dark:text-warning-200
                                      flex items-center justify-center text-sm font-bold"
                      >
                        {index + 1}
                      </span>
                      <p className="text-sm text-neutral-700 dark:text-neutral-300">{suggestion}</p>
                    </div>
                  ))}
                </div>

                {historyResults.length > 0 && (
                  <div className="pt-4 border-t border-neutral-200 dark:border-neutral-700">
                    <h4 className="font-semibold text-sm mb-2 flex items-center gap-2">
                      <History className="w-4 h-4" />
                      历史记录
                    </h4>
                    <div className="flex gap-2 overflow-x-auto pb-2">
                      {historyResults.slice(0, 5).map((result, idx) => (
                        <button
                          key={idx}
                          onClick={() => setTasteResult(result)}
                          className="px-3 py-1.5 rounded-lg bg-neutral-100 dark:bg-neutral-800
                                     hover:bg-neutral-200 dark:hover:bg-neutral-700
                                     text-xs whitespace-nowrap transition-colors"
                        >
                          #{idx + 1} 分数:{(result.score * 100).toFixed(0)}
                        </button>
                      ))}
                    </div>
                  </div>
                )}
              </Card>
            </TabsContent>
          </Tabs>
        )}
      </div>
    </div>
  );
}

export default TastePredictTab;

/**
 * Agent 工作流 E2E 测试
 *
 * 测试范围：
 * - AgentWorkflowTab 渲染和交互
 * - Turn/Step 状态显示
 * - Token 计数器
 * - Compaction 触发
 * - 工作流模板切换
 * - Waterfall 事件可视化
 */

import { test, expect } from '@playwright/test';

const AGENT_WORKFLOW_URL = '/agent';

// ── 辅助函数 ────────────────────────────────────────────────

async function navigateToAgentWorkflow(page: any): Promise<void> {
  await page.goto(AGENT_WORKFLOW_URL);
  // 等待多智能体协作中心加载，进入 Chief 控制台（AgentWorkflowTab 迁移到 /agent）
  await page.waitForSelector('[data-testid="agent-nav-chief"]', { timeout: 10000 });
  await page.locator('[data-testid="agent-nav-chief"]').click();
  await page.waitForSelector('[data-testid="agent-input"]', { timeout: 10000 });
}

async function sendAgentMessage(page: any, message: string): Promise<void> {
  const textarea = page.locator('[data-testid="agent-input"]');
  await textarea.fill(message);
  await textarea.press('Enter');
}

async function waitForAgentResponse(page: any, timeout: number = 15000): Promise<void> {
  // 等待 running 状态消失
  await page.waitForSelector('.animate-spin', { state: 'hidden', timeout });
  // 等待新消息出现（使用 data-testid）
  await page.locator('[data-testid="assistant-message"]').last().waitFor({ state: 'visible', timeout });
}

// ── 测试套件 ────────────────────────────────────────────────

test.describe('Agent 工作流 E2E 测试', () => {
  test.beforeEach(async ({ page }) => {
    await navigateToAgentWorkflow(page);
  });

  test('应渲染 Agent Workflow Tab', async ({ page }) => {
    // 检查头部
    await expect(page.locator('text=AI 研发助手')).toBeVisible();
    await expect(page.locator('text=Agent v3.0')).toBeVisible();

    // 检查工作流模板按钮
    const templates = page.locator('.rounded-full.border');
    await expect(templates).toHaveCountGreaterThan(0);

    // 检查输入框
    const textarea = page.locator('textarea');
    await expect(textarea).toBeVisible();
    await expect(textarea).toHaveAttribute('placeholder', /描述你的研发需求/);
  });

  test('应显示快捷提示按钮', async ({ page }) => {
    const promptButtons = page.locator('button:text("帮我设计一款")');
    await expect(promptButtons).toBeVisible();
  });

  test('发送消息后应显示 Turn 状态', async ({ page }) => {
    // Mock API 响应
    await page.route('/api/v1/agent/**', route => {
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({
          success: true,
          data: {
            execution_id: 'test-exec-123',
            user_query: '测试消息',
            status: 'completed',
            total_latency_ms: 1500,
            steps: [
              { step_id: '1', tool: 'rag_search', status: 'success', latency_ms: 500 },
              { step_id: '2', tool: 'formula_generate', status: 'success', latency_ms: 800 },
              { step_id: '3', tool: 'compliance_check', status: 'success', latency_ms: 200 },
            ],
            final_response_preview: '这是一条测试回复',
          },
        }),
      });
    });

    await page.route('/api/v1/agent/workflow/*/execute', route => {
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({
          success: true,
          data: {
            execution_id: 'test-wf-123',
            workflow_type: 'formula_design',
            user_query: '测试消息',
            status: 'completed',
            total_latency_ms: 1500,
            stages: [
              { stage: 'RAG检索', success: true, latency_ms: 500 },
              { stage: '配方生成', success: true, latency_ms: 800 },
              { stage: '合规检查', success: true, latency_ms: 200 },
            ],
            final_response_preview: '配方设计方案已生成',
          },
        }),
      });
    });

    await sendAgentMessage(page, '帮我设计一款针对高血糖人群的饮品配方');
