  const messages: ChatMessage[] = []

  for (let i = 0; i < count; i++) {
    const topicIndex = i % topics.length

    // 用户提问
    messages.push(createMockMessage({
      content: `关于"${topics[topicIndex]}"，我想了解：${['原理是什么', '有哪些应用', '如何制备', '市场前景如何'][i % 4]}？`
