// Helper for rendering hooks in tests
function renderHook<T>(hookFn: () => T): { result: { current: T } } {
  const result: { current: T } = { current: null as any }

  function TestComponent() {
    result.current = hookFn()
    return null
  }

  render(<TestComponent />)
  return { result }
}

