    if (score >= 80) return 'text-success-500';
    if (score >= 60) return 'text-warning-500';
    if (score >= 40) return 'text-warning-500';
    return 'text-error-500';
  };

  const getHealthLabel = (score: number) => {
    if (score >= 80) return '优秀';
