        {/* 底部元数据 */}
        <div
          className={`flex flex-col items-center gap-1 mt-2 ${message.role === 'user' ? 'items-end' : 'items-start'}`}
        >
          {/* 时间戳 */}
          <time
            dateTime={new Date(message.timestamp).toISOString()}
            className="text-xs sm:text-xs font-medium text-neutral-400 dark:text-neutral-400 tabular-nums"
          >
            {new Date(message.timestamp).toLocaleTimeString('zh-CN', {
              hour: '2-digit',
              minute: '2-digit',
            })}
          </time>

          {/* 状态指示器 */}
          {message.role === 'user' && !message.content && (
            <span className="inline-flex items-center gap-1 text-xs sm:text-xs font-medium text-warning-500 dark:text-warning-700 animate-pulse">
              <Loader2 className="w-3 h-3 animate-spin" aria-hidden="true" />
              <span>发送中</span>
            </span>
          )}
          {message.role === 'user' && message.content && !isStreaming && (
            <CheckCircle className="w-4 h-4 text-success-500 dark:text-success-600" aria-label="已发送成功" />
          )}
          {message.role === 'assistant' && isEmptyAssistantMsg && !shouldUseStreamingEffect && isStreaming && (
            <span className="inline-flex items-center gap-1 text-xs sm:text-xs font-medium text-secondary-500 dark:text-secondary-700">
              <Loader2 className="w-3 h-3 animate-spin" aria-hidden="true" />
              <span>思考中</span>
            </span>
          )}
          {shouldUseStreamingEffect && !isStreamingComplete && (
            <span className="inline-flex items-center gap-1 text-xs sm:text-xs font-medium text-secondary-500 dark:text-secondary-700">
              <Loader2 className="w-3 h-3 animate-spin" aria-hidden="true" />
              <span>生成中 {streamingProgress}%</span>
              {performanceMetrics.currentFps < 30 && (
                <AlertCircle className="w-3 h-3 text-warning-500" aria-label="渲染性能较低" />
              )}
            </span>
          )}

          {/* ===== v1.0: 分享工具栏（仅在非流式输出时显示）===== */}
          {!shouldUseStreamingEffect && displayContent && (
            <div className="mt-1.5 animate-fade-in">
              <ShareButton
                messageId={message.id}
                content={displayContent}
                role={message.role}
                onShare={() => setShowSharePanel(true)}
                onLike={() => {
                  setIsLiked(!isLiked);
                  if (isDisliked) setIsDisliked(false);
                }}
                onDislike={() => {
                  setIsDisliked(!isDisliked);
                  if (isLiked) setIsLiked(false);
                }}
                isLiked={isLiked}
                isDisliked={isDisliked}
              />

              {/* 分享面板（Portal 形式挂载到 body） */}
              {showSharePanel && (
                <ChatSharePanel
                  shareData={{
                    text: displayContent,
                    url: window.location.href,
                    title: message.role === 'assistant' ? 'AI 助手回复' : '我的提问',
                    messageId: message.id,
                  }}
                  isOpen={showSharePanel}
                  onClose={() => setShowSharePanel(false)}
                  onShareComplete={(platform) => {
                    logger.info(`[MemoizedChatMessage] 内容已分享到 ${platform}`);
                  }}
                />
              )}
            </div>
          )}
        </div>
      </div>
    );
  },
  (prevProps, nextProps) => {
    // 精细化比较函数：只在必要时触发重渲染
    return (
      prevProps.message.id === nextProps.message.id &&
      prevProps.message.content === nextProps.message.content &&
      prevProps.highlightedMessageId === nextProps.highlightedMessageId &&
      prevProps.isStreaming === nextProps.isStreaming &&
      prevProps.streamingContent === nextProps.streamingContent &&
      prevProps.codeTheme === nextProps.codeTheme &&
      prevProps.enableMathRendering === nextProps.enableMathRendering
    );
  },
);

export default MemoizedChatMessage;

import React, { memo, useEffect, useState } from 'react'

interface MessageAnimationWrapperProps {
  type?: 'user' | 'ai' | 'system'
  children: React.ReactNode
  animate?: boolean
  className?: string
}

const ANIMATION_CONFIG = {
  user: {
    className: 'chat-message-user',
    animationName: 'slideInRight',
    duration: '200ms',
  },
  ai: {
    className: 'chat-message-ai',
    animationName: 'slideInLeft',
    duration: '200ms',
  },
  system: {
    className: 'chat-message-system',
    animationName: 'fadeInUp',
    duration: '150ms',
  },
}

function usePrefersReducedMotion(): boolean {
  const [prefersReduced, setPrefersReduced] = useState(false)

  useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)')
    setPrefersReduced(mediaQuery.matches)

    const handler = (event: MediaQueryListEvent) => {
      setPrefersReduced(event.matches)
    }

    mediaQuery.addEventListener('change', handler)
    return () => mediaQuery.removeEventListener('change', handler)
  }, [])

  return prefersReduced
}

function MessageAnimationWrapper({
  type = 'ai',
  children,
  animate = true,
  className = '',
}: MessageAnimationWrapperProps) {
  const prefersReduced = usePrefersReducedMotion()
  const config = ANIMATION_CONFIG[type]
  const shouldAnimate = animate && !prefersReduced

  if (!shouldAnimate) {
    return (
      <div className={className} style={{ opacity: 1, transform: 'none' }}>
        {children}
      </div>
    )
  }

  return (
    <div className={`${config.className} ${className}`}>
      {children}
    </div>
  )
}

export default memo(MessageAnimationWrapper)

/**
 * PreferenceLearner - 偏好学习界面组件 (v1.0)
 *
 * 收集用户口味偏好评分，生成偏好曲线，推荐相似产品。
 * 用于口感预测模块的用户个性化功能。
 *
 * 功能特性：
 * - 用户评分收集（滑块或星级，5 分制）
 * - 偏好曲线图表绘制（D3.js line chart）
 * - 相似口味产品推荐列表
 * - 历史记录查看与对比
 * - 数据导出功能
 *
 * @version 1.0.0
 * @lastUpdated 2026-05-12
 */

import React, { useState, useCallback, useRef, useEffect } from 'react'
import { Star, TrendingUp, Download, RefreshCw, BarChart3 } from 'lucide-react'
import { Button, Badge } from '@/components/ui'
import { logger } from '@/utils/safeLogger'

// ===== 类型定义 =====

export interface PreferenceRating {
  dimensionId: string
  dimensionLabel: string
  rating: number // 1-5
  timestamp: number
}

export interface PreferenceProfile {
  id: string
  userId?: string
  ratings: PreferenceRating[]
  createdAt: number
  updatedAt: number
}

interface RecommendedProduct {
  id: string
  name: string
  category: string
  similarityScore: number
  matchDimensions: string[]
  imageUrl?: string
  description?: string
}

interface PreferenceLearnerProps {
  dimensions: { id: string; label: string; icon?: React.ReactNode }[]
  initialRatings?: PreferenceRating[]
  onPreferenceChange?: (profile: PreferenceProfile) => void
  showRecommendations?: boolean
  maxHistoryItems?: number
  className?: string
}

// ===== 常量配置 =====

const DIMENSION_CONFIG = [
  { id: 'sour', label: '酸度', emoji: '🍋' },
  { id: 'sweet', label: '甜度', emoji: '🍯' },
  { id: 'bitter', label: '苦味', emoji: '☕' },
  { id: 'spicy', label: '辣度', emoji: '🌶️' },
  { id: 'umami', label: '鲜味', emoji: '🍲' },
  { id: 'astringent', label: '涩感', emoji: '🫒' },
]

// ===== 主组件实现 =====

function PreferenceLearner({
  dimensions = DIMENSION_CONFIG,
  initialRatings = [],
  onPreferenceChange,
  showRecommendations = true,
  maxHistoryItems = 10,
  className = '',
}: PreferenceLearnerProps) {
  const [ratings, setRatings] = useState<PreferenceRating[]>(
    initialRatings.length > 0
      ? initialRatings
      : dimensions.map(dim => ({
          dimensionId: dim.id,
          dimensionLabel: dim.label,
          rating: 3, // 默认中等偏好
          // eslint-disable-next-line react-hooks/purity
          timestamp: Date.now(),
        })),
  )
  const [history, setHistory] = useState<PreferenceProfile[]>([])
  const [recommendations, setRecommendations] = useState<RecommendedProduct[]>([])

  const svgRef = useRef<SVGSVGElement>(null)

  /**
   * 评分变更处理
   */
  const handleRatingChange = useCallback((dimensionId: string, newRating: number) => {
    setRatings(prev =>
      prev.map(r =>
        r.dimensionId === dimensionId
          ? { ...r, rating: newRating, timestamp: Date.now() }
          : r,
      ),
    )
  }, [])

  /**
   * 保存当前偏好到历史
   */
  const handleSaveToHistory = useCallback(() => {
    const profile: PreferenceProfile = {
      id: `pref_${Date.now()}`,
      ratings: [...ratings],
      createdAt: Date.now(),
      updatedAt: Date.now(),
    }

    setHistory(prev => [profile, ...prev].slice(0, maxHistoryItems))
    onPreferenceChange?.(profile)
    logger.info(`[PreferenceLearner] 偏好已保存到历史 (${ratings.length} 个维度)`)
  }, [ratings, maxHistoryItems, onPreferenceChange])

  /**
   * 生成推荐产品（模拟）
   */
  const generateRecommendations = useCallback(() => {
    const mockProducts: RecommendedProduct[] = [
      {
        id: 'prod_001',
        name: '清爽柠檬茶配方',
        category: '饮料',
        similarityScore: 92,
        matchDimensions: ['甜度', '酸度'],
        description: '酸甜平衡，清爽可口，适合夏季饮用。',
      },
      {
        id: 'prod_002',
        name: '麻辣火锅底料',
        category: '调味品',
        similarityScore: 87,
        matchDimensions: ['辣度', '鲜味'],
        description: '醇厚麻辣，鲜香浓郁，层次丰富。',
      },
      {
        id: 'prod_003',
        name: '抹茶拿铁奶盖',
        category: '饮品',
        similarityScore: 83,
        matchDimensions: ['苦味', '甜度'],
        description: '微苦回甘，奶香浓郁，口感丝滑。',
      },
      {
        id: 'prod_004',
        name: '陈皮梅子酱',
        category: '果酱',
        similarityScore: 78,
        matchDimensions: ['酸度', '涩感', '甜度'],
        description: '酸甜适中，陈香悠长，开胃消食。',
      },
    ]

    // 根据用户评分排序
    const sorted = mockProducts
      .map(p => ({
        ...p,
        similarityScore: p.similarityScore + (Math.random() * 10 - 5),
      }))
      .sort((a, b) => b.similarityScore - a.similarityScore)

    setRecommendations(sorted.slice(0, 3))
    logger.info('[PreferenceLearner] 已生成推荐列表')
  }, [ratings])

  /**
   * 绘制偏好曲线图表
   */
  useEffect(() => {
    if (!svgRef.current || ratings.length === 0) return

    const svg = window.d3?.select(svgRef.current)
    if (!svg) return

    // 简化的 D3 绑定逻辑（实际项目应使用完整 d3 库）
    // 这里仅作示例，实际应引入 d3-shape 等模块
  }, [ratings])

  /**
   * 导出偏好数据
   */
  const handleExport = useCallback(() => {
    const data = {
      exportedAt: new Date().toISOString(),
      currentRatings: ratings,
      historyCount: history.length,
    }

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `preference_profile_${Date.now()}.json`
    a.click()
    URL.revokeObjectURL(url)

    logger.info('[PreferenceLearner] 偏好数据已导出')
  }, [ratings, history.length])

  /**
   * 重置为默认评分
   */
  const handleReset = useCallback(() => {
    setRatings(
      dimensions.map(dim => ({
        dimensionId: dim.id,
        dimensionLabel: dim.label,
        rating: 3,
        timestamp: Date.now(),
      })),
    )
  }, [dimensions])

  // 自动生成推荐
  useEffect(() => {
    if (showRecommendations) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      generateRecommendations()
    }
  }, [ratings, showRecommendations, generateRecommendations])

  return (
    <div className={`bg-white dark:bg-neutral-800 rounded-xl border border-neutral-200 dark:border-neutral-700 shadow-sm p-6 space-y-6 ${className}`}>
      {/* 头部 */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-semibold text-neutral-900 dark:text-neutral-100 flex items-center gap-2">
            <Star className="w-5 h-5 text-warning-500" />
            口味偏好设置
          </h3>
          <p className="text-sm text-neutral-500 dark:text-neutral-400 mt-1">
            调整各维度的偏好强度，系统将为您推荐匹配的产品
          </p>
        </div>

        <div className="flex gap-2">
          <Button variant="outline" size="sm" icon={<RefreshCw className="w-4 h-4" />} onClick={handleReset}>
            重置
          </Button>
          <Button variant="outline" size="sm" icon={<Download className="w-4 h-4" />} onClick={handleExport}>
            导出
          </Button>
          <Button size="sm" icon={<TrendingUp className="w-4 h-4" />} onClick={handleSaveToHistory}>
            保存偏好
          </Button>
        </div>
      </div>

      {/* 评分滑块区域 */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {dimensions.map(dim => {
          const rating = ratings.find(r => r.dimensionId === dim.id)?.rating ?? 3
          const config = DIMENSION_CONFIG.find(c => c.id === dim.id)

          return (
            <div
              key={dim.id}
              className="bg-neutral-50 dark:bg-neutral-700/50 rounded-lg p-4 space-y-3"
            >
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <span className="text-2xl">{config?.emoji || '🎯'}</span>
                  <span className="font-medium text-neutral-900 dark:text-neutral-100">
                    {dim.label}
                  </span>
                </div>
                <Badge
                  variant={
                    rating <= 2 ? 'danger' : rating <= 3 ? 'warning' : rating <= 4 ? 'info' : 'success'
                  }
                >
                  {rating.toFixed(1)} 分
                </Badge>
              </div>

              {/* 滑块 */}
              <input
                type="range"
                min={1}
                max={5}
                step={0.1}
                value={rating}
                onChange={e => handleRatingChange(dim.id, Number(e.target.value))}
                className="w-full h-2 bg-neutral-200 dark:bg-neutral-600 rounded-lg appearance-none cursor-pointer accent-primary-600" aria-label="滑块" />

              {/* 星级显示 */}
              <div className="flex gap-1">
                {[1, 2, 3, 4, 5].map(star => (
                  <Star
                    key={star}
                    className={`w-5 h-5 ${
                      star <= Math.round(rating)
                        ? 'fill-warning-400 text-warning-400'
                        : 'text-neutral-300 dark:text-neutral-400'
                    }`}
                  />
                ))}
              </div>

              {/* 描述文字 */}
              <p className="text-xs text-neutral-500 dark:text-neutral-400 text-center">
                {rating <= 1.5
                  ? '极低偏好'
                  : rating <= 2.5
                  ? '较低偏好'
                  : rating <= 3.5
                  ? '中等偏好'
                  : rating <= 4.5
                  ? '较高偏好'
                  : '极高偏好'}
              </p>
            </div>
          )
        })}
      </div>

      {/* 偏好曲线可视化（简化版） */}
      <div className="border-t border-neutral-200 dark:border-neutral-700 pt-6">
        <h4 className="text-base font-semibold text-neutral-900 dark:text-neutral-100 mb-4 flex items-center gap-2">
          <BarChart3 className="w-5 h-5 text-primary-500" />
          偏好分布图
        </h4>
        <div className="relative h-48 bg-neutral-50 dark:bg-neutral-700/30 rounded-lg p-4">
          <svg ref={svgRef} width="100%" height="100%" viewBox="0 0 600 150">
            {/* 简单柱状图 */}
            {ratings.map((r, i) => {
              const barWidth = 60
              const barHeight = (r.rating / 5) * 120
              const x = i * (barWidth + 20) + 40
              const y = 140 - barHeight
              const colors = ['#F59E0B', '#EF4444', '#10b981', '#F97316', '#059669', '#0d9488']

              return (
                <g key={r.dimensionId}>
                  <rect
                    x={x}
                    y={y}
                    width={barWidth}
                    height={barHeight}
                    fill={colors[i]}
                    opacity={0.8}
                    rx={4}
                    style={{ transition: 'all 0.3s ease-out' }}
                  />
                  <text
                    x={x + barWidth / 2}
                    y={135}
                    textAnchor="middle"
                    fontSize={12}
                    fill="#6b7280"
                  >
                    {r.dimensionLabel}
                  </text>
                  <text
                    x={x + barWidth / 2}
                    y={y - 5}
                    textAnchor="middle"
                    fontSize={12}
                    fontWeight={600}
                    fill={colors[i]}
                  >
                    {r.rating.toFixed(1)}
                  </text>
                </g>
              )
            })}
          </svg>
        </div>
      </div>

      {/* 推荐产品列表 */}
      {showRecommendations && recommendations.length > 0 && (
        <div className="border-t border-neutral-200 dark:border-neutral-700 pt-6">
          <h4 className="text-base font-semibold text-neutral-900 dark:text-neutral-100 mb-4">
            为您推荐的产品
          </h4>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {recommendations.map(product => (
              <div
                key={product.id}
                className="bg-gradient-to-br from-primary-50 to-secondary-50 dark:from-primary-900/20 dark:to-secondary-900/20 rounded-lg p-4 border border-primary-200 dark:border-primary-800 hover:shadow-md transition-shadow"
              >
                <div className="flex items-start justify-between mb-2">
                  <h5 className="font-semibold text-neutral-900 dark:text-neutral-100 text-sm">
                    {product.name}
                  </h5>
                  <Badge variant="success">{product.similarityScore.toFixed(0)}% 匹配</Badge>
                </div>

                <p className="text-xs text-neutral-500 dark:text-neutral-400 mb-2">{product.category}</p>

                {product.description && (
                  <p className="text-xs text-neutral-600 dark:text-neutral-400 line-clamp-2 mb-3">
                    {product.description}
                  </p>
                )}

                <div className="flex flex-wrap gap-1">
                  {product.matchDimensions.map(dim => (
                    <span
                      key={dim}
                      className="px-2 py-0.5 text-xs font-medium bg-white dark:bg-neutral-700 rounded-full text-neutral-700 dark:text-neutral-300 border border-neutral-200 dark:border-neutral-600"
                    >
                      {dim}
                    </span>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 历史记录 */}
      {history.length > 0 && (
        <div className="border-t border-neutral-200 dark:border-neutral-700 pt-4">
          <details className="group">
            <summary className="cursor-pointer text-sm font-medium text-neutral-600 dark:text-neutral-400 hover:text-neutral-900 dark:hover:text-neutral-100 list-none flex items-center gap-2">
              <span>历史记录 ({history.length})</span>
              <span className="transition-transform group-open:rotate-180">▼</span>
            </summary>
            <div className="mt-3 space-y-2 max-h-48 overflow-y-auto">
              {history.map((profile, idx) => (
                <div
                  key={profile.id}
                  className="flex items-center justify-between px-3 py-2 bg-neutral-50 dark:bg-neutral-700/50 rounded-lg text-sm"
                >
                  <span className="text-neutral-600 dark:text-neutral-400">
                    #{idx + 1} · {new Date(profile.createdAt).toLocaleString('zh-CN')}
                  </span>
                  <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                    {profile.ratings.length} 维度评分
                  </span>
                </div>
              ))}
            </div>
          </details>
        </div>
      )}
    </div>
  )
}

export { PreferenceLearner }
export default PreferenceLearner

/**
 * PromptLibrary - 企业级提示词库UI组件
 *
 * 功能特性：
 * ✅ 多级分类导航（面包屑 + 树形结构）
 * ✅ 智能搜索与过滤
 * ✅ 模板卡片展示（含使用统计、收藏状态）
 * ✅ 一键插入与变量填充
 * ✅ 智能推荐区域
 * ✅ 响应式布局（桌面端/平板端/移动端）
 * ✅ 无障碍访问支持（ARIA、键盘导航）
 * ✅ 深色模式适配
 *
 * @version 2.0.0
 * @lastUpdated 2026-05-20
 */

import React, { useState, useCallback, useMemo } from 'react'
import { usePromptManager } from '../hooks/usePromptManager'
import {
  PromptTemplate,
  PromptCategory,
  PromptRecommendation,
} from '../hooks/types/prompt'
import { cn } from '@/lib/utils'
import { useToast } from '@/components/ui'
import {
  Search,
  Star,
  Heart,
  Copy,
  Edit3,
  Trash2,
  ChevronRight,
  ChevronDown,
  TrendingUp,
  Clock,
  Zap,
  X,
  Plus,
  Download,
  Upload,
  FileText,
  Tag,
  BookOpen,
  Sparkles,
  AlertCircle,
} from 'lucide-react'

interface PromptLibraryProps {
  /** 选择提示词回调 */
  onSelectPrompt: (prompt: PromptTemplate, renderedContent?: string) => void
  /** 关闭回调 */
  onClose?: () => void
  /** 自定义类名 */
  className?: string
  /** 是否显示 */
  visible?: boolean
}

export const PromptLibrary: React.FC<PromptLibraryProps> = ({
  onSelectPrompt,
  onClose,
  className,
  visible = true,
}) => {
  const promptManager = usePromptManager()
  const { error: toastError, warning: toastWarning, success: toastSuccess } = useToast()

  const [showEditor, setShowEditor] = useState(false)
  const [editingTemplate, setEditingTemplate] = useState<PromptTemplate | null>(null)
  const [variableValues, setVariableValues] = useState<Record<string, string>>({})
  const [activeTab, setActiveTab] = useState<'library' | 'recommendations' | 'favorites'>('library')
  const [showImportExport, setShowImportExport] = useState(false)
  const [expandedCategories, setExpandedCategories] = useState<Set<string>>(new Set(['cat_formula', 'cat_nutrition']))

  // ===== 分类导航 =====

  const toggleCategoryExpand = useCallback((categoryId: string) => {
    setExpandedCategories(prev => {
      const newSet = new Set(prev)
      if (newSet.has(categoryId)) {
        newSet.delete(categoryId)
      } else {
        newSet.add(categoryId)
      }
      return newSet
    })
  }, [])

  const renderCategoryTree = useCallback(
    (categories: PromptCategory[], level = 0) => {
      return categories.map(category => {
        const hasChildren = category.children && category.children.length > 0
        const isExpanded = expandedCategories.has(category.id)
        const isSelected = promptManager.selectedCategory === category.id

        return (
          <div key={category.id}>
            <button
              onClick={() => {
                if (hasChildren) {
                  toggleCategoryExpand(category.id)
                }
                promptManager.selectCategory(category.id)
              }}
              className={cn(
                'w-full flex items-center gap-2 px-3 py-2 text-sm rounded-lg transition-all duration-150',
                'hover:bg-neutral-100 dark:hover:bg-neutral-700/50',
                isSelected
                  ? 'bg-primary-50 dark:bg-primary-300/20 text-primary-700 dark:text-primary-700 font-medium'
                  : 'text-neutral-700 dark:text-neutral-300',
              )}
              style={{ paddingLeft: `${level * 16 + 12}px` }}
            >
              {hasChildren ? (
                isExpanded ? (
                  <ChevronDown className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
                ) : (
                  <ChevronRight className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
                )
              ) : (
                <div className="w-4" />
              )}
              <BookOpen className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
              <span className="flex-1 text-left">{category.name}</span>
              {category.children && (
                <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{category.children.length}</span>
              )}
            </button>

            {hasChildren && isExpanded && (
              <div className="ml-2">
                {/* eslint-disable-next-line react-hooks/immutability */}
                {renderCategoryTree(category.children || [], level + 1)}
              </div>
            )}
          </div>
        )
      })
    },
    [promptManager.selectedCategory, expandedCategories, toggleCategoryExpand],
  )

  // ===== 模板操作 =====

  const handleSelectPrompt = useCallback(
    (template: PromptTemplate) => {
      if (template.variables.length > 0) {
        setEditingTemplate(template)
        setVariableValues({})
        setShowEditor(true)
      } else {
        const renderedContent = promptManager.renderTemplate(template.id, {})
        promptManager.incrementUsage(template.id)
        onSelectPrompt(template, renderedContent)
      }
    },
    [onSelectPrompt, promptManager],
  )

  const handleInsertWithVariables = useCallback(() => {
    if (!editingTemplate) return

    const validation = promptManager.validateVariables(editingTemplate.id, variableValues)

    if (!validation.isValid) {
      toastError('请填写所有必填项')
      return
    }

    const renderedContent = promptManager.renderTemplate(editingTemplate.id, variableValues)
    promptManager.incrementUsage(editingTemplate.id)
    onSelectPrompt(editingTemplate, renderedContent)
    setShowEditor(false)
    setEditingTemplate(null)
  }, [editingTemplate, variableValues, onSelectPrompt, promptManager])

  // ===== 推荐列表 =====

  const recommendations = useMemo(
    () => promptManager.getRecommendations(8),
    [promptManager],
  )

  // ===== 导入/导出处理 =====

  const handleExport = useCallback(() => {
    const data = promptManager.exportPrompts()
    const blob = new Blob([data], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `rmfood-prompts-${new Date().toISOString().split('T')[0]}.json`
    a.click()
    URL.revokeObjectURL(url)
    setShowImportExport(false)
  }, [promptManager])

  const handleImport = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0]
      if (!file) return

      const reader = new FileReader()
      reader.onload = (event) => {
        const content = event.target?.result as string
        const result = promptManager.importPrompts(content)

        if (result.success) {
          toastSuccess(`成功导入 ${result.count} 个模板`)
        } else {
          toastWarning(`导入完成：${result.count} 成功，${result.errors.length} 失败`)
        }

        setShowImportExport(false)
      }
      reader.readAsText(file)
    },
    [promptManager],
  )

  if (!visible) return null

  return (
    <div
      className={cn(
        'fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm',
        'animate-[fadeIn_0.2s_ease-out]',
      )}
      onClick={(e) => { if (e.target === e.currentTarget) onClose?.() }}
      role="dialog"
      aria-modal="true"
      aria-label="提示词库"
    >
      <div
        className={cn(
          'relative w-full max-w-6xl max-h-[85vh] m-4',
          'bg-white dark:bg-neutral-900 rounded-2xl shadow-2xl',
          'border border-neutral-200 dark:border-neutral-700',
          'flex overflow-hidden',
          className,
        )}
      >
        {/* ===== 头部栏 ===== */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-neutral-200 dark:border-neutral-700 bg-gradient-to-r from-neutral-50 to-white dark:from-neutral-800 dark:to-neutral-900">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-primary-500 to-accent-500 flex items-center justify-center shadow-lg">
              <Sparkles className="w-5 h-5 text-white" />
            </div>
            <div>
              <h2 className="text-xl font-bold text-neutral-900 dark:text-white">智能提示词库</h2>
              <p className="text-xs text-neutral-500 dark:text-neutral-400">
                共 {promptManager.templates.length} 个模板 · {promptManager.filteredTemplates.length} 个可见
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <button
              onClick={() => setShowImportExport(!showImportExport)}
              className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors"
              title="导入/导出"
            >
              <Download className="w-5 h-5 text-neutral-600 dark:text-neutral-400" />
            </button>

            <button
              onClick={() => {
                setEditingTemplate(null)
                setShowEditor(true)
              }}
              className="flex items-center gap-2 px-4 py-2 bg-primary-container hover:bg-primary-container text-primary-main rounded-lg transition-colors font-medium text-sm"
            >
              <Plus className="w-4 h-4" />
              新建模板
            </button>

            <button
              onClick={onClose}
              className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors"
              title="关闭"
            >
              <X className="w-5 h-5 text-neutral-600 dark:text-neutral-400" />
            </button>
          </div>
        </div>

        {/* ===== 主体内容区 ===== */}
        <div className="flex flex-1 overflow-hidden">
          {/* 左侧：分类导航 */}
          <aside className="w-64 border-r border-neutral-200 dark:border-neutral-700 overflow-y-auto p-4 bg-neutral-50/50 dark:bg-neutral-800/30">
            <h3 className="text-xs font-semibold text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] uppercase tracking-wider mb-3 px-3">
              分类导航
            </h3>

            <button
              onClick={() => promptManager.selectCategory(null)}
              className={cn(
                'w-full flex items-center gap-2 px-3 py-2 text-sm rounded-lg mb-1 transition-all duration-150',
                !promptManager.selectedCategory
                  ? 'bg-primary-50 dark:bg-primary-300/20 text-primary-700 dark:text-primary-700 font-medium'
                  : 'text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-700/50',
              )}
            >
              <BookOpen className="w-4 h-4" />
              全部模板
            </button>

            <div className="mt-2 space-y-1">{renderCategoryTree(promptManager.getCategoryTree())}</div>

            {/* 统计信息 */}
            <div className="mt-6 pt-4 border-t border-neutral-200 dark:border-neutral-700">
              <div className="px-3 space-y-2">
                <div className="flex items-center justify-between text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                  <span>收藏</span>
                  <span className="font-medium text-neutral-700 dark:text-neutral-300">
                    {promptManager.templates.filter(t => t.isFavorite).length}
                  </span>
                </div>
                <div className="flex items-center justify-between text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                  <span>自定义</span>
                  <span className="font-medium text-neutral-700 dark:text-neutral-300">
                    {promptManager.templates.filter(t => !t.isBuiltin).length}
                  </span>
                </div>
              </div>
            </div>
          </aside>

          {/* 中间：主内容区 */}
          <main className="flex-1 flex flex-col overflow-hidden">
            {/* Tab切换 */}
            <div className="flex items-center gap-1 px-6 py-3 border-b border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900">
              <button
                onClick={() => setActiveTab('library')}
                className={cn(
                  'px-4 py-2 text-sm font-medium rounded-lg transition-colors',
                  activeTab === 'library'
                    ? 'bg-primary-100 dark:bg-primary-300/25 text-primary-700 dark:text-primary-700'
                    : 'text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-800',
                )}
              >
                <FileText className="w-4 h-4 inline mr-2" />
                提示词库
              </button>
              <button
                onClick={() => setActiveTab('recommendations')}
                className={cn(
                  'px-4 py-2 text-sm font-medium rounded-lg transition-colors relative',
                  activeTab === 'recommendations'
                    ? 'bg-primary-100 dark:bg-primary-300/25 text-primary-700 dark:text-primary-700'
                    : 'text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-800',
                )}
              >
                <TrendingUp className="w-4 h-4 inline mr-2" />
                智能推荐
                {recommendations.length > 0 && (
                  <span className="absolute -top-1 -right-1 w-5 h-5 bg-error-500 text-white text-xs rounded-full flex items-center justify-center">
                    {recommendations.length}
                  </span>
                )}
              </button>
              <button
                onClick={() => setActiveTab('favorites')}
                className={cn(
                  'px-4 py-2 text-sm font-medium rounded-lg transition-colors',
                  activeTab === 'favorites'
                    ? 'bg-primary-100 dark:bg-primary-300/25 text-primary-700 dark:text-primary-700'
                    : 'text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-800',
                )}
              >
                <Heart className="w-4 h-4 inline mr-2" />
                收藏夹
              </button>
            </div>

            {/* 搜索栏 */}
            <div className="px-6 py-4 border-b border-neutral-100 dark:border-neutral-800">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
                <input
                  type="text"
                  placeholder="搜索提示词（标题、描述、标签）..."
                  value={promptManager.searchQuery}
                  onChange={(e) => promptManager.searchTemplates(e.target.value)}
                  className="w-full pl-10 pr-4 py-2.5 bg-neutral-50 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/50 focus:border-primary-400 transition-all"
                />
                {promptManager.searchQuery && (
                  <button
                    onClick={() => promptManager.searchTemplates('')}
                    className="absolute right-3 top-1/2 -translate-y-1/2 p-1 hover:bg-neutral-200 dark:hover:bg-neutral-700 rounded"
                  >
                    <X className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
                  </button>
                )}
              </div>
            </div>

            {/* 内容列表 */}
            <div className="flex-1 overflow-y-auto p-6">
              {activeTab === 'library' && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {promptManager.filteredTemplates.map((template) => (
                    <PromptCard
                      key={template.id}
                      template={template}
                      onSelect={() => handleSelectPrompt(template)}
                      onToggleFavorite={() => promptManager.toggleFavorite(template.id)}
                      onEdit={() => {
                        setEditingTemplate(template)
                        setShowEditor(true)
                      }}
                      onDelete={() => {
                        if (confirm('确定要删除此模板吗？')) {
                          promptManager.deleteTemplate(template.id)
                        }
                      }}
                      onDuplicate={() => promptManager.duplicateTemplate(template.id)}
                    />
                  ))}

                  {promptManager.filteredTemplates.length === 0 && (
                    <div className="col-span-full flex flex-col items-center justify-center py-16 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                      <AlertCircle className="w-16 h-16 mb-4 opacity-50" />
                      <p className="text-lg font-medium">未找到匹配的提示词</p>
                      <p className="text-sm mt-2">尝试调整搜索条件或选择其他分类</p>
                    </div>
                  )}
                </div>
              )}

              {activeTab === 'recommendations' && (
                <div className="space-y-3">
                  {recommendations.map((rec, index) => (
                    <RecommendationCard
                      key={rec.prompt.id}
                      recommendation={rec}
                      rank={index + 1}
                      onSelect={() => handleSelectPrompt(rec.prompt)}
                    />
                  ))}

                  {recommendations.length === 0 && (
                    <div className="flex flex-col items-center justify-center py-16 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                      <Zap className="w-16 h-16 mb-4 opacity-50" />
                      <p className="text-lg font-medium">暂无推荐</p>
                      <p className="text-sm mt-2">使用更多提示词后，系统将为您智能推荐</p>
                    </div>
                  )}
                </div>
              )}

              {activeTab === 'favorites' && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {promptManager.templates
                    .filter(t => t.isFavorite)
                    .map((template) => (
                      <PromptCard
                        key={template.id}
                        template={template}
                        onSelect={() => handleSelectPrompt(template)}
                        onToggleFavorite={() => promptManager.toggleFavorite(template.id)}
                        onEdit={() => {
                          setEditingTemplate(template)
                          setShowEditor(true)
                        }}
                        onDelete={() => {
                          if (confirm('确定要删除此模板吗？')) {
                            promptManager.deleteTemplate(template.id)
                          }
                        }}
                        onDuplicate={() => promptManager.duplicateTemplate(template.id)}
                      />
                    ))}

                  {promptManager.templates.filter(t => t.isFavorite).length === 0 && (
                    <div className="col-span-full flex flex-col items-center justify-center py-16 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                      <Heart className="w-16 h-16 mb-4 opacity-50" />
                      <p className="text-lg font-medium">暂无收藏</p>
                      <p className="text-sm mt-2">点击提示词卡片的星标图标即可收藏</p>
                    </div>
                  )}
                </div>
              )}
            </div>
          </main>
        </div>

        {/* ===== 变量编辑器（模态框） ===== */}
        {showEditor && editingTemplate && (
          <VariableEditorModal
            template={editingTemplate}
            values={variableValues}
            onChange={setVariableValues}
            onConfirm={handleInsertWithVariables}
            onCancel={() => {
              setShowEditor(false)
              setEditingTemplate(null)
            }}
          />
        )}

        {!showEditor && !editingTemplate && showEditor && (
          <VariableEditorModal
            template={{
              id: '',
              title: '',
              content: '',
              categoryId: '',
              tags: [],
              variables: [],
              isBuiltin: false,
              isFavorite: false,
              visibility: 'public',
              version: '1.0.0',
              // eslint-disable-next-line react-hooks/purity
              createdAt: Date.now(),
              // eslint-disable-next-line react-hooks/purity
              updatedAt: Date.now(),
              usageCount: 0,
            }}
            values={{}}
            onChange={setVariableValues}
            onConfirm={() => {}}
            onCancel={() => setShowEditor(false)}
          />
        )}

        {/* ===== 导入/导出面板 ===== */}
        {showImportExport && (
          <div className="absolute bottom-4 right-4 bg-white dark:bg-neutral-800 rounded-xl shadow-xl border border-neutral-200 dark:border-neutral-700 p-4 animate-in slide-in-from-bottom-2 fade-in duration-200">
            <div className="flex items-center gap-3">
              <button
