      )}

      {/* 更多操作 */}
      {onMore && (
        <button
          onClick={onMore}
          className="p-1 rounded hover:bg-neutral-100 dark:hover:bg-neutral-800 text-neutral-400 hover:text-neutral-600 transition-colors"
          title="更多"
          aria-label="更多操作"
        >
