	messages: ChatMessage[]
	isStreaming: boolean
	isLoading?: boolean
	chatError: Error | null
	onRetry?: () => void
	onRetryMessage?: (messageId: string) => void
	onCopyMessage?: (content: string) => void
	onRegenerate?: (messageId: string) => void
	onDeleteMessage?: (messageId: string) => void
