	onRetractMessage?: (id: string) => void
	onForkMessage?: (messageId: string) => void
	onDetailsMessage?: (call: { id: string; name: string; args: Record<string, unknown>; status: 'running' | 'completed' | 'error'; durationMs?: number }) => void
