export function MessageList({
	messages: rawMessages, isStreaming, isLoading, chatError,
	onRetry, onRetryMessage, onCopyMessage, onRegenerate, onDeleteMessage,
	showReportButton,
	highlightedMessageId, selectedMessageIds, onReferenceMessage,
	onRetractMessage, onForkMessage, onDetailsMessage,
	onStructureSave, onStructureShare,
	thinkingSteps,
}: MessageListProps) {
	// 防御：上游在初始加载态可能传入 undefined（类型声明虽为必填）。
	// 若不归一化，下方 :78 的 messages.length 会抛 TypeError 导致整个列表崩溃。
	const messages = rawMessages ?? []

	const scrollRef = useRef<HTMLDivElement>(null)
	const bottomRef = useRef<HTMLDivElement>(null)
	const [copiedId, setCopiedId] = useState<string | null>(null)
	const [reactions, setReactions] = useState<Record<string, 'like' | 'dislike' | null>>({})
	const [showScrollBtn, setShowScrollBtn] = useState(false)
	const [editingId, setEditingId] = useState<string | null>(null)
	const [editContent, setEditContent] = useState('')
	const [retryQueue, setRetryQueue] = useState<Array<{ id: string; content: string; timestamp: number }>>([])

	const networkStatus = useNetworkStatus()
	const { isOnline, isSlowConnection } = networkStatus

	const shouldVirtualize = messages.length > VIRTUALIZE_THRESHOLD
	const listContainerRef = useRef<HTMLDivElement>(null)
	const [scrollMargin, setScrollMargin] = useState(0)

	// 动态高度估计：根据消息内容和角色计算，避免固定 140px 导致的滚动错位
	const getEstimatedSize = useCallback((index: number): number => {
		const msg = messages[index]
		if (!msg) return 140

		if (msg.role === 'assistant') {
			// AI回复：基础高度 + 内容长度（每80字符约25px）+ thinking步骤额外空间
			const baseHeight = 80
			const contentHeight = Math.min(Math.floor(msg.content.length / 80) * 25, 400)
			const stepHeight = (((msg as unknown as Record<string, unknown>).thinking_steps as unknown as number[])?.length ?? 0) * 30
			return baseHeight + contentHeight + stepHeight
		}

		if (msg.role === 'user') {
			// 用户消息：基础高度 + 内容长度
			return Math.min(60 + Math.floor(msg.content.length / 40) * 15, 200)
		}

		// 错误消息等
		return 100
	}, [messages])

	const rowVirtualizer = useVirtualizer({
		count: messages.length,
		getScrollElement: () => scrollRef.current,
		estimateSize: getEstimatedSize,
		overscan: 10,
		scrollMargin,
		getItemKey: (index) => messages[index]?.id ?? index,
	})

	useLayoutEffect(() => {
		if (shouldVirtualize && listContainerRef.current) {
			setScrollMargin(listContainerRef.current.offsetTop)
		}
	}, [shouldVirtualize, isOnline, isSlowConnection, showReportButton, selectedMessageIds])

	// Auto scroll
	useEffect(() => {
		if (shouldVirtualize) {
			rowVirtualizer.scrollToIndex(Math.max(0, messages.length - 1), { align: 'end' })
		} else {
			bottomRef.current?.scrollIntoView({ behavior: 'smooth' })
		}
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [messages, isStreaming, shouldVirtualize])

	const handleScroll = useCallback(() => {
		const el = scrollRef.current
		if (!el) return
		const isNearBottom = el.scrollHeight - el.scrollTop - el.clientHeight < 200
		setShowScrollBtn(!isNearBottom)
	}, [])

	const handleCopy = useCallback((id: string, content: string) => {
		navigator.clipboard.writeText(content).then(() => {
			setCopiedId(id)
			setTimeout(() => setCopiedId(null), 2000)
		}).catch(() => {})
		onCopyMessage?.(content)
	}, [onCopyMessage])

	const handleReaction = useCallback((msgId: string, type: 'like' | 'dislike') => {
		setReactions(prev => {
			const current = prev[msgId]
			if (current === type) return { ...prev, [msgId]: null }
			return { ...prev, [msgId]: type }
		})
	}, [])

	const scrollToBottom = useCallback(() => {
		bottomRef.current?.scrollIntoView({ behavior: 'smooth' })
	}, [])

	const startEdit = useCallback((msg: ChatMessage) => {
		setEditingId(msg.id)
		setEditContent(msg.content)
	}, [])

	// 网络恢复自动重试
	useEffect(() => {
		if (!isOnline || retryQueue.length === 0 || !onRetryMessage) return
		const timer = setTimeout(() => {
			retryQueue.forEach(item => onRetryMessage(item.id))
			setRetryQueue([])
		}, 1000)
		return () => clearTimeout(timer)
	}, [isOnline, retryQueue, onRetryMessage])

	const isHL = useCallback((id: string) => highlightedMessageId === id, [highlightedMessageId])
	const isSel = useCallback((id: string) => selectedMessageIds?.includes(id) ?? false, [selectedMessageIds])

	// 渲染消息列表（必须在所有条件 return 之前定义，遵守 React hooks 规则）
	const renderInner = useCallback((msg: ChatMessage, i: number) => (
		<MessageBubble
			key={msg.id}
			msg={msg}
			index={i}
			allMessages={messages}
			isStreaming={isStreaming}
			reaction={reactions[msg.id]}
			searchQuery={undefined}
			editingId={editingId}
			editContent={editContent}
			setEditContent={setEditContent}
			onCopy={handleCopy}
			onReaction={handleReaction}
			copiedId={copiedId}
			onEdit={(id, content) => { const msg = messages.find(m => m.id === id); if (msg) startEdit(msg); setEditContent(content); }}
			onRetract={onRetractMessage ?? (() => {})}
			onDelete={onDeleteMessage ?? (() => {})}
			onReference={onReferenceMessage ?? (() => {})}
			onRegenerate={onRegenerate ?? (() => {})}
			onForkMessage={onForkMessage}
			onDetails={onDetailsMessage}
			onStructureSave={onStructureSave}
			onStructureShare={onStructureShare}
			thinkingSteps={(i === messages.length - 1 && msg.role === 'assistant' && thinkingSteps) ? thinkingSteps : undefined}
			isHighlighted={isHL(msg.id)}
			isSelected={isSel(msg.id)}
		/>
	), [messages, isStreaming, reactions, editingId, editContent, handleCopy, handleReaction, thinkingSteps, isHL, isSel, onRetractMessage, onDeleteMessage, onReferenceMessage, onRegenerate, onForkMessage, onDetailsMessage, onStructureSave, onStructureShare, startEdit])

	// 骨架屏
	if (messages.length === 0 && isLoading && !chatError) {
		return (
			<div className="flex-1 overflow-y-auto px-4 py-8 space-y-6 chat-custom-scrollbar">
				<div className="chat-skeleton space-y-5 max-w-lg mx-auto">
					<div className="flex items-end gap-3 justify-end">
						<div className="flex flex-col items-end gap-2 flex-1 max-w-[75%]">
							<div className="skeleton-bubble skeleton-user h-10 w-[70%] rounded-2xl rounded-br-sm" />
						</div>
						<div className="skeleton-avatar w-9 h-9 rounded-full bg-neutral-300 animate-pulse" />
					</div>
					<div className="flex items-start gap-3">
						<div className="skeleton-avatar w-9 h-9 rounded-full bg-neutral-300 animate-pulse" />
						<div className="flex flex-col gap-2 flex-1 max-w-[80%]">
							<div className="skeleton-bubble skeleton-ai h-16 w-full rounded-2xl rounded-tl-sm" />
							<div className="skeleton-bubble skeleton-ai h-8 w-[60%] rounded-2xl rounded-tl-sm" />
						</div>
					</div>
					<div className="flex items-end gap-3 justify-end">
						<div className="flex flex-col items-end gap-2 flex-1 max-w-[65%]">
							<div className="skeleton-bubble skeleton-user h-7 w-[90%] rounded-2xl rounded-br-sm" />
						</div>
						<div className="skeleton-avatar w-9 h-9 rounded-full bg-neutral-300 animate-pulse" />
					</div>
				</div>
			</div>
		)
	}

	// 空状态（可滚动：内容超高时内部滚动，避免溢出压到输入框）
	if (messages.length === 0 && !chatError) {
		return (
			<div className="flex-1 overflow-y-auto px-4 py-8 chat-custom-scrollbar">
				<div className="min-h-full flex flex-col items-center justify-center space-y-6">
					<div className="text-center space-y-3">
						<div className="w-20 h-20 mx-auto rounded-3xl bg-gradient-to-br from-primary-400 via-primary-500 to-primary-600 shadow-lg shadow-primary-300/40 dark:shadow-primary-900/30 flex items-center justify-center animate-pulse-slow">
							<Sparkles className="w-10 h-10 text-white drop-shadow-sm" />
						</div>
						<h3 className="text-lg font-semibold text-neutral-800 dark:text-neutral-200">开始新对话</h3>
						<p className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] max-w-md">输入您的问题或需求，AI 将为您提供专业的配方建议和分析。</p>
					</div>
					<div className="grid grid-cols-1 sm:grid-cols-2 gap-3 w-full max-w-lg">
						{QUICK_ACTIONS.map((action, i) => (
							<button key={i} className="group relative flex items-start gap-3 p-4 rounded-xl border border-neutral-200 hover:border-primary-300 dark:hover:border-primary-600 hover:bg-gradient-to-br hover:from-primary-50/60 hover:to-transparent dark:hover:from-primary-900/15 dark:hover:to-transparent transition-all duration-200 ease-out text-left hover:scale-[1.02] hover:shadow-md hover:shadow-primary-100/50 dark:hover:shadow-primary-900/20 active:scale-[0.98]">
								<div className={`w-8 h-8 rounded-lg flex items-center justify-center ${action.color} bg-white dark:bg-neutral-800 shadow-sm`}>
									<action.Icon className="w-4 h-4" />
								</div>
								<div>
									<div className="text-sm font-medium text-neutral-700 dark:text-neutral-300">{action.title}</div>
									<div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-0.5">{action.desc}</div>
								</div>
							</button>
						))}
					</div>
				</div>
			</div>
		)
	}

	// 错误状态
	if (chatError) {
		return (
			<div className="flex-1 flex items-center justify-center p-4">
				<div className="text-center space-y-3">
					<p className="text-error-600 dark:text-error-600 text-sm">{chatError.message}</p>
					{onRetry && (
						<button onClick={onRetry} className="text-xs flex items-center gap-1 hover:underline mx-auto">
							<RefreshCw className="w-3 h-3" /> 重新发送
						</button>
					)}
				</div>
			</div>
		)
	}

	if (shouldVirtualize) {
		return (
			<div className="flex-1 overflow-y-auto chat-custom-scrollbar relative" ref={scrollRef} onScroll={handleScroll}>
				<div
					ref={listContainerRef}
					style={{ height: rowVirtualizer.getTotalSize(), width: '100%', position: 'relative' }}
				>
					{rowVirtualizer.getVirtualItems().map((vi) => (
						<div
							key={vi.key}
							data-index={vi.index}
							ref={rowVirtualizer.measureElement}
							style={{
								position: 'absolute',
								top: 0, left: 0, width: '100%',
								transform: `translateY(${vi.start - rowVirtualizer.options.scrollMargin}px)`,
							}}
						>
							{renderInner(messages[vi.index], vi.index)}
						</div>
					))}
				</div>
			</div>
		)
	}

	return (
		<div className="flex-1 overflow-y-auto chat-custom-scrollbar" ref={scrollRef} onScroll={handleScroll}>
			<div ref={listContainerRef} />
			{messages.map((msg, i) => renderInner(msg, i))}

			{/* 流式加载指示器 */}
			{isStreaming && messages.length > 0 && !messages[messages.length - 1]?.isLoading && (
				<div className="chat-message-row">
					<div className="avatar-ai">
						<Bot className="w-4 h-4" />
						<span className="avatar-status-indicator avatar-status-thinking" />
					</div>
					<div className="chat-typing-indicator">
						<span className="chat-typing-dot" />
						<span className="chat-typing-dot" />
						<span className="chat-typing-dot" />
					</div>
				</div>
			)}

			<div ref={bottomRef} />

			{/* 跳到底部按钮 */}
			{showScrollBtn && (
				<button onClick={scrollToBottom}
					className="sticky bottom-3 left-1/2 -translate-x-1/2 min-h-[36px] px-4 py-2 rounded-full surface-overlay80 backdrop-blur-md border border-neutral-200/60/60 shadow-lg shadow-neutral-200/50 dark:shadow-black/20 text-xs font-medium text-neutral-600 flex items-center gap-2 transition-all duration-200 ease-out hover:-translate-y-0.5 hover:shadow-xl hover:bg-white hover:border-primary-300/60 dark:hover:border-primary-600/40 active:translate-y-0 animate-fade-in"
				>
					<ChevronDown className="w-4 h-4" />
					<span>回到最新</span>
				</button>
			)}
		</div>
	)
}

export default MessageList

/**
 * ReasoningRow — DSH 风格思考过程行 (v3.0)
 *
 * 设计原则（对标 DSH ReasoningRow）：
 * - 折叠状态：单行 disclosure，高度固定 28px
 * - 展开状态：内联展开完整思考文本
 * - 流式时显示脉冲状态
 * - 极简视觉：无渐变背景、无边框、无算法标签堆砌
 *
 * @version 3.0.0
 */
import React, { useState, useRef, useEffect } from 'react'
import { ChevronRight, Loader2 } from 'lucide-react'

export interface ReasoningStep {
  step: string
  content: string
  status: 'thinking' | 'complete' | 'pending'
  detail?: string
}

interface ReasoningRowProps {
  steps: ReasoningStep[]
  isThinking: boolean
  elapsedMs?: number
}

function formatDuration(ms: number): string {
  if (ms < 1000) return `${ms}ms`
  return `${(ms / 1000).toFixed(1)}s`
}

export default function ReasoningRow({ steps, isThinking, elapsedMs }: ReasoningRowProps) {
  const [expanded, setExpanded] = useState(false)
  const contentRef = useRef<HTMLDivElement>(null)
  const completedCount = steps.filter(s => s.status === 'complete').length
  const pendingCount = steps.filter(s => s.status === 'pending').length

  // 流式完成时自动收起
  useEffect(() => {
    if (!isThinking && steps.length > 0 && completedCount === steps.length && expanded) {
      // 保持展开，让用户决定是否收起
    }
  }, [isThinking, completedCount, steps.length, expanded])

  if (steps.length === 0 && !isThinking) return null

  const isComplete = !isThinking && completedCount === steps.length
  const isPartial = !isThinking && completedCount > 0 && completedCount < steps.length

  return (
    <div className="my-1">
      {/* 折叠/展开 trigger — DSH 单行 disclosure 风格 */}
      <button
        onClick={() => setExpanded(!expanded)}
        className="w-full flex items-center gap-2 px-2 py-1.5 text-left rounded-md hover:bg-neutral-100 dark:hover:bg-neutral-800/50 transition-colors group"
        aria-expanded={expanded}
      >
        {/* 状态指示器 — DSH 风格：纯圆点 */}
        <span className={`flex-shrink-0 w-1.5 h-1.5 rounded-full ${
          isThinking ? 'bg-success-500 animate-pulse' :
          isComplete ? 'bg-success-500' :
          isPartial ? 'bg-warning-500' :
          'bg-neutral-400'
        }`} />

        {/* 摘要文字 — DSH 风格：简洁文本 */}
        <span className="text-xs text-neutral-500 dark:text-neutral-400 flex-1 truncate">
          {isThinking
            ? '正在思考…'
            : isComplete
              ? `思考完成 · ${completedCount} 步`
              : isPartial
                ? `思考中 · ${completedCount}/${steps.length} 步`
                : '思考过程'}
          {elapsedMs !== undefined && !isThinking && (
            <span className="text-neutral-400 dark:text-neutral-400 ml-1">· {formatDuration(elapsedMs)}</span>
          )}
        </span>

        {/* 展开箭头 */}
        <ChevronRight className={`w-3.5 h-3.5 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] transition-transform duration-150 flex-shrink-0 ${expanded ? 'rotate-90' : ''}`} />
      </button>

      {/* 展开内容 — 内联展示 */}
      <div
        ref={contentRef}
        className={`overflow-hidden transition-all duration-200 ${
          expanded ? 'max-h-[600px] opacity-100' : 'max-h-0 opacity-0'
        }`}
      >
        <div className="px-2 pb-1.5 space-y-0.5">
          {steps.map((step, i) => (
            <div
              key={i}
              className={`flex items-start gap-1.5 py-0.5 text-xs ${
                step.status === 'thinking' ? 'text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]' :
                step.status === 'complete' ? 'text-neutral-600 dark:text-neutral-300' :
                'text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]'
              }`}
            >
              {/* 步骤状态 */}
              <span className="flex-shrink-0 w-3 h-3 flex items-center justify-center mt-0.5">
                {step.status === 'complete' && (
                  <span className="w-1 h-1 rounded-full bg-success-500" />
                )}
                {step.status === 'thinking' && (
                  <Loader2 className="w-2.5 h-2.5 text-success-500 animate-spin" />
                )}
                {step.status === 'pending' && (
                  <span className="w-1 h-1 rounded-full bg-neutral-300 dark:bg-neutral-600" />
                )}
              </span>
              {/* 步骤内容 */}
              <span className="flex-1 min-w-0 truncate">
                <span className="font-medium">{step.step}</span>
                {step.content && (
                  <span className="text-neutral-400 dark:text-neutral-400 ml-1">{step.content}</span>
                )}
              </span>
            </div>
          ))}

          {/* 流式思考中 — 追加动态行 */}
          {isThinking && (
            <div className="flex items-center gap-1.5 py-0.5 text-xs text-[color:var(--text-muted)]">
              <Loader2 className="w-2.5 h-2.5 text-success-500 animate-spin flex-shrink-0" />
              <span>正在分析配方需求…</span>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

/**
 * TypewriterText — 打字机动画组件
 *
 * 逐字显示 AI 回复内容，模拟实时生成效果。
 * 支持：
 * - 可调速度
 * - 完成回调
 * - Markdown 兼容（逐块渲染）
 * - 跳跃完成（点击加速）
 */
import React, { useState, useEffect, useRef, useCallback } from 'react'
import MarkdownRenderer from './MarkdownRenderer'

interface TypewriterTextProps {
  content: string
  speed?: number        // 每字毫秒数（默认 30）
  chunkSize?: number     // 每次显示字数（默认 3）
  onComplete?: () => void
  enabled?: boolean      // 是否启用动画（默认 true）
}

export default function TypewriterText({
  content: rawContent,
  speed = 30,
  chunkSize = 3,
  onComplete,
  enabled = true,
}: TypewriterTextProps) {
  // 防御：上游（如 MessageBubble）在消息 content 字段缺失时会传入 null/undefined。
  // 若不在此归一化，下方 :47 的 content.length 会抛 TypeError。
  const content = rawContent ?? ''
  // Respect user's motion preference
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(() => {
    if (typeof window !== 'undefined' && window.matchMedia) {
      return window.matchMedia('(prefers-reduced-motion: reduce)').matches
    }
    return false
  })

  // Listen for changes to the reduced motion preference
  useEffect(() => {
    if (typeof window === 'undefined' || !window.matchMedia) return
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)')
    const handler = (e: MediaQueryListEvent | MediaQueryList) => setPrefersReducedMotion(e.matches)
    mq.addEventListener('change', handler as EventListener)
    return () => mq.removeEventListener('change', handler as EventListener)
  }, [])

  // 长内容自动跳过动画 — 避免不完整 Markdown 渲染导致内容丢失
  const isLongContent = content.length > 800
  const autoComplete = !enabled || isLongContent || prefersReducedMotion
  const [displayedLen, setDisplayedLen] = useState(autoComplete ? content.length : 0)
  const [isComplete, setIsComplete] = useState(autoComplete)
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null)
  const completedRef = useRef(false)

  // 点击跳过动画
  const skipToEnd = useCallback(() => {
    if (timerRef.current) clearInterval(timerRef.current)
    setDisplayedLen(content.length)
    setIsComplete(true)
    if (!completedRef.current) {
      completedRef.current = true
      onComplete?.()
    }
  }, [content.length, onComplete])

  useEffect(() => {
    if (!enabled || !content || isLongContent) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setDisplayedLen(content.length)
      setIsComplete(true)
      return
    }

    // 重置
    setDisplayedLen(0)
    setIsComplete(false)
    completedRef.current = false

    // 动态速度: 内容越长速度越快
    const adaptiveChunkSize = content.length > 300 ? 8 : content.length > 100 ? 5 : chunkSize

    timerRef.current = setInterval(() => {
      setDisplayedLen(prev => {
        const next = prev + adaptiveChunkSize
        if (next >= content.length) {
          clearInterval(timerRef.current!)
          setIsComplete(true)
          // 延迟回调确保状态更新
          setTimeout(() => {
            if (!completedRef.current) {
              completedRef.current = true
              onComplete?.()
            }
          }, 50)
          return content.length
        }
        return next
      })
    }, speed)

    return () => {
      if (timerRef.current) clearInterval(timerRef.current)
    }
  }, [content, enabled, speed, chunkSize, onComplete])

  // 计算百分比
  const progress = content.length > 0 ? (displayedLen / content.length) * 100 : 100

  // 不做动画时直接渲染
  if (!enabled || isComplete) {
    return (
      <div  role="button" tabIndex={0} onClick={skipToEnd} className="cursor-default">
        <MarkdownRenderer content={content} />
      </div>
    )
  }

  // 逐字模式：渲染已显示的部分
  const visibleText = content.slice(0, displayedLen)

  return (
    <div  role="button" tabIndex={0} onClick={skipToEnd} className="cursor-default group relative">
      <MarkdownRenderer content={visibleText} />

      {/* 闪烁光标 */}
      {displayedLen < content.length && (
        <span className="inline-block w-0.5 h-4 bg-primary-500 animate-pulse ml-0.5 align-text-bottom" />
      )}

      {/* 进度条（极简） */}
      {displayedLen < content.length && (
        <div className="h-0.5 bg-neutral-200 dark:bg-neutral-700 rounded-full mt-2 overflow-hidden opacity-0 group-hover:opacity-100 transition-opacity">
          <div
            className="h-full bg-primary-400 rounded-full transition-all duration-300"
            style={{ width: `${progress}%` }}
          />
        </div>
      )}
    </div>
  )
}

/**
 * ChatMessages 工具函数
 *
 * 从原 ChatMessages.tsx 提取的辅助函数和子组件
 */

import React from 'react'
import type { ChatMessage } from '../../hooks/useChatMessages'
import { detectStructuredContent } from '../structured/utils'
import StructuredMessageRenderer from '../structured/StructuredMessageRenderer'
import MarkdownRenderer from './MarkdownRenderer'

export type MessageType = 'text' | 'link' | 'code' | 'image' | 'file'

/**
 * 自动检测消息内容类型
 */
export function detectMessageType(content: string): MessageType {
	if (!content || !content.trim()) return 'text'
	const trimmed = content.trim()
	if (/^data:image\/(png|jpeg|jpg|gif|webp|svg\+xml);base64,/i.test(trimmed) || /\.(png|jpeg|jpg|gif|webp|svg|bmp)(\?|$)/i.test(trimmed)) {
		return 'image'
	}
	if (/^https?:\/\/\S+$/i.test(trimmed)) return 'link'
	const filePattern = /\S+\.(pdf|doc|docx|xls|xlsx|ppt|pptx|zip|rar|tar|gz|csv|txt|md|json|xml|yaml|yml)(\s|$)/i
	if (filePattern.test(trimmed) && !trimmed.includes('```')) return 'file'
	const lines = trimmed.split('\n')
	const isCodeBlock = trimmed.startsWith('```') && trimmed.endsWith('```')
	const isIndentedCode = lines.length >= 3 && lines.every(line => line.trim() === '' || /^\s{2,}/.test(line))
	if (isCodeBlock || isIndentedCode) return 'code'
	return 'text'
}

/**
 * 解析内容中的图表数据分隔符
 */
export function parseChartData(content: string): { textContent: string; chartJson: any } | null {
	const marker = '<!--DATA-->'
	const idx = content.indexOf(marker)
	if (idx === -1) return null
	const textContent = content.substring(0, idx).trim()
	const jsonStr = content.substring(idx + marker.length).trim()
	try {
		return { textContent, chartJson: JSON.parse(jsonStr) }
	} catch {
		return null
	}
}

/**
 * 渲染消息内容
 */
export function renderMessageContent(
	msg: ChatMessage,
	index: number,
	allMessages: ChatMessage[],
	streaming: boolean,
): React.ReactNode {
	void index;
	void allMessages;
	void streaming;
	if (msg.role === 'assistant') {
		const structured = detectStructuredContent(msg.content)
		if (structured) {
			return <StructuredMessageRenderer content={structured} />
		}
	}
	const type = msg.messageType || detectMessageType(msg.content)
	switch (type) {
		case 'link':
			return <LinkMessageCard url={msg.content.trim()} />
		case 'code':
			return <CodeMessageBlock code={msg.content} />
		case 'image':
			return <ImageMessageCard src={msg.content.trim()} />
		case 'file':
			return <FileMessageCard filename={msg.content.trim()} />
		default:
			return <MarkdownRenderer content={msg.content} />
	}
}

export function LinkMessageCard({ url }: { url: string }) {
	return <div className="chat-link-card">{url}</div>
}
export function CodeMessageBlock({ code }: { code: string }) {
	return <pre><code>{code}</code></pre>
}
export function ImageMessageCard({ src }: { src: string }) {
	return <img src={src} alt="image" className="w-full rounded" />
}
export function FileMessageCard({ filename }: { filename: string }) {
	return <div className="chat-file-card">{filename}</div>
}

export function tryExtractDomain(url: string): string | null {
	try {
		return new URL(url).hostname
	} catch {
		return null
	}
}
export function tryExtractTitle(url: string): string {
	try {
		const segments = new URL(url).pathname.split('/').filter(Boolean)
		return segments[segments.length - 1]?.replace(/\.[^.]+$/, '') || '链接'
	} catch {
		return '链接'
	}
}
export function extractExtension(filename: string): string {
	const match = filename.match(/\.([^.]+)$/)
	return match ? match[1].toUpperCase() : 'FILE'
}

