}

/**
 * 追问推荐引擎
 */
export class FollowUpSuggestionEngine {
  private context: ConversationContext = {
    topicKeywords: [],
    entities: [],
    messageCount: 0,
    hasFormulaOutput: false,
    hasSafetyWarning: false,
  }

  /**
   * 更新对话上下文
   */
  updateContext(context: Partial<ConversationContext>): void {
    this.context = { ...this.context, ...context }
    logger.debug('[FollowUpSuggestionEngine] Context updated:', this.context)
  }

  /**
   * 生成追问建议列表
   * 根据对话上下文从候选池中筛选最适合的问题
   */
  generateSuggestions(maxCount: number = 3): FollowUpSuggestion[] {
    const candidates = this.getCandidateQuestions()
    const scored = candidates.map(q => ({
      id: q.id,
      question: q.question,
      category: q.category,
      confidence: this.scoreQuestion(q),
      relatedEntities: this.extractRelatedEntities(q),
      relatedIntent: q.category,
    }))

    // 按置信度排序，取前N个
    const sorted = scored
      .sort((a, b) => b.confidence - a.confidence)
      .slice(0, maxCount)

    // 去重：相同category只保留最高分
    const seenCategories = new Set<string>()
    const unique = sorted.filter(s => {
      if (seenCategories.has(s.category)) return false
      seenCategories.add(s.category)
      return true
    })

    logger.info('[FollowUpSuggestionEngine] Generated suggestions:', unique.length)
    return unique
  }

  /**
   * 获取候选问题池
   */
  private getCandidateQuestions(): QuickQuestion[] {
    const candidates: QuickQuestion[] = []

    // 优先添加与当前上下文相关的问题
    const relatedByCategory = this.context.topicKeywords.length > 0
      ? QUICK_QUESTIONS.filter(q =>
        this.context.topicKeywords.some(kw =>
          q.question.includes(kw) || q.category.includes(kw)
        )
      )
      : []

    candidates.push(...relatedByCategory)

    // 根据对话阶段补充问题
    if (this.context.hasFormulaOutput) {
      // 已有配方输出，推荐深化相关问题
      const deepQuestions = QUICK_QUESTIONS.filter(q =>
        ['配方设计', '安全合规', '配伍知识'].includes(q.category)
      )
      candidates.push(...deepQuestions)
    }

    if (this.context.hasSafetyWarning) {
      // 有安全警告，推荐安全相关问题
      const safetyQuestions = QUICK_QUESTIONS.filter(q =>
        q.category === '安全合规'
      )
      candidates.push(...safetyQuestions)
    }

    // 补充热门问题
    const popularQuestions = QUICK_QUESTIONS.filter(q => q.popular)
    candidates.push(...popularQuestions)

    // 去重
    const unique = candidates.filter((q, index, self) =>
      index === self.findIndex(item => item.id === q.id)
    )

    return unique
  }

  /**
   * 对候选问题进行评分
   */
  private scoreQuestion(question: QuickQuestion): number {
    let score = 0.5 // 基础分

    // 热门问题加分
    if (question.popular) score += 0.15

    // 类别匹配加分
    if (this.context.topicKeywords.some(kw => question.question.includes(kw))) {
      score += 0.2
    }

    // 对话阶段适配加分
    if (this.context.hasFormulaOutput && question.category === '安全合规') {
      score += 0.15
    }
    if (this.context.hasFormulaOutput && question.category === '配方设计') {
      score += 0.1
    }
    if (this.context.messageCount > 5 && question.category === '配伍知识') {
      score += 0.1
    }

    // 多样性惩罚：避免推荐过多同类问题
    if (this.context.topicKeywords.length === 0 && question.popular) {
      score += 0.05
    }

    return Math.min(score, 1.0)
  }

  /**
   * 提取问题中相关的实体
   */
  private extractRelatedEntities(question: QuickQuestion): string[] {
    const entities: string[] = []
    const questionText = question.question.toLowerCase()

    // 简单实体匹配
    const knownEntities = [
      '黄芪', '党参', '枸杞', '人参', '桑叶', '苦瓜', '肉桂', '葛根',
      '睡眠', '血糖', '血压', '血脂', '免疫', '抗氧化', '肝', '肾',
    ]

    for (const entity of knownEntities) {
      if (questionText.includes(entity.toLowerCase())) {
        entities.push(entity)
      }
    }

    return entities
  }

  /**
   * 重置上下文
   */
  reset(): void {
    this.context = {
      topicKeywords: [],
      entities: [],
      messageCount: 0,
      hasFormulaOutput: false,
      hasSafetyWarning: false,
    }
    logger.debug('[FollowUpSuggestionEngine] Context reset')
  }
}

/**
 * 单例实例
 */
export const followUpSuggestionEngine = new FollowUpSuggestionEngine()
export default followUpSuggestionEngine

/**
 * formulaExtractorService — 从结构化聊天内容提取配方数据
 *
 * 功能：
 * 1. 从 StructuredContent JSON 中提取配方信息
 * 2. 从 Markdown 文本中解析表格数据
 * 3. 构建完整的 FormulaCandidate 对象
 *
 * 用法：
 * ```ts
 * const formula = extractFormulaFromContent(structuredContent)
 * if (formula) {
 *   await saveFormula(formula)
 * }
 * ```
 */
import { logger } from '@/utils/safeLogger'
import type { StructuredContent } from '../components/structured/types'
import type { AIRecognizedFormula } from '@/types/ai.types'

/** 从 content-block 中提取的配方成分 */
export interface ExtractedIngredient {
  name: string
  dosage: string
  function: string
  role?: '君' | '臣' | '佐' | '使'
}

/** 从结构化内容提取的完整配方 */
export interface ExtractedFormula {
  name: string
  description: string
  ingredients: ExtractedIngredient[]
  /** 多维评分数据 */
  scores?: Record<string, number>
  /** 配伍思路 */
  rationale?: string
  /** 注意事项 */
  precautions?: string[]
  /** 生产工艺 */
  productionSteps?: string[]
  /** 预期功效 */
  expectedEffects?: string[]
  /** 服用建议 */
  dosageAdvice?: string
  /** 来源 block 的原始数据 */
  rawContent?: StructuredContent
}

/**
 * 从 StructuredContent 中提取配方
 *
 * 提取策略：
 * 1. header block → 配方名称 + 描述
 * 2. data-table block → 成分列表
 * 3. metrics block → 多维评分
 * 4. callout blocks → 配伍思路/注意事项/功效
 * 5. list block → 生产工艺步骤
 */
export function extractFormulaFromContent(content: StructuredContent): ExtractedFormula | null {
  if (!content || !Array.isArray(content.blocks) || content.blocks.length === 0) {
    return null
  }

  const formula: ExtractedFormula = {
    name: '',
    description: '',
    ingredients: [],
    scores: {},
    rationale: '',
    precautions: [],
    productionSteps: [],
    expectedEffects: [],
    dosageAdvice: '',
    rawContent: content,
  }

  for (const block of content.blocks) {
    switch (block.type) {
      case 'header': {
        const h = block.data as { title?: string; description?: string }
        if (h.title) formula.name = h.title.replace(/^[🧪💊🍵🥤]?\s*/u, '')
        if (h.description) formula.description = h.description
        break
      }

      case 'data-table': {
        const dt = block.data as {
          columns?: Array<{ key: string; label: string }>
          rows?: Array<Record<string, unknown>>
        }
        if (dt.columns && dt.rows) {
          const nameKey = dt.columns.find(c => c.key === 'name')?.key || 'name'
          const dosageKey = dt.columns.find(c => c.key === 'dosage')?.key || 'dosage'
          const funcKey = dt.columns.find(c => c.key === 'function')?.key || 'function'
          const roleKey = dt.columns.find(c => c.key === 'role')?.key || 'role'

          formula.ingredients = dt.rows
            .filter(row => row[nameKey])
            .map(row => ({
              name: String(row[nameKey] ?? ''),
              dosage: String(row[dosageKey] ?? ''),
              function: String(row[funcKey] ?? ''),
              role: row[roleKey] as ExtractedIngredient['role'],
            }))
        }
        break
      }

      case 'metrics': {
        const m = block.data as { items?: Array<{ label: string; value: number }> }
        if (m.items) {
          formula.scores = Object.fromEntries(
            m.items.map(i => [i.label, typeof i.value === 'number' ? i.value : parseFloat(String(i.value)) || 0])
          )
        }
        break
      }

      case 'callout': {
        const c = block.data as { variant?: string; title?: string; content?: string }
        if (!c.content) break
        const lowerTitle = (c.title || '').toLowerCase()
        const lowerVariant = (c.variant || '').toLowerCase()

        if (lowerTitle.includes('配伍') || lowerTitle.includes('思路')) {
          formula.rationale = c.content
        } else if (lowerTitle.includes('注意') || lowerVariant === 'warning') {
          // 解析注意事项为数组
          const lines = c.content.split(/(?=\d+[.、])/).filter(s => s.trim())
          formula.precautions = lines.map(l => l.trim()).filter(Boolean)
        } else if (lowerTitle.includes('预期') || lowerTitle.includes('功效')) {
          const lines = c.content.split(/[；;。]/).filter(s => s.trim().length > 5)
          formula.expectedEffects = lines.map(l => l.trim()).filter(Boolean)
        } else if (lowerTitle.includes('总结') || lowerVariant === 'summary') {
          // 保存为备选描述
          if (!formula.description) formula.description = c.content
        }
        break
      }

      case 'list': {
        const l = block.data as { variant?: string; items?: Array<{ label: string; description?: string }> }
        if (l.items && l.items.length > 0) {
          const firstLabel = l.items[0].label
          if (firstLabel.includes('原料') || firstLabel.includes('水处理') || firstLabel.includes('溶解')) {
            // 生产工艺
            formula.productionSteps = l.items.map(i => `${i.label}${i.description ? '：' + i.description : ''}`)
          }
        }
        break
      }
    }
  }

  // 如果未从 data-table 提取到成分，尝试从 ingredients detail blocks 提取
  if (formula.ingredients.length === 0) {
    for (const block of content.blocks) {
      if (block.type === 'ingredient-detail') {
        const d = block.data as { name?: string; dosage_range?: string; efficacy?: string }
        if (d.name) {
          formula.ingredients.push({
            name: d.name,
            dosage: d.dosage_range || '',
            function: d.efficacy || '',
          })
        }
      }
    }
  }

  // 基本验证
  if (!formula.name && formula.ingredients.length === 0) {
    logger.warn('[formulaExtractor] 未能从内容中提取有效配方:', content)
    return null
  }

  logger.info('[formulaExtractor] 提取配方成功:', {
    name: formula.name,
    ingredientCount: formula.ingredients.length,
  })

  return formula
}

/**
 * 从 Markdown 文本中解析配方表格
 * 兼容旧版 Markdown 格式输出
 */
export function extractFormulaFromMarkdown(text: string): ExtractedFormula | null {
  const formula: ExtractedFormula = {
    name: '',
    description: '',
    ingredients: [],
    scores: {},
    rationale: '',
    precautions: [],
    productionSteps: [],
    expectedEffects: [],
    dosageAdvice: '',
  }

  // 提取配方名称（标题行）
  const titleMatch = text.match(/^#\s+(.+)$/m)
  if (titleMatch) {
    formula.name = titleMatch[1].replace(/^[🧪💊🍵🥤]?\s*/u, '').trim()
  }

  // 解析表格
  const tableLines = text.match(/\|(.+)\|[\s\S]*?\|(?:[-:| ]+)\|([\s\S]*?)(?=\n\s*\|.*?:|$)/)
  if (tableLines) {
    const rows = tableLines[2].split('\n').filter(l => l.trim().startsWith('|'))
    for (const row of rows) {
      const cells = row.split('|').filter(c => c.trim())
      if (cells.length >= 3) {
        formula.ingredients.push({
          name: cells[0]?.trim() || '',
          dosage: cells[1]?.trim() || '',
          function: cells[2]?.trim() || '',
        })
      }
    }
  }

  // 提取注意事项
  const warningMatch = text.match(/####\s*注意事项[\s\S]*?(?=####|$)/)
  if (warningMatch) {
    const lines = warningMatch[0].split('\n').filter(l => l.trim().startsWith('-') || l.trim().match(/^\d+\./))
    formula.precautions = lines.map(l => l.replace(/^[-\d.]+\s*/, '').trim()).filter(Boolean)
  }

  return formula.ingredients.length > 0 ? formula : null
}

/**
 * 将提取的配方转换为 AIRecognizedFormula 格式
 * 以便直接保存到 formulaIndex
 */
export function toAIRecognizedFormula(extracted: ExtractedFormula): AIRecognizedFormula {
  return {
    id: '',
    name: extracted.name || '未命名配方',
    ingredientCount: extracted.ingredients.length,
    confidence: extracted.ingredients.length > 0 ? 0.9 : 0.5,
    sourceMessageId: '',
    parsedAt: new Date(),
    rawData: {} as any,
    ingredients: extracted.ingredients.map(i => ({
      name: i.name,
      dosage: i.dosage,
      role: i.role,
    })),
  }
}

/**
 * 生成配方的唯一 ID
 */
export function generateFormulaId(name: string, timestamp: number = Date.now()): string {
  const slug = name
    .replace(/[^\u4e00-\u9fa5a-zA-Z0-9]/g, '-')
    .slice(0, 20)
    .toLowerCase()
  return `formula_${slug}_${timestamp}`
}

/**
 * FormulaIntelligenceService — 配方智能对话服务
 *
 * 将 FormulaDesignEngine 集成到 AI 对话流中：
 * 1. 从用户自然语言输入中提取配方需求
 * 2. 调用 FormulaDesignEngine 生成配方
 * 3. 将结果转换为结构化内容块
 * 4. 支持多轮配方优化对话
 *
 * @version 1.0.0
 */

import { FormulaDesignEngine, formulaDesignEngine } from './formulaDesignEngine'
import type { FormulaCandidate, FormulaDesignRequest, ScoreDimension } from './formulaDesignEngine'
import { FormulaDialogueManager } from './dialogue/FormulaDialogueManager'
import { knowledgeGraph } from './knowledge/FormulaKnowledgeGraph'
import { logger } from '@/utils/safeLogger'

/* ================================================================== */
/*  类型定义                                                            */
/* ================================================================== */

export interface DialogueState {
  sessionId: string
  currentFormula: FormulaCandidate | null
  optimizationHistory: FormulaCandidate[]
  userPreferences: {
    targetEffects: string[]
    constraints: FormulaDesignRequest['constraints']
    userProfile: FormulaDesignRequest['userProfile']
  }
  dialogueRound: number
  lastQuery: string
}

/** 意图类型 */
export type IntentType =
  | 'formula_design'      // 设计新配方
  | 'formula_optimize'    // 优化现有配方
  | 'formula_analyze'     // 分析配方
  | 'ingredient_query'    // 查询成分
  | 'general_chat'        // 普通聊天

/* ================================================================== */
/*  对话式配方设计服务                                                  */
/* ================================================================== */

export class FormulaIntelligenceService {
  private engine: FormulaDesignEngine
  private dialogueSessions: Map<string, DialogueState>
  private dialogueManager: FormulaDialogueManager

  constructor() {
    this.engine = formulaDesignEngine
    this.dialogueSessions = new Map()
    this.dialogueManager = new FormulaDialogueManager()
  }

  /* ================================================================ */
  /*  1. 意图识别                                                      */
  /* ================================================================ */

  /**
   * 识别用户意图
   * 简单 NLP 规则引擎，识别配方相关意图
   */
  detectIntent(query: string): IntentType {
    const q = query.toLowerCase()

    // 配方设计意图
    const designKeywords = [
      '设计', '配方', '做一款', '开发', '研发', '调配',
      '帮我配', '我想做', '定制', 'create', 'formula', 'design',
    ]
    if (designKeywords.some(k => q.includes(k))) return 'formula_design'

    // 优化意图
    const optimizeKeywords = ['优化', '改进', '改善', '提升', '修改', '调整', 'optimize', 'improve']
    if (optimizeKeywords.some(k => q.includes(k))) return 'formula_optimize'

    // 分析意图
    const analyzeKeywords = ['分析', '评估', '评价', '评分', '怎么样', 'analyze', 'evaluate']
    if (analyzeKeywords.some(k => q.includes(k))) return 'formula_analyze'

    // 成分查询
    const ingredientKeywords = ['成分', '原料', '药材', '功效', '作用', 'ingredient', 'effect']
    if (ingredientKeywords.some(k => q.includes(k))) return 'ingredient_query'

    return 'general_chat'
  }

  /* ================================================================ */
  /*  2. 需求提取                                                      */
  /* ================================================================ */

  /**
   * 从自然语言中提取配方设计参数
   */
  extractDesignRequest(query: string, sessionId: string): FormulaDesignRequest {
    const q = query.toLowerCase()
    const session = this.getOrCreateSession(sessionId)
    const effects = this.extractTargetEffects(q)

    // 更新会话偏好
    if (effects.length > 0) {
      session.userPreferences.targetEffects = [
        ...new Set([...session.userPreferences.targetEffects, ...effects]),
      ]
    }

    return {
      targetEffects: effects.length > 0 ? effects : session.userPreferences.targetEffects,
      constraints: session.userPreferences.constraints,
      userProfile: session.userPreferences.userProfile,
    }
  }

  /** 提取目标功效关键词 */
  private extractTargetEffects(query: string): string[] {
    const effectMap: Record<string, string[]> = {
      immunity: ['免疫', '免疫力', '增强免疫', '提高免疫', '抵抗力'],
      anti_fatigue: ['抗疲劳', '疲劳', '乏力', '精力', '提神', '恢复体力'],
      anti_oxidant: ['抗氧化', '延缓衰老', '自由基', '抗氧化'],
      skin_health: ['皮肤', '美容', '护肤', '美白', '胶原蛋白', '养颜'],
      gut_health: ['肠道', '消化', '肠胃', '益生菌', '调理肠胃', '通便'],
      liver_protect: ['护肝', '保肝', '解酒', '肝脏', '肝'],
      cognition: ['健脑', '记忆力', '认知', '大脑', '智力', '专注'],
      joint_health: ['关节', '骨骼', '骨', '关节健康', '补钙'],
      anti_inflammatory: ['抗炎', '消炎', '炎', '舒缓'],
      vision: ['视力', '护眼', '眼', '明目'],
      vitality: ['活力', '强身', '整体健康', '增强体质', '强身健体'],
      metabolism: ['代谢', '减肥', '体重', '血糖', '降糖', '血脂'],
      cardio_protect: ['心血管', '心脏', '血管', '血压', '降血压', '降血脂', '三高', '降三高'],
      anti_aging: ['抗衰老', '衰老', '逆龄', '延年益寿', '长寿'],
      blood_sugar: ['降血糖', '血糖', '糖尿', '降糖'],
      peptide: ['多肽', '肽', '复合肽', '小分子肽', '胶原肽'],
      sleep: ['睡眠', '助眠', '失眠', '安神'],
    }

    const detected: string[] = []
    for (const [effect, keywords] of Object.entries(effectMap)) {
      if (keywords.some(kw => query.includes(kw))) {
        detected.push(effect)
      }
    }

    return detected
  }

  /* ================================================================ */
  /*  3. 对话管理                                                      */
  /* ================================================================ */

  getOrCreateSession(sessionId: string): DialogueState {
    if (!this.dialogueSessions.has(sessionId)) {
      this.dialogueSessions.set(sessionId, {
        sessionId,
        currentFormula: null,
        optimizationHistory: [],
        userPreferences: {
          targetEffects: [],
          constraints: {},
          userProfile: {},
        },
        dialogueRound: 0,
        lastQuery: '',
      })
    }
    return this.dialogueSessions.get(sessionId)!
  }

  /* ================================================================ */
  /*  4. 核心对话处理                                                  */
  /* ================================================================ */

  /**
   * 处理用户对话输入，返回结构化内容块
   */
  processUserInput(query: string, sessionId: string): {
    blocks: Array<{ type: string; data: any }>
    sessionState: DialogueState
  } {
    const session = this.getOrCreateSession(sessionId)
    session.lastQuery = query
    session.dialogueRound++

    const intent = this.detectIntent(query)
    logger.info('[FormulaIntelligence] Detected intent:', { intent, round: session.dialogueRound })

    switch (intent) {
      case 'formula_design':
        return this.handleFormulaDesign(query, session)
      case 'formula_optimize':
        return this.handleFormulaOptimize(query, session)
      case 'formula_analyze':
        return this.handleFormulaAnalyze(query, session)
      case 'ingredient_query':
        return this.handleIngredientQuery(query, session)
      case 'general_chat':
      default:
        return this.handleGeneralChat(query, session)
    }
  }

  private handleFormulaDesign(query: string, session: DialogueState) {
    // v2.0: 使用对话管理器 + 遗传算法 + 知识图谱
    try {
      const blocks = this.dialogueManager.process(query)
      if (blocks.length > 0) {
        return { blocks, sessionState: session }
      }
    } catch (_e) {
      // fallback to v1 engine
    }
    const request = this.extractDesignRequest(query, session.sessionId)

    if (request.targetEffects.length === 0) {
      return {
        blocks: [{
          type: 'callout',
          data: {
            variant: 'info',
            title: '配方需求',
            content: '请告诉我您想要的配方功效方向，例如：\n• "我想设计一款增强免疫力的配方"\n• "帮我做一款抗疲劳的固体饮料"\n• "设计一款美容护肤的胶原蛋白肽产品"',
          },
        }],
        sessionState: session,
      }
    }

    // 生成配方
    const formula = this.engine.generateFormula(request)
    session.currentFormula = formula
    session.optimizationHistory.push(formula)

    // 转为结构化内容块
    const blocks = this.engine.toStructuredBlocks(formula)
    // v2.0: 添加知识图谱分析
    const ingIds = formula.ingredients.map(i => i.profile.id)
    const knowledgeStats = knowledgeGraph.getStats()
    if (knowledgeStats.ingredients > 0) {
      const compatMatrix = this.engine.analyzeCompatibility(ingIds)
      const synergyCount = compatMatrix.filter(m => m.interaction === 'synergy').length
      const warningCount = compatMatrix.filter(m => m.interaction === 'antagonism').length
      // Insert compatibility metric
      blocks.splice(2, 0, {
        type: 'metrics',
        data: {
          title: '配伍分析',
          items: [
            { label: '协同组合', value: synergyCount, unit: '项', trend: 'up' },
            { label: '注意事项', value: warningCount, unit: '项', trend: warningCount > 0 ? 'down' : 'stable' },
          ],
        },
      })
    }

    // 添加对话引导
    blocks.push({
      type: 'callout',
      data: {
        variant: 'info',
        title: '下一步操作',
        content: '您可以通过以下指令继续优化：\n• "优化这个配方" — 自动迭代优化\n• "增加XXX成分" — 添加指定成分\n• "调整用量" — 微调各成分比例\n• "分析安全性" — 详细安全评估',
      },
    })

    return { blocks, sessionState: session }
  }

  private handleFormulaOptimize(query: string, session: DialogueState) {
    if (!session.currentFormula) {
      return this.handleFormulaDesign(query, session)
    }

    const optimized = this.engine.optimizeFormula(session.currentFormula, 3)
    const best = optimized[0]
    session.currentFormula = best
    session.optimizationHistory.push(best)

    const blocks = this.engine.toStructuredBlocks(best)

    // 添加优化对比
    if (optimized.length > 1) {
      blocks.splice(2, 0, {
        type: 'data-table',
        data: {
          title: 'Pareto 优化对比',
          columns: [
            { key: 'name', label: '配方版本' },
            { key: 'efficacy', label: '功效', type: 'percentage', align: 'center' },
            { key: 'safety', label: '安全', type: 'percentage', align: 'center' },
            { key: 'overall', label: '综合', type: 'percentage', align: 'center' },
            { key: 'change', label: '变化' },
          ],
          rows: optimized.slice(0, 4).map((f, i) => ({
            name: i === 0 ? '优化版 ✓' : `备选 ${i}`,
            efficacy: f.scores.efficacy,
            safety: f.scores.safety,
            overall: f.overallScore,
            change: i === 0 ? '最优解' : `综合+${(f.overallScore - optimized[0].overallScore > 0.01 ? '+' : '')}${Math.round((f.overallScore - optimized[0].overallScore) * 100)}%`,
          })),
          summary: `经过 ${optimized.length} 轮 Pareto 优化，综合评分提升 ${Math.round((best.overallScore - session.optimizationHistory[0].overallScore) * 100)}%`,
        },
      })
    }

    blocks.push({
      type: 'callout',
      data: {
        variant: 'success',
        title: '优化完成',
        content: `配方已迭代优化至第 ${session.optimizationHistory.length} 版。您可以继续调整或确认此方案。`,
      },
    })

    return { blocks, sessionState: session }
  }

