interface IntentDetectionResult {
  primaryIntent: IntentType
  confidence: number
  subIntents?: SubIntent[]
  method: string
  processingTime?: number
  /** 候选意图列表（置信度较低的备选） */
  alternativeIntents?: { intent: IntentType; confidence: number }[]
  entities?: {
    type: string
    text: string
    confidence: number
    position?: [number, number]
  }[]
