  })

  describe('highlightKeywords', () => {
    it('应高亮匹配的关键词', () => {
      const text = 'Hello world, this is a test'
      const result = highlightKeywords(text, ['world', 'test'])
      expect(result).toBe('Hello <mark>world</mark>, this is a <mark>test</mark>')
    })

    it('应忽略空关键词', () => {
      const text = 'Hello world'
