    })

    it('应统一换行符', () => {
      const text = 'Line1\r\nLine2\n\n\nLine3'
      expect(normalizeText(text)).toBe('Line1\nLine2\n\nLine3')
    })

    it('应去除首尾空格', () => {
      const text = '  Hello world  '
      expect(normalizeText(text)).toBe('Hello world')
    })
  })

  describe('detectLanguage', () => {
    it('应检测中文', () => {
      expect(detectLanguage('你好世界')).toBe('zh')
    })

    it('应检测英文', () => {
      expect(detectLanguage('Hello world')).toBe('en')
    })

    it('应检测混合语言', () => {
      expect(detectLanguage('中文测试 English 编程')).toBe('mixed')
    })

    it('应处理空文本', () => {
      expect(detectLanguage('')).toBe('unknown')
    })
  })

  describe('formatFileSize', () => {
    it('应格式化字节', () => {
      expect(formatFileSize(100)).toBe('100 B')
    })

    it('应格式化KB', () => {
      expect(formatFileSize(2048)).toBe('2.0 KB')
    })

    it('应格式化MB', () => {
      expect(formatFileSize(3 * 1024 * 1024)).toBe('3.0 MB')
    })

    it('应格式化GB', () => {
      expect(formatFileSize(4 * 1024 * 1024 * 1024)).toBe('4.0 GB')
    })

    it('应处理0字节', () => {
      expect(formatFileSize(0)).toBe('0 B')
    })
  })

  describe('debounce', () => {
    it('应延迟执行函数', async () => {
      vi.useFakeTimers()
      const mockFn = vi.fn()
      const debouncedFn = debounce(mockFn, 100)

      debouncedFn()
      debouncedFn()
      debouncedFn()

      expect(mockFn).not.toHaveBeenCalled()

      vi.advanceTimersByTime(100)
      expect(mockFn).toHaveBeenCalledTimes(1)

      vi.useRealTimers()
    })

    it('应在延迟后执行', async () => {
      vi.useFakeTimers()
      const mockFn = vi.fn()
      const debouncedFn = debounce(mockFn, 50)

      debouncedFn()
      vi.advanceTimersByTime(49)
      expect(mockFn).not.toHaveBeenCalled()

      vi.advanceTimersByTime(1)
      expect(mockFn).toHaveBeenCalled()

      vi.useRealTimers()
    })
  })

  describe('throttle', () => {
    it('应限制函数执行频率', async () => {
      vi.useFakeTimers()
      const mockFn = vi.fn()
      const throttledFn = throttle(mockFn, 100)

      throttledFn()
      throttledFn()
      throttledFn()

      expect(mockFn).toHaveBeenCalledTimes(1)

      vi.advanceTimersByTime(100)
      throttledFn()
      expect(mockFn).toHaveBeenCalledTimes(2)

      vi.useRealTimers()
    })

    it('应在限制时间内只执行一次', async () => {
      vi.useFakeTimers()
      const mockFn = vi.fn()
      const throttledFn = throttle(mockFn, 50)

      throttledFn()
      throttledFn()
      vi.advanceTimersByTime(49)
      throttledFn()

      expect(mockFn).toHaveBeenCalledTimes(1)

      vi.advanceTimersByTime(1)
      throttledFn()
      expect(mockFn).toHaveBeenCalledTimes(2)

      vi.useRealTimers()
    })
  })
})

/**
