﻿import type { ChatMessage } from '../types'

/**
 * 历史消息一次性清理：过滤 v12 精简前遗留在 localStorage 的"脚手架污染"消息。
 *
 * 背景：早期版本把增强 Prompt（含系统提示词/意图分析/记忆摘要/JSON 输出模板）
 * 直接作为用户可见内容渲染并持久化，另有 React "Invalid hook call" 失败气泡残留。
 * v12 起已改为"发送增强内容、显示原始文本"，但旧数据仍会污染界面。
 */

// 用户/AI 内容中出现即判定为脚手架泄漏
const SCAFFOLD_MARKERS = [
  '[场景识别]',
  '[意图分析]',
  '[记忆摘要]',
  '[多轮对话]',
  '[用户输入]',
  '[近期对话]',
  '【输出格式要求】',
  '[object Object]',
] as const

// error 字段中出现即判定为 React 运行时错误气泡
const RUNTIME_ERROR_MARKERS = [
  'Invalid hook call',
  'Rules of Hooks',
  'Minified React error',
  'react.dev',
] as const

// 完整系统提示词特征：三个标题同时出现才判定，避免误伤正常问答
const SYSTEM_PROMPT_SIGNATURE = ['核心能力', '回复规范', '禁止行为'] as const

function isSystemPromptLeak(text: string): boolean {
  return SYSTEM_PROMPT_SIGNATURE.every((sig) => text.includes(sig))
}

function isPolluted(message: ChatMessage): boolean {
  const content = message.content ?? ''
  const error = message.error ?? ''

  if (SCAFFOLD_MARKERS.some((m) => content.includes(m))) return true
  if (isSystemPromptLeak(content)) return true
  if (error && RUNTIME_ERROR_MARKERS.some((m) => error.includes(m))) return true

  return false
}

export interface SanitizeResult {
  messages: ChatMessage[]
  removedCount: number
}

/**
 * 过滤污染消息，返回清理后的消息数组与移除数量。
 */
export function sanitizeChatMessages(messages: ChatMessage[]): SanitizeResult {
  if (!Array.isArray(messages) || messages.length === 0) {
    return { messages: messages ?? [], removedCount: 0 }
  }

  const cleaned = messages
  .filter((m) => !isPolluted(m))
  .map(m => ({
    ...m,
    content: m.role === 'assistant' ? stripJsonWrapper(m.content || '') : m.content
  })).map((m) => {
    // 清理旧格式消息内容
    if (m.role === 'assistant' && m.content) {
      const stripped = stripJsonWrapper(m.content)
      if (stripped !== m.content) {
        return { ...m, content: stripped }
      }
    }
    return m
  })

  return { messages: cleaned, removedCount: messages.length - cleaned.length }
}


// 过滤污染消息，返回清理后的消息数组与移除数量。

/**
 * 清理消息内容：检测并剥离 ```json ... ``` 包装（旧格式遗留）
 * 将原始 JSON 字符串中的结构化内容提取出来，便于前端正确渲染
 */
function stripJsonWrapper(content: string): string {
  if (!content) return content
  const trimmed = content.trim()
  // 如果内容以 ```json 开头且以 ``` 结尾，提取内部 JSON
  const match = trimmed.match(/^```(?:json)?\s*\n([\s\S]*?)\n?\s*```$/)
  if (match) {
    return match[1].trim()
  }
  return content
}

/**
 * 检测消息是否为旧版 thinking_engine 输出的原始 Markdown（非结构化）
 * 这类消息会被渲染为普通文本，不会显示结构化 block
 */
function isOldFormatMessage(msg: ChatMessage): boolean {
  if (msg.role !== 'assistant') return false
  const content = msg.content ?? ''
  // 旧格式特征：包含 thinking_engine 输出标记或纯 Markdown 无 JSON 包装
  const hasThinkingMarkers = /\[思考步骤\]|\[Step \d+\]/.test(content)
  const hasRawMarkdown = content.startsWith('#') && !content.includes('```json')
  return hasThinkingMarkers || hasRawMarkdown
}

/**
 * Waterfall 事件系统 v2.1
 *
 * 基于 DeepSeek Harness 的 waterfall 事件模型完整实现：
 * - 强制 next() 调用机制
 * - 完整的 6 个 Waterfall 事件类型
 * - 1 个 Serial 事件类型 (agent/turn-stopping)
 * - 事件数据强类型
 * - 监听器统计和调试信息
 */

import { logger } from '@/utils/safeLogger';
import type {
  WaterfallEvent,
  WaterfallEventData,
  SerialEvent,
  SerialEventData,
} from '@/components/ai/shared/types';

// ── 监听器类型 ─────────────────────────────────────────────

export type WaterfallHandler = (data: any, next: () => void) => void;
export type SerialHandler = (data: any) => void;

// ── WaterfallEmitter 类 ────────────────────────────────────

export class WaterfallEmitter {
  private waterfallListeners: Map<WaterfallEvent, WaterfallHandler[]> = new Map();
  private serialListeners: Map<SerialEvent, SerialHandler[]> = new Map();
  private enabled = true;
  private listenersCount = 0;

  /** 注册 Waterfall 监听器 (必须调用 next()) */
  on(event: WaterfallEvent, handler: WaterfallHandler): () => void {
    if (!this.enabled) {
      logger.warn('[Waterfall] Emitter disabled, listener not registered');
      return () => {};
    }

    const list = this.waterfallListeners.get(event) ?? [];
    list.push(handler);
    this.waterfallListeners.set(event, list);
    this.listenersCount++;

    return () => {
      const current = this.waterfallListeners.get(event) ?? [];
      this.waterfallListeners.set(
        event,
        current.filter((h) => h !== handler),
      );
      this.listenersCount--;
    };
  }

  /** 注册一次性 Waterfall 监听器 */
  once(event: WaterfallEvent, handler: WaterfallHandler): () => void {
    const wrapper = (data: any, next: () => void) => {
      handler(data, next);
      this.off(event, wrapper);
    };
    return this.on(event as WaterfallEvent, wrapper)
  }

  /** 移除 Waterfall 监听器 */
  off(event: WaterfallEvent, handler: WaterfallHandler): void {
    const list = this.waterfallListeners.get(event) ?? [];
    this.waterfallListeners.set(
      event,
      list.filter((h) => h !== handler),
    );
    this.listenersCount--;
  }

  /** 注册 Serial 监听器 (无需调用 next) */
  onSerial(event: SerialEvent, handler: SerialHandler): () => void {
    if (!this.enabled) return () => {};

    const list = this.serialListeners.get(event) ?? [];
    list.push(handler);
    this.serialListeners.set(event, list);
    this.listenersCount++;

    return () => {
      this.serialListeners.set(
        event,
        list.filter((h) => h !== handler),
      );
      this.listenersCount--;
    };
  }

  /**
   * 触发 Waterfall 事件
   * 所有监听器必须调用 next() 才能继续委托
   * 如果监听器没有调用 next()，会自动继续 (带警告)
   */
  async emit<T extends WaterfallEvent>(
    event: T,
    data: any,
  ): Promise<any> {
    if (!this.enabled) return data;

    const list = this.waterfallListeners.get(event) ?? [];
    if (list.length === 0) return data;

    const currentData = data;

    for (const handler of list) {
      let nextCalled = false;

      await new Promise<void>((resolve) => {
        const next = () => {
          nextCalled = true;
          resolve();
        };

        try {
          handler(currentData, next);
        } catch (err) {
          logger.error(`[Waterfall] Listener error on ${event}:`, err);
          next(); // 出错时也继续
        }

        // 如果 handler 没有调用 next()，等待一小段时间后自动继续
        if (!nextCalled) {
          setTimeout(() => {
            if (!nextCalled) {
              logger.warn(`[Waterfall] Listener did not call next() for ${event}, auto-continuing`);
              resolve();
            }
          }, 100);
        }
      });
    }

    return currentData;
  }

  /**
   * 触发 Serial 事件
   */
  async emitSerial<T extends SerialEvent>(
    event: T,
    data: SerialEventData[T],
  ): Promise<void> {
    if (!this.enabled) return;

    const list = this.serialListeners.get(event) ?? [];
    for (const handler of list) {
      try {
        handler(data);
      } catch (err) {
        logger.error(`[Waterfall] Serial listener error on ${event}:`, err);
      }
    }
  }

  /** 禁用/启用事件系统 */
  setEnabled(enabled: boolean): void {
    this.enabled = enabled;
    if (!enabled) {
      logger.info('[Waterfall] Emitter disabled');
    }
  }

  /** 获取监听器统计 */
  get stats() {
    let count = 0;
    this.waterfallListeners.forEach((listeners) => (count += listeners.length));
    this.serialListeners.forEach((listeners) => (count += listeners.length));
    return {
      waterfallEvents: this.waterfallListeners.size,
      serialEvents: this.serialListeners.size,
      totalListeners: count,
      enabled: this.enabled,
    };
  }

  /** 清除所有监听器 */
  clear(): void {
    this.waterfallListeners.clear();
    this.serialListeners.clear();
    this.listenersCount = 0;
    logger.info('[Waterfall] All listeners cleared');
  }
}

// ── 全局单例 ───────────────────────────────────────────────

let _emitter: WaterfallEmitter | null = null;

export function getWaterfallEmitter(): WaterfallEmitter {
  if (!_emitter) {
    _emitter = new WaterfallEmitter();
    logger.info('[Waterfall] Global emitter initialized');
  }
  return _emitter;
}

/** 重置全局 emitter (用于测试) */
export function resetWaterfallEmitter(): void {
  _emitter = null;
}

// ── 事件工厂函数 ───────────────────────────────────────────

export const waterfallEvents = {
  /** agent/pre-step: 决定是否进入 step */
  preStep: (input: string, turnId: string) => ({
    event: 'agent/pre-step' as WaterfallEvent,
    data: { input, turnId } as WaterfallEventData['agent/pre-step'],
  }),

  /** agent/request: 模型请求前预处理 */
  request: (turnId: string, model: string) => ({
    event: 'agent/request' as WaterfallEvent,
    data: { turnId, model } as WaterfallEventData['agent/request'],
  }),

  /** llm/stream: 流式响应 */
  stream: (turnId: string, chunk: string) => ({
    event: 'llm/stream' as WaterfallEvent,
    data: { turnId, chunk } as WaterfallEventData['llm/stream'],
  }),

  /** tools/pre-execute: 工具执行前 */
  preExecute: (toolCalls: any[]) => ({
    event: 'tools/pre-execute' as WaterfallEvent,
    data: { toolCalls } as WaterfallEventData['tools/pre-execute'],
  }),

  /** tools/execute: 工具执行中 */
  execute: (toolCalls: any[]) => ({
    event: 'tools/execute' as WaterfallEvent,
    data: { toolCalls } as WaterfallEventData['tools/execute'],
  }),

  /** tools/post-execute: 工具执行后 */
  postExecute: (results: any[]) => ({
    event: 'tools/post-execute' as WaterfallEvent,
    data: { results } as WaterfallEventData['tools/post-execute'],
  }),

  /** agent/turn-stopping: 最终拦截点 (Serial) */
  turnStopping: (turnId: string, reason: 'completed' | 'cancelled' | 'timeout') => ({
    event: 'agent/turn-stopping' as SerialEvent,
    data: { turnId, reason } as SerialEventData['agent/turn-stopping'],
  }),
};

/**
 * DocumentUploader - RAG 知识库文档上传组件
 *
 * 支持拖拽/点击上传 PDF、TXT、CSV、MD 文件
 * 实时显示上传进度和解析结果
 */

import React, { useState, useCallback, useRef } from 'react'
import { Upload, FileText, X, CheckCircle, AlertCircle, Loader2 } from 'lucide-react'
import { uploadDocument, type DocumentInfo } from '@/api/rag'
import { clsx } from 'clsx'

interface DocumentUploaderProps {
  onUploadSuccess?: (doc: DocumentInfo) => void
  maxSizeMB?: number
}

const ACCEPTED_TYPES = '.pdf,.txt,.csv,.md'
const ACCEPTED_TYPES_LABEL = 'PDF, TXT, CSV, MD'

export function DocumentUploader({ onUploadSuccess, maxSizeMB = 20 }: DocumentUploaderProps) {
  const [isDragging, setIsDragging] = useState(false)
  const [isUploading, setIsUploading] = useState(false)
  const [progress, setProgress] = useState(0)
  const [uploadResult, setUploadResult] = useState<{ type: 'success' | 'error'; message: string } | null>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const handleFile = useCallback(async (file: File) => {
    // 验证类型
    const ext = '.' + file.name.split('.').pop()?.toLowerCase()
    if (!ACCEPTED_TYPES.includes(ext)) {
      setUploadResult({ type: 'error', message: `不支持的文件类型 "${ext}"，仅支持 ${ACCEPTED_TYPES_LABEL}` })
      return
    }

    // 验证大小
    if (file.size > maxSizeMB * 1024 * 1024) {
      setUploadResult({ type: 'error', message: `文件大小超过 ${maxSizeMB}MB 限制` })
      return
    }

    setIsUploading(true)
    setProgress(0)
    setUploadResult(null)

    try {
      const doc = await uploadDocument(file, (p) => setProgress(p))
      setUploadResult({ type: 'success', message: `"${doc.filename}" 上传成功，共 ${doc.chunk_count} 个文档块` })
      onUploadSuccess?.(doc)
    } catch (err: any) {
      const msg = err?.response?.data?.detail || err?.message || '上传失败'
      setUploadResult({ type: 'error', message: msg })
    } finally {
      setIsUploading(false)
    }
  }, [maxSizeMB, onUploadSuccess])

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setIsDragging(false)
    const file = e.dataTransfer.files[0]
    if (file) handleFile(file)
  }, [handleFile])

  const handleChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (file) handleFile(file)
    if (inputRef.current) inputRef.current.value = ''
  }, [handleFile])

  return (
    <div className="space-y-3">
      {/* Drop zone */}
      <div
        onDragOver={(e) => { e.preventDefault(); setIsDragging(true) }}
        onDragLeave={() => setIsDragging(false)}
        onDrop={handleDrop}
        onClick={() => !isUploading && inputRef.current?.click()}
        className={clsx(
          'relative border-2 border-dashed rounded-xl p-6 text-center cursor-pointer transition-all duration-200',
          isDragging
            ? 'border-primary-500 bg-primary-50 dark:bg-primary-950/30'
            : 'border-neutral-300 dark:border-neutral-600 hover:border-primary-400 hover:bg-neutral-50 dark:hover:bg-neutral-800/50',
          isUploading && 'pointer-events-none opacity-60',
        )}
      >
        <input
          ref={inputRef}
          type="file"
          accept={ACCEPTED_TYPES}
          onChange={handleChange}
          className="hidden"
          aria-label="选择文档文件"
        />

        {isUploading ? (
          <div className="space-y-2">
            <Loader2 className="w-8 h-8 mx-auto text-primary-500 animate-spin" />
            <p className="text-sm text-[var(--text-secondary)]">正在上传并解析...</p>
            <div className="w-full max-w-xs mx-auto bg-neutral-200 dark:bg-neutral-700 rounded-full h-1.5">
              <div
                className="bg-primary-500 h-1.5 rounded-full transition-all duration-300"
                style={{ width: `${progress}%` }}
              />
            </div>
            <p className="text-xs text-[var(--text-muted)]">{progress}%</p>
          </div>
        ) : (
          <div className="space-y-2">
            <Upload className="w-8 h-8 mx-auto text-[var(--text-muted)]" />
            <p className="text-sm text-[var(--text-secondary)]">
              拖拽文件到此处，或 <span className="text-primary-500">点击选择</span>
            </p>
            <p className="text-xs text-[var(--text-muted)]">
              支持 {ACCEPTED_TYPES_LABEL} 格式，单文件最大 {maxSizeMB}MB
            </p>
          </div>
        )}
      </div>

      {/* Result message */}
      {uploadResult && (
        <div className={clsx(
          'flex items-start gap-2 p-3 rounded-lg text-sm',
          uploadResult.type === 'success'
            ? 'bg-success-50 dark:bg-success-950/30 text-success-700 dark:text-success-600'
            : 'bg-error-50 dark:bg-error-950/30 text-error-700 dark:text-error-600',
        )}>
          {uploadResult.type === 'success'
            ? <CheckCircle className="w-4 h-4 mt-0.5 shrink-0" />
            : <AlertCircle className="w-4 h-4 mt-0.5 shrink-0" />
          }
          <p className="flex-1">{uploadResult.message}</p>
          <button onClick={() => setUploadResult(null)} className="shrink-0 hover:opacity-70">
            <X className="w-4 h-4" />
          </button>
        </div>
      )}
    </div>
  )
}

