import { useMemo, useState, useEffect } from 'react'
import DOMPurify from 'dompurify'
import { sanitizeHtml, sanitizeHtmlAsync } from '@/components/ai/features/utils/sanitize'

interface MarkdownBlock {
  type: string
  content: string
}

const FIELD_KEYWORDS = ['配方名称', '配方定位', '剂型', '功能主治', '主要原料', '辅料', '配方', '用量', '用法', '注意事项', '保质期', '储存条件', '执行标准', '生产企业']

function parseContent(content: string): MarkdownBlock[] {
  const blocks: MarkdownBlock[] = []
  const lines = content.split('\n')
  let currentBlock: MarkdownBlock | null = null
  let tableRows: string[] = []
  let inTable = false

  const flushTable = () => {
    if (tableRows.length > 0) {
      blocks.push({ type: 'table', content: tableRows.join('\n') })
      tableRows = []
    }
    inTable = false
  }

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    if (!line) continue

    if (typeof line === 'string' && (/^\|.*\|$/.exec(line))) {
      if (!inTable) {
        if (currentBlock) { blocks.push(currentBlock); currentBlock = null }
        inTable = true
      }
      if (typeof line === 'string' && !(/^\|[\s\-:|]+\|$/.exec(line))) {
        tableRows.push(line)
      }
      continue
    } else if (inTable) {
      flushTable()
    }

    if (line.trim() === '---') {
      if (currentBlock) { blocks.push(currentBlock); currentBlock = null }
      blocks.push({ type: 'separator', content: '' })
    } else if (line.startsWith('# ')) {
      if (currentBlock) { blocks.push(currentBlock); currentBlock = null }
      blocks.push({ type: 'h1', content: line.slice(2) })
    } else if (line.startsWith('## ')) {
      if (currentBlock) { blocks.push(currentBlock); currentBlock = null }
      blocks.push({ type: 'h2', content: line.slice(3) })
    } else if (line.startsWith('### ')) {
      if (currentBlock) { blocks.push(currentBlock); currentBlock = null }
      blocks.push({ type: 'h3', content: line.slice(4) })
    } else if (line.startsWith('#### ')) {
      if (currentBlock) { blocks.push(currentBlock); currentBlock = null }
      blocks.push({ type: 'h4', content: line.slice(5) })
    } else if (line.startsWith('> ')) {
      if (currentBlock && currentBlock.type !== 'quote') {
        if (currentBlock.type !== 'table') blocks.push(currentBlock)
        currentBlock = null
      }
      if (!currentBlock) currentBlock = { type: 'quote', content: '' }
      currentBlock.content += (currentBlock.content ? '\n' : '') + line.slice(2)
    } else if (typeof line === 'string' && ((/^[-*] /.exec(line)) || (/^\d+\. /.exec(line)))) {
      if (currentBlock && currentBlock.type !== 'list') {
        if (currentBlock.type !== 'table') blocks.push(currentBlock)
        currentBlock = null
      }
      if (!currentBlock) currentBlock = { type: 'list', content: '' }
      currentBlock.content += (currentBlock.content ? '\n' : '') + line
    } else if (line.trim()) {
      if (currentBlock && currentBlock.type !== 'paragraph') {
        blocks.push(currentBlock)
        currentBlock = null
      }
      if (!currentBlock) currentBlock = { type: 'paragraph', content: '' }
      currentBlock.content += (currentBlock.content ? ' ' : '') + line
    } else if (currentBlock?.type === 'paragraph') {
      blocks.push(currentBlock)
      currentBlock = null
    }
  }

  if (currentBlock) {
    if (currentBlock.type !== 'table') blocks.push(currentBlock)
  }
  if (inTable) flushTable()

  return blocks
}

function renderInline(text: string): string {
  const escapedText = text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')

  return escapedText
    .replace(/\*\*(.+?)\*\*/g, '<strong class="font-semibold text-neutral-900 dark:text-neutral-100">$1</strong>')
    .replace(/\*(.+?)\*/g, '<em class="italic">$1</em>')
    .replace(/`([^`]+)`/g, '<code class="bg-neutral-100 dark:bg-neutral-800 text-primary-700 dark:text-primary-700 px-1 py-0.5 rounded text-xs font-mono">$1</code>')
}

function renderTable(tableContent: string): string {
  const rows = tableContent.split('\n').filter(r => r.trim())
  if (rows.length < 2) return DOMPurify.sanitize(tableContent)

  const parseCells = (row: string) => row.split('|').slice(1, -1).map(c => c.trim())

  const headerCells = parseCells(rows[0] ?? '')
  const bodyRows = rows.slice(1)

  const hasRoleColumn = headerCells.some(h => /角色|组分类型|组方位置/i.test(h))

  let html = '<div class="overflow-x-auto my-4 rounded-lg border border-neutral-200 dark:border-neutral-700 shadow-sm bg-white dark:bg-neutral-800">'
  html += '<table class="w-full border-collapse min-w-[600px] md:min-w-0">'
  html += '<thead><tr class="bg-gradient-to-r from-primary-50 to-primary-100 dark:from-primary-900/40 dark:to-primary-800/30">'
  headerCells.forEach((cell, idx) => {
    const isCenter = /组分类型|角色|用量|单袋用量|100份用量|作用定位|核心依据/i.test(cell)
    const isSticky = idx === 0 && hasRoleColumn
    html += `<th class="px-3 py-3.5 ${isCenter ? 'text-center' : 'text-left'} text-xs font-bold text-primary-800 dark:text-primary-200 border-b-2 border-primary-300 dark:border-primary-600 tracking-wide uppercase ${isSticky ? 'sticky left-0 bg-primary-100/90 dark:bg-primary-300/40 z-10' : ''}">${renderInline(cell)}</th>`
  })
  html += '</tr></thead><tbody>'
  bodyRows.forEach((row, idx) => {
    const cells = parseCells(row)
    const zebraClass = idx % 2 === 0 ? 'bg-white dark:bg-neutral-800' : 'bg-neutral-50/70 dark:bg-neutral-900/30'
    html += `<tr class="${zebraClass} hover:bg-primary-50/40 dark:hover:bg-primary-900/20 transition-colors duration-150">`
    cells.forEach((cell, cIdx) => {
      const isCenter = cIdx === 0 || /用量|剂量/.test(headerCells[cIdx] ?? '')
      const isSticky = cIdx === 0 && hasRoleColumn
      const isHighlight = /君|臣|佐|使/i.test(cell)
      const cellClass = isHighlight
        ? 'font-semibold text-primary-700 dark:text-primary-700'
        : 'text-neutral-700 dark:text-neutral-300'
      const bgClass = isHighlight ? 'bg-primary-50/50 dark:bg-primary-300/20' : ''
      html += `<td class="px-3 py-2.5 text-sm ${isCenter ? 'text-center' : 'text-left'} ${cellClass} ${bgClass} ${cIdx < cells.length - 1 ? 'border-r border-neutral-100 dark:border-neutral-700/50' : ''} ${isSticky ? 'sticky left-0 z-10 ' + zebraClass : ''}">${renderInline(cell)}</td>`
    })
    html += '</tr>'
  })
  html += '</tbody></table></div>'
  return html
}

function isFieldLine(text: string): { isField: boolean; fieldName: string; fieldValue: string } {
  for (const kw of FIELD_KEYWORDS) {
    if (text.startsWith(kw) && text.length > kw.length) {
      const rest = text.slice(kw.length).trim()
      if (rest.startsWith(':') || rest.startsWith('：') || rest.startsWith('-') || rest.startsWith('—')) {
        return { isField: true, fieldName: kw, fieldValue: rest.slice(1).trim() }
      }
    }
  }
  return { isField: false, fieldName: '', fieldValue: '' }
}

export interface SimpleMarkdownProps {
  content: string
  className?: string
}

export function SimpleMarkdown({ content, className = '' }: SimpleMarkdownProps) {
  const blocks = useMemo(() => parseContent(typeof content === 'string' ? content : ''), [content])

  const rawHtml = useMemo(() => {
    return blocks.map((block) => {
      switch (block.type) {
        case 'h1':
          return `<h1 class="text-[26px] font-bold text-neutral-900 dark:text-neutral-100 pb-3 mb-4 border-b-2 border-primary-200 dark:border-primary-800 leading-tight">${renderInline(block.content)}</h1>`
        case 'h2':
          return `<h2 class="text-[20px] font-bold text-neutral-900 dark:text-neutral-100 mt-6 mb-3 pl-3 border-l-4 border-primary-500 leading-snug">${renderInline(block.content)}</h2>`
        case 'h3':
          return `<h3 class="text-[16px] font-bold text-neutral-800 dark:text-neutral-200 mt-4 mb-2 leading-snug">${renderInline(block.content)}</h3>`
        case 'h4':
          return `<h4 class="text-[14px] font-medium text-neutral-700 dark:text-neutral-300 mt-3 mb-1 leading-snug">${renderInline(block.content)}</h4>`
        case 'separator':
          return `<div class="my-5 border-t-2 border-dashed border-neutral-200 dark:border-neutral-700"></div>`
        case 'quote':
          return `<blockquote class="my-3 pl-4 pr-3 py-2 border-l-4 border-primary-400 bg-primary-50/50 dark:bg-primary-300/15 rounded-r-lg italic text-neutral-700 dark:text-neutral-300 text-sm leading-relaxed">${renderInline(block.content.replace(/\n/g, '<br />'))}</blockquote>`
        case 'table':
          return renderTable(block.content)
        case 'list': {
          const items = block.content.split('\n')
          const listClass = /^\d/.exec(items[0]) ? 'list-decimal' : 'list-disc'
          const listItems = items.map(item => {
            const text = item.replace(/^[-*] /, '').replace(/^\d+\. /, '')
            return `<li class="ml-6 mb-1 text-neutral-700 dark:text-neutral-300 leading-relaxed">${renderInline(text)}</li>`
          }).join('')
          return `<ul class="my-3 space-y-1 ${listClass} text-sm">${listItems}</ul>`
        }
        case 'paragraph': {
          const field = isFieldLine(block.content)
          if (field.isField) {
            return `<div class="my-3 p-3 bg-neutral-50 dark:bg-neutral-800/50 rounded-lg border border-neutral-100 dark:border-neutral-700/50">
              <span class="text-sm font-semibold text-primary-700 dark:text-primary-700">${field.fieldName}</span>
              <span class="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mx-1">:</span>
              <span class="text-sm text-neutral-800 dark:text-neutral-200">${renderInline(field.fieldValue)}</span>
            </div>`
          }
          return `<p class="my-3 text-sm text-neutral-700 dark:text-neutral-300 leading-[1.7]">${renderInline(block.content)}</p>`
        }
        default:
          return ''
      }
    }).join('')
  }, [blocks])

  const [sanitizedHtml, setSanitizedHtml] = useState<string>('')
  const [isSanitizing, setIsSanitizing] = useState(false)

  useEffect(() => {
    let isMounted = true

    async function performSanitization() {
      if (!rawHtml) {
        setSanitizedHtml('')
        return
      }

      setIsSanitizing(true)

      try {
        const result = await sanitizeHtmlAsync(rawHtml)

        if (isMounted) {
          setSanitizedHtml(result)
        }
      } catch (error) {
        if (isMounted) {
          const fallbackResult = sanitizeHtml(rawHtml)
          setSanitizedHtml(fallbackResult)
        }
      } finally {
        if (isMounted) {
          setIsSanitizing(false)
        }
      }
    }

    performSanitization()

    return () => {
      isMounted = false
    }
  }, [rawHtml])

  if (isSanitizing && !sanitizedHtml) {
    return (
      <div className={`animate-pulse bg-neutral-100 dark:bg-neutral-800 rounded-lg h-32 ${className}`} />
    )
  }

  // 🔒 P0 安全修复: 确保 sanitizedHtml 存在才渲染
  // 消毒失败时返回安全的占位符，绝不回退到未消毒的 rawHtml
  if (!sanitizedHtml) {
    // 消毒失败时返回安全占位符，不显示可能包含恶意脚本的内容
    return (
      <div className={`text-sm leading-[1.7] space-y-1 ${className}`}>
        <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] italic">[内容已过滤]</span>
      </div>
    )
  }

  return (
    <div
      className={`text-sm leading-[1.7] space-y-1 ${className}`}
      dangerouslySetInnerHTML={{ __html: sanitizedHtml }}
    />
  )
}

/**
 * FlavorWheel - 五味风味轮可视化组件
 *
 * 基于 SVG 的交互式六边形风味轮
 * 用于展示配方的五味分布特征
 *
 * 技术栈：React + TypeScript + SVG
 * 设计原则：简洁优先、性能优化、可访问性
 */

import React, { useMemo, useState, useCallback } from 'react'
import { Tooltip } from 'recharts'
import {
  FIVE_TASTES_LABELS,
  FIVE_TASTES_COLORS,
} from '@/types/taste.types'
import { FiveTastes } from '@/types/taste.types'
import type {
  TasteProfile,
} from '@/types/taste.types'

interface FlavorWheelProps {
  /** 口感数据 */
  data: TasteProfile
  /** 尺寸大小 (px) */
  size?: number
  /** 是否显示动画 */
  animated?: boolean
  /** 自定义类名 */
  className?: string
  /** 悬停回调 */
  onHover?: (taste: FiveTastes | null, value: number) => void
}

/** 扇区配置接口 */
interface SectorConfig {
  taste: FiveTastes
  label: string
  color: string
  startAngle: number
  endAngle: number
}

const WHEEL_SIZE = 300
const INNER_RADIUS = 60
const OUTER_RADIUS = 140

export function FlavorWheel({
  data,
  size = WHEEL_SIZE,
  animated = true,
  className = '',
  onHover,
}: FlavorWheelProps) {
  const [hoveredTaste, setHoveredTaste] = useState<FiveTastes | null>(null)

  const center = size / 2
  const radius = (size / 2) - 20
  const innerRadius = (radius * INNER_RADIUS) / OUTER_RADIUS

  const sectors = useMemo<SectorConfig[]>(() => {
    const tasteKeys = Object.values(FiveTastes)
    const angleStep = (Math.PI * 2) / tasteKeys.length

    return tasteKeys.map((taste, index) => ({
      taste,
      label: FIVE_TASTES_LABELS[taste],
      color: FIVE_TASTES_COLORS[taste],
      startAngle: index * angleStep - Math.PI / 2,
      endAngle: (index + 1) * angleStep - Math.PI / 2,
    }))
  }, [])

  const maxIntensity = useMemo(() => {
    return Math.max(...Object.values(data), 100)
  }, [data])

  const handleMouseEnter = useCallback(
    (taste: FiveTastes, value: number) => {
      setHoveredTaste(taste)
      onHover?.(taste, value)
    },
    [onHover],
  )

  const handleMouseLeave = useCallback(() => {
    setHoveredTaste(null)
    onHover?.(null, 0)
  }, [onHover])

  const createArcPath = (
    cx: number,
    cy: number,
    r: number,
    startAngle: number,
    endAngle: number,
  ): string => {
    const startX = cx + r * Math.cos(startAngle)
    const startY = cy + r * Math.sin(startAngle)
    const endX = cx + r * Math.cos(endAngle)
    const endY = cy + r * Math.sin(endAngle)
    const largeArcFlag = endAngle - startAngle > Math.PI ? 1 : 0

    return [
      'M', cx, cy,
      'L', startX, startY,
      'A', r, r, 0, largeArcFlag, 1, endX, endY,
      'Z',
    ].join(' ')
  }

  const getLabelPosition = (sector: SectorConfig): { x: number; y: number } => {
    const midAngle = (sector.startAngle + sector.endAngle) / 2
    const labelRadius = radius + 25
    return {
      x: center + labelRadius * Math.cos(midAngle),
      y: center + labelRadius * Math.sin(midAngle),
    }
  }

  const getValuePosition = (sector: SectorConfig): { x: number; y: number } => {
    const midAngle = (sector.startAngle + sector.endAngle) / 2
    const valueRadius = innerRadius + (radius - innerRadius) * 0.6
    return {
      x: center + valueRadius * Math.cos(midAngle),
      y: center + valueRadius * Math.sin(midAngle),
    }
  }

  return (
    <div
      className={`relative inline-flex items-center justify-center ${className}`}
      style={{ width: size, height: size }}
    >
      <svg
        width={size}
        height={size}
        viewBox={`0 0 ${size} ${size}`}
        className="overflow-visible"
        role="img"
        aria-label="五味分布风味轮"
      >
        {/* 背景圆 */}
        <circle
          cx={center}
          cy={center}
          r={radius}
          fill="#f8f9fa"
          stroke="#e9ecef"
          strokeWidth={2}
          className="dark:fill-neutral-800 dark:stroke-neutral-700"
        />

        {/* 六个扇区 */}
        {sectors.map((sector) => {
          const intensity = data[sector.taste] || 0
          const normalizedIntensity = intensity / maxIntensity
          const sectorRadius = innerRadius + (radius - innerRadius) * normalizedIntensity

          if (normalizedIntensity < 0.02) return null

          const path = createArcPath(
            center,
            center,
            sectorRadius,
            sector.startAngle,
            sector.endAngle,
          )

          const isHovered = hoveredTaste === sector.taste

          return (
            <g key={sector.taste}>
              {/* 扇区填充 */}
              <path
                d={path}
                fill={sector.color}
                opacity={isHovered ? 1 : 0.8}
                stroke="white"
                strokeWidth={isHovered ? 3 : 1.5}
                className={`transition-all duration-200 ${
                  animated ? 'animate-pulse-once' : ''
                }`}
                style={{
                  transformOrigin: `${center}px ${center}px`,
                  cursor: 'pointer',
                }}
                onMouseEnter={() =>
                  handleMouseEnter(sector.taste, intensity)
                }
                onMouseLeave={handleMouseLeave}
              />

              {/* 强度数值标签 */}
              {normalizedIntensity > 0.15 && (() => {
                const pos = getValuePosition(sector)
                return (
                  <text
                    x={pos.x}
                    y={pos.y}
                    textAnchor="middle"
                    dominantBaseline="middle"
                    className={`text-xs font-bold select-none ${
                      isHovered ? 'fill-white' : 'fill-white'
                    }`}
                    style={{
                      textShadow: isHovered
                        ? '0 1px 3px rgba(0,0,0,0.5)'
                        : 'none',
                    }}
                  >
                    {intensity.toFixed(0)}
                  </text>
                )
              })()}
            </g>
          )
        })}

        {/* 中心圆 */}
        <circle
          cx={center}
          cy={center}
          r={innerRadius}
          fill="white"
          stroke="#e9ecef"
          strokeWidth={2}
          className="dark:fill-neutral-900 dark:stroke-neutral-700"
        />

        {/* 中心文字 */}
        <text
          x={center}
          y={center - 10}
          textAnchor="middle"
          dominantBaseline="middle"
          className="text-sm font-bold fill-neutral-700 dark:fill-neutral-300"
        >
          综合评分
        </text>
        <text
          x={center}
          y={center + 15}
          textAnchor="middle"
          dominantBaseline="middle"
          className="text-2xl font-bold fill-secondary-600 dark:fill-secondary-400"
        >
          {calculateBalanceScore(data).toFixed(1)}
        </text>

        {/* 外围标签 */}
        {sectors.map((sector) => {
          const pos = getLabelPosition(sector)
          const isHovered = hoveredTaste === sector.taste

          return (
            <g key={`label-${sector.taste}`}>
              <text
                x={pos.x}
                y={pos.y}
                textAnchor="middle"
                dominantBaseline="middle"
                className={`text-sm font-medium transition-all duration-200 ${
                  isHovered
                    ? 'font-bold scale-110'
                    : ''
                }`}
                fill={sector.color}
                style={{
                  fontSize: isHovered ? '16px' : '14px',
                  transition: 'all 0.2s ease',
                }}
              >
                {sector.label}
              </text>
            </g>
          )
        })}
      </svg>

      {/* 悬停提示框 */}
      {hoveredTaste && (
        <div
          className="absolute top-2 left-1/2 -translate-x-1/2 bg-white dark:bg-neutral-800
                     px-4 py-2 rounded-lg shadow-lg border border-neutral-200 dark:border-neutral-700
                     z-10 animate-fade-in pointer-events-none"
        >
          <div className="flex items-center gap-2">
            <div
              className="w-3 h-3 rounded-full"
              style={{ backgroundColor: FIVE_TASTES_COLORS[hoveredTaste] }}
            />
            <span className="font-semibold text-neutral-900 dark:text-neutral-100">
              {FIVE_TASTES_LABELS[hoveredTaste]}
            </span>
            <span className="text-neutral-600 dark:text-neutral-400">
              {data[hoveredTaste]?.toFixed(1) || 0}
            </span>
          </div>
        </div>
      )}
    </div>
  )
}

function calculateBalanceScore(profile: TasteProfile): number {
  const values = Object.values(profile)
  const sum = values.reduce((a, b) => a + b, 0)

  if (sum === 0) return 0

  const mean = sum / values.length
  const variance =
    values.reduce((acc, val) => acc + Math.pow(val - mean, 2), 0) /
    values.length
  const stdDev = Math.sqrt(variance)

  const coefficientOfVariation = stdDev / mean
  const balanceScore = Math.max(0, 1 - coefficientOfVariation)

  return balanceScore
}

export default FlavorWheel

/**
 * TasteRadarChart - 五味雷达图可视化组件
 *
 * 基于 Recharts 的专业级五味分布对比图表
 * 支持多数据系列、交互式工具提示、响应式布局
 */

import React, { useMemo } from 'react'
import {
  Radar,
  RadarChart as RechartsRadarChart,
  PolarGrid,
  PolarAngleAxis,
  PolarRadiusAxis,
  ResponsiveContainer,
  Tooltip,
  Legend,
} from 'recharts'
import {
  FIVE_TASTES_LABELS,
} from '@/types/taste.types'
import { FiveTastes } from '@/types/taste.types'
import type {
  TasteProfile,
} from '@/types/taste.types'

interface TasteRadarChartProps {
  /** 主数据（当前配方） */
  primaryData: TasteProfile
  /** 对比数据（可选，如标准配方/历史记录） */
  comparisonData?: {
    label: string
    data: TasteProfile
    color?: string
  }[]
  /** 图表尺寸 */
  width?: number
  height?: number
  /** 是否显示网格 */
  showGrid?: boolean
  /** 自定义类名 */
  className?: string
}

interface RadarDataPoint {
  taste: string
  label: string
  primary: number
  comparison1?: number
  comparison2?: number
}

const DEFAULT_COLORS = [
  'var(--color-secondary-500)',
  'var(--color-primary-400)',
  '#D97706',
  '#FF3B30',
  'var(--color-accent-500)',
]

export function TasteRadarChart({
  primaryData,
  comparisonData = [],
  width = 500,
  height = 400,
  showGrid = true,
  className = '',
}: TasteRadarChartProps) {
  const chartData = useMemo<RadarDataPoint[]>(() => {
    const tasteKeys = Object.values(FiveTastes) as FiveTastes[]

    return tasteKeys.map((taste) => {
      const point: RadarDataPoint = {
        taste,
        label: FIVE_TASTES_LABELS[taste],
        primary: primaryData[taste] || 0,
      }

      if (comparisonData.length > 0) {
        point.comparison1 = comparisonData[0]?.data[taste] || 0
      }
      if (comparisonData.length > 1) {
        point.comparison2 = comparisonData[1]?.data[taste] || 0
      }

      return point
    })
  }, [primaryData, comparisonData])

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload?.length) {
      return (
        <div className="bg-white dark:bg-neutral-800 p-3 rounded-lg shadow-xl border
                       border-neutral-200 dark:border-neutral-700 text-sm">
          <p className="font-bold text-neutral-900 dark:text-neutral-100 mb-2">
            {label}
          </p>
          {payload.map((entry: any, index: number) => (
            <p key={index} style={{ color: entry.color }} className="flex items-center gap-2">
              <span className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color }} />
              <span>{entry.name}:</span>
              <span className="font-semibold">{entry.value.toFixed(1)}</span>
            </p>
          ))}
        </div>
      )
    }
    return null
  }

  return (
    <div className={`w-full ${className}`} style={{ width: width || '100%', height }}>
      <ResponsiveContainer width="100%" height="100%">
        <RechartsRadarChart
          cx="50%"
          cy="50%"
          outerRadius="75%"
          data={chartData}
        >
          {showGrid && (
            <PolarGrid
              stroke="#e5e7eb"
              className="dark:stroke-neutral-700"
            />
          )}

          <PolarAngleAxis
            dataKey="label"
            tick={{
              fill: '#6b7280',
              fontSize: 13,
              fontWeight: 500,
            }}
            className="dark:text-neutral-400"
          />

          <PolarRadiusAxis
            angle={30}
            domain={[0, 100]}
            tick={{
              fill: '#9ca3af',
              fontSize: 12,
            }}
            axisLine={false}
            className="dark:text-neutral-400"
          />

          {/* 主数据 */}
          <Radar
            name="当前配方"
            dataKey="primary"
            stroke="var(--color-secondary-500)"
            fill="var(--color-secondary-500)"
            fillOpacity={0.25}
            strokeWidth={2.5}
            dot={{ r: 4, fill: 'var(--color-secondary-500)', strokeWidth: 2 }}
          />

          {/* 对比数据 1 */}
          {comparisonData.length > 0 && (
            <Radar
              name={comparisonData[0].label || '对比 1'}
              dataKey="comparison1"
              stroke={comparisonData[0].color || DEFAULT_COLORS[1]}
              fill={comparisonData[0].color || DEFAULT_COLORS[1]}
              fillOpacity={0.15}
              strokeWidth={2}
              strokeDasharray="5 5"
              dot={{ r: 3 }}
            />
          )}

          {/* 对比数据 2 */}
          {comparisonData.length > 1 && (
            <Radar
              name={comparisonData[1].label || '对比 2'}
              dataKey="comparison2"
              stroke={comparisonData[1].color || DEFAULT_COLORS[2]}
              fill={comparisonData[1].color || DEFAULT_COLORS[2]}
              fillOpacity={0.1}
              strokeWidth={2}
              strokeDasharray="10 5"
              dot={{ r: 3 }}
            />
          )}

          {/* eslint-disable-next-line react-hooks/static-components */}
          <Tooltip content={<CustomTooltip />} />

          {(comparisonData.length > 0) && (
            <Legend
              wrapperStyle={{
                paddingTop: '20px',
                fontSize: '13px',
              }}
            />
          )}
        </RechartsRadarChart>
      </ResponsiveContainer>
    </div>
  )
}

export default TasteRadarChart
